SELECT 'moj-all-verified-judgments-review-002-chunk-188' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"90a05577-e72d-5f91-9e28-7fb1aa92484c","document_type":"judgment","category":"judicial","subcategory":"general","title":"هبة -هدية زوج -اإلهداء بعد عقد النكاح وقبل الدخول -طلب الزوج إعادة الهدايا -جرى العرف أن ما يهديه الزوج لزوجته قبل الدخول هو من قبيل الهدية -العادة محكمة -حلف اليمن على أن الهدية ليست بنية االرجاع -احلكم بصرف النظر عن دعوى املدعي وإخاء سبيل املدعى عليها .","document_number":"34198975","case_number":"33309200","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/27","year":"1434","subject":"هبة -هدية زوج -اإلهداء بعد عقد النكاح وقبل الدخول -طلب الزوج إعادة الهدايا -جرى العرف أن ما يهديه الزوج لزوجته قبل الدخول هو من قبيل الهدية -العادة محكمة -حلف اليمن على أن الهدية ليست بنية االرجاع -احلكم بصرف النظر عن دعوى املدعي وإخاء سبيل املدعى عليها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34198975 :‬تاريخه ‪1434/4/27 :‬هـ‬\n                        ‫رقم الدعوى‪33309200 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34240178‬تاريخه ‪1434/6/13:‬هـ‬\n\n\n      ‫هبــة ‪ -‬هديــة زوج ‪ -‬اإلهــداء بعــد عقــد النــكاح وقبــل الدخــول ‪ -‬طلــب‬\n      ‫الــزوج إعــادة الهدايــا ‪ -‬جــرى العــرف أن مــا يهديــه الــزوج لزوجتــه قبــل‬\n      ‫الدخــول هــو مــن قبيــل الهديــة ‪ -‬العــادة محكمــة ‪ -‬حلــف اليمــن علــى‬\n      ‫أن الهديــة ليســت بنيــة االرجــاع ‪ -‬احلكــم بصــرف النظــر عــن دعــوى‬\n                                          ‫املدعــي وإخــاء ســبيل املدعــى عليهــا ‪.‬‬\n\n\n\n      ‫‪ -‬قولــه صلــى اهلل عليــه وســلم ‪ ( :‬البنيــة علــى املدعــي واليمــن علــى‬\n                                                                     ‫مــن أنكــر ) ‪.‬‬\n                                        ‫‪ -‬القاعدة الفقهية ( العادة محكمة ) ‪.‬‬\n\n\n\n      ‫حضــر املدعــي وادعــى بأنــه مت عقــد نكاحــه علــى موكلــة املدعــى‬\n      ‫عليــه علــى مهــر وقــدره ثالثــون ألــف ريــال وقــدم لهــا ‪ 4‬أطقــم ذهــب‬\n      ‫مببلــغ ‪ 38150‬ريــال و ‪ 2‬ســاعة رجالــي بقيمــة ‪ 1230‬ريــال وأســورة بقيمــة‬\n      ‫‪ 3229‬وسلســلة بقيمــة ‪ 820‬ريــال وسلســلة تلبيســه بقيمــة ‪ 2100‬ريــال‬\n      ‫ودبلــة أملــاس ســوليتر بقيمــة ‪ 4200‬ريــال ليتــم اختيــار طقــم واحــد مــن‬\n      ‫قبــل املدعــى عليهــا لتناســب فســتانها ثــم تقــوم بإرجــاع الباقــي لتقدميــه‬\n      ‫بعــد الــزواج كاملعتــاد وقــد اســتلمها أخوهــا املدعــى عليــه وكالــة‬\n\n‫‪265‬‬\n\f‫وعنــد مطالبتــه لألغــراض ألن معظمهــا ألهلــه رفضــت املدعيــة وبــدأت‬\n‫بافتعــال املشــاكل وطلبــت فســخ النــكاح ويطلــب إعــادة كل مــا ذكــر‬\n‫وأمــا طقــم الذهــب الرابــع والــذي قيمتــه ‪ 9450‬ريــال فــا مانــع أن يبقــى‬\n‫معهــا حســب العــرف حتــى يــرى هــل يتــم الــزواج أم ال ـ وبعــرض دعــوى‬\n‫املدعــي علــى املدعــى عليــه وكالــة طلــب صــورة مــن الدعــوى لعرضهــا‬\n‫علــى موكلتــه واإلجابــة عنهــا يف اجللســة الثانيــة ‪ .‬و يف جلســة أخــرى‬\n‫حضــر الطرفــان وبســؤال املدعــى عليــه وكالــة عــن جوابــه قــدم جواب ـ ًا‬\n‫محــرر ًا أشــير إليــه يف ضبــط القضيــة وممــا جــاء فيــه مصادقــة املــرأة‬\n‫علــى عقــد النــكاح وعلــى املهــر الــذي ذكــر وقــد خــا بهــا عــدة مــرات‬\n‫خلــوة شــرعية كامل ـةـ ومــا ذكــره بخصــوص تقــدمي األطقــم الذهبيــة‬\n‫واألســورة والسلســلة فــإن املدعــي لــم يحــرر فيهــا دعــواه وقــال إن‬\n‫معظمهــا ألهلــه فمــا هــو الــذي ألهلــه حتديــد ًا ـ مــا ذكــره مــن تســليمه‬\n‫األطقــم الذهبيــة والسلســلة وأســورة الختيــار مــا يناســبها وتعيــد الباقــي‬\n‫فهــذا غيــر صحيــح والصحيــح أنــه قدمهــا لهــا هديــة زوج لزوجتــه كمــا‬\n‫يف عــرف البــاد مــن غيــر طلــب منهــا ولــم يشــترط ذلــك عليــه ولــم تكــن‬\n‫مــن املهــر املســمى يف العقــد وقــد قــدم هــذه األغــراض تبرعـ ًا منــه وهبــة‬\n‫ملكتهــا املدعــى عليهــا بالقبــض بدليــل أن األنــواع مختلفــة ومســمياتها‬\n‫مختلفــة وليســت مــن جنــس واحــد الختيــار مــا يناســب الفســتان وهــذه‬\n‫األغــراض يف عــرف املجتمــع يقدمهــا الــزوج لزوجتــه هديــة زواج وتقديــر‬\n‫ولــو لــم يقدمهــا الــزوج لزوجتــه لــم يؤثــر هــذا يف زواجهــا وال يف عقــد‬\n‫النــكاح ولــن تعيدهــا لــه ـ وأمــا الســاعتني الرجاليــة فقــد ســلمها‬\n‫ألخيهــا املدعــى عليــه وكالــة هديــة منــه ألبيهــا وأخيهــا وقــد قبضاهــا‬\n‫وإذا كان لــه دعــوى فليقمهــا عليهمــا وال شــأن لهــا يف هــذه األغــراض‬\n\n\n                                                                                     ‫‪266‬‬\n\f      ‫ـ وبعــرض ذلــك علــى املدعــى أنكــر اختالئــه باملدعــى عليهــا واللقــاء‬\n      ‫يكــون بحضــرة أمهــا ـ وأمــا مــا ذكرتــه املــرأة بخصــوص األطقــم ألهــل‬\n      ‫املدعــي فيقصــد أن األطقــم منــه ولكــن املبلــغ املشــترى بهــا منــه ألمــه‬\n      ‫ومنــه ألختــه ـ ومــا ذكرتــه مــن كونــه هديــة زوج لزوجتــه فليــس بصحيح‬\n      ‫ـ ومــا ذكرتــه مــن كــون الســاعتني الرجاليــة التــي ســلمت ألخيهــا فهــذا‬\n      ‫صحيــح واألخــرى ســلمها املدعــي ضمــن مجموعــة ولــم يســلمها لوالدهــا‬\n      ‫ولكنهــا ليــس علــى ســبيل الهديــة ـ والتــي جــاء بهــا تلبيــة لطلبهــا لتراهــا‬\n      ‫قبــل موعدهــا ـ بســؤاله عــن بينتــه بــأن مــا قدمــه ممــا ادعــى بــه علــى‬\n      ‫نيــة الرجــوع بعــد مشــاهدته فقــط فأجــاب ليــس لديــه بينــه ولكــن‬\n      ‫العــرف يقتضــي مــا ذكــره يف دعــواه ـ جــرت الكتابــة لقســم اخلبــراء‬\n      ‫لإلفــادة عمــا لديهــم مــن العــرف اجلــاري والســائد يف مثــل هــذه احلالــة ـ‬\n      ‫جــاء اجلــواب مــن قســم اخلبــراء يتضمــن أن العــرف الســائد بــن النــاس‬\n      ‫أنــه إذا قــدم الرجــل ملخطوبتــه هديــة بــدون شــرط مــن املــرأة أو مــن‬\n      ‫أهلهــا فإنهــا يف هــذه احلالــة تعتبــر هديــة هــذا هــو العــرف الســائد ـ وأنــه‬\n      ‫قدمهــا قبــل الــزواج وهــذا دليــل علــى أنــه قدمــه ترغيبـ ًا لهــا يف الــزواج ‪-‬‬\n      ‫بعــرض ذلــك علــى املدعــي قــرر أنــه لــم يقدمــه علــى أنــه هديــة ـ مت إفهــام‬\n      ‫املدعــي بأنــه ليــس لــه إال ميــن املدعــى عليهــا ـ يف جلســة أخــرى حضــرت‬\n      ‫املدعــى عليهــا أصالــة ولــم يحضــر املدعــي رغــم معرفتــه باملوعــد ومت‬\n      ‫عــرض اليمــن عليهــا بعــد تخويفهــا بــاهلل فاســتعدت فحلفــت اليمــن‬\n      ‫كمــا طلــب منهــا ‪ -‬نظــر ًا إلنــكار املدعــى عليهــا وعــدم وجــود بينــة‬\n      ‫للمدعــي وألداء املدعــى عليهــا اليمــن و لقولــه صلــى اهلل عليــه وســلم‬\n      ‫( البينــة علــى املدعــي واليمــن علــى مــن أنكــر ) وللقاعــدة الفقهيــة (‬\n      ‫العــادة محكمــة ) ـ صــدر احلكــم بصــرف النظــر عــن دعــوى املدعــي‬\n\n\n‫‪267‬‬\n\f‫وإخــاء ســبيل املدعــى عليهــا مــن هــذه الدعــوى ـ ـ قــررت املدعــى عليهــا‬\n‫القناعــة ـ مت بعــث نســخة مــن احلكــم للمدعــي لتقــدمي اعتراضــه خــال‬\n‫املــدة النظاميــة وإفهامــه أنــه يف حالــة عــدم تقــدمي اعتراضــه يكتســب‬\n        ‫احلكــم القطعيــة ‪ .‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة باملدينــة املنورة‪/‬املســاعد برقــم ‪ 33309200‬وتاريــخ‬\n‫‪ 1433/05/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33840163‬وتاريــخ‬\n‫‪ 1433/05/03‬ه ـ ففــي يــوم األحــد املوافــق‪ 1433/05/23‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪08 : 52‬وفيهــا حضــر ‪ .......‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .......‬وحضــر حلضــوره ‪ .......‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .......‬مبوجــب الوكالــة رقــم ‪ .......‬وتاريــخ‬\n‫ا ‪ :‬قــد مت عقــد نكاحــي علــى املــرأة ‪.......‬‬‫‪1433/5/22‬ه ـ وادعــى قائـ ً‬\n‫بالعقــد رقــم ‪ .......‬وتاريــخ ‪1433/3/19‬ه ـ علــى مهــر وقــدره ثالثــون‬\n‫ألــف ريــال مت تســليمه وقدمــت لهــا ‪ 4‬أطقــم ذهــب بقيمــة ‪38150‬‬\n‫ريــال و‪ 2‬ســاعة رجالــي بقيمــة ‪1230‬ريــال وأســورة بقيمــة ‪3229‬ريــال‬\n‫وسلســلة بقيمــة ‪ 820‬ريــال وسلســلة تلبيســة بقيمــة‪ 2100‬ريــال ودبلــة‬\n‫أملــاس ســوليتيربقيمة‪ 4200‬ريــال ليتــم اختيــار طقــم واحــد مــن قبلهــا‬\n‫ليناســب فســتانها ثــم تقــوم بإرجــاع الباقــي لتقدميــه بعــد الــزواج كاملعتاد‬\n‫وقــد أســتلمها أخوهــا ‪ .......‬وعنــد مطالبتــي لألغــراض ألن معظمهــا‬\n\n                                                                                     ‫‪268‬‬\n\f      ‫ألهلــي رفضــت وبــدأت بافتعــال املشــاكل وطلبــت فســخ النــكاح لــذا‬\n      ‫أطلــب إعــادة كل مــا ذكــرت وأمــا طقــم الذهــب الرابــع الــذي قيمتــه‬\n      ‫تســعة آالف وأربــع مئــة وخمســون ريــا ًال فــا مانــع أن يبقــى معهــا حســب‬\n      ‫العــرف حتــى نــرى هــل يتــم الــزواج أم ال هكــذا ادعــى ‪ ،‬وبعــرض دعــواه‬\n      ‫علــى املدعــى عليــه وكالــة أجــاب ‪ :‬أطلــب صــورة مــن دعــوى املدعــى‬\n      ‫لعرضهــا علــى موكلتــي واإلجابــة عليهــا يف اجللســة القادمــة فجــرى‬\n      ‫تســليم املدعــى عليــه صــورة مــن دعــوى املدعــي ويف يــوم آخــر حضــر‬\n      ‫الطرفــان وبســؤال املدعــى عليــه وكالــة عــن جوابــه قدمــه مكتوب ـ ًا‬\n      ‫ونــص احلاجــة منــه ‪،‬أوال ‪ :‬مــا ذكــره مــن عقــد النــكاح بــي علــى املهــر‬\n      ‫الــذي ذكــر وقــدره ثالثــون ألــف ريــال فصحيــح أمــا مــا ذكــر مــن عــدم‬\n      ‫حصــول الدخــول بــي فصحيــح أيض ـ ًا إال أن املدعــي قــد خــا بــي عــدة‬\n                                                       ‫مــرات خلــوة شــرعية كاملــة‪.‬‬\n      ‫ثاني ـ ًا ‪ :‬مــا ذكــره مــن تقــدمي األطقــم الذهبيــة واألســورة والسلســة فــان‬\n      ‫املدعــي لــم يحــرر فيهــا دعــواه إذ قــال أن معظمهــا ألهلــه‪ ،‬فمــا هــو الــذي‬\n                                ‫ألهلــه منهــا حتديــد ًا حتــى يكــون اجلــواب مالقيـ ًا‬\n      ‫ثالثـ ًا ‪ :‬مــا ذكــره مــن تســليمه األطقــم الذهبيــة والسلســة وأســورة وأنهــا‬\n      ‫الختيــار مــا يناســبني وأعيــد الباقــي فهــذا غيــر صحيــح والصحيــح أنــه‬\n      ‫قدمهــا لــي هديــة زوج لزوجتــه كمــا هــو عــرف البــاد مــن غيــر طلــب‬\n      ‫منــي ولــم أشــترط ذلــك عليــه ولــم تكــن مــن املهــر املســمى بيننــا يف‬\n      ‫العقــد إذ إن املهــر محــدد يف عقــد النــكاح الشــرعي الــذي ذكــره‬\n      ‫يف دعــواه والشــيء ســواه وقــد قــدم هــذه األغــراض بطوعــه واختيــاره‬\n      ‫وتبــرع منــه وهبــة ملكتهــا بالقبــض وبدليــل أن األغــراض التــي ذكرهــا‬\n      ‫أنواعهــا مختلفــة ومســمياتها مختلفــة وليســت مــن جنــس واحــد حتــى‬\n\n\n‫‪269‬‬\n\f‫يتــم اختيــار مــا يناســب الفســتان كمــا يدعــي ويعــاد مــاال يناســبه وهــذه‬\n‫األغــراض التــي ذكــر يقدمهــا يف عــرف مجتمعنــا الــزوج لزوجتــه هديــة‬\n‫زواج وتقديــر ولــو لــم يقدمهــا الــزوج لزوجتــه لــم يؤثــر هــذا يف زواجهمــا‬\n            ‫وال يف عقــد النــكاح لــذا فــا حــق لــه فيهــا ولــن أعيدهــا لــه‪.‬‬\n‫رابع ـ ًا ‪ :‬أمــا مــا ذكــر مــن الســاعتني الرجاليــة فقــد ســلمها املدعــي‬\n‫ألخــي ‪ ...‬هديــة منــه ألبــي وأخــي وقــد قبضاهــا وإذا كان لــه دعــوى‬\n‫بهــا فليقمهــا عليهمــا وال شــأن لــي يف هــذا ‪ ،‬وبعــرض جوابهــا علــى‬\n‫املدعــي أجــاب ‪ :‬لــم أختــل بهــا وكل لقــاء تكــون أمهــا موجــودة ســوى‬\n‫مــرة خرجــت معــي يف الســيارة إلــى الســوق ومــا ذكرتــه مــن قولــي إن‬\n‫معظــم األطقــم ألهلــي فأقصــد أن األطقــم منــي ولكــن املبلــغ املشــترى‬\n‫بــه منــه مــا أعطتنــي إيــاه أمــي ومنــه مــا أعطتنــي إيــاه أختــي ومــا ذكرتــه‬\n‫مــن كونــه هديــه زوج لزوجتــه فليــس بصحيــح ومــا ذكرتــه مــن كــون‬\n‫الســاعتني الرجاليــة التــي ســلمت واحــدة ألخيهــا ‪ .......‬فهــذا صحيــح‬\n‫واألخــرى ســلمتها مــن ضمــن مجموعــة ولــم أســلمها ألبيهــا ولكنهمــا‬\n‫ليســا علــى ســبيل الهديــة وإمنــا الصحيــح إننــي أتيــت بــكل ذلــك تلبيــة‬\n‫لطلبهــا أن تراهــا قبــل موعدهــا وبســؤاله عــن بينتــه بــأن ماقدمــه ممــا‬\n‫ادعــى بــه علــى نيــة الرجــوع بــه بعــد مشــاهدته فقــط أجــاب ليــس لــدي‬\n‫بينــة ولكــن العــرف يقتضــي مــا ذكرته يف دعــواي ولذا قررت الكتابة‬\n‫لقســم اخلبــراء لإلفــادة عمــا لديهــم مــن العــرف اجلــاري والســائد يف مثــل‬\n‫هــذه احلالــة وقــد وردنــا خطــاب قســم اخلبــراء رقــم ‪ 33840163‬وتاريــخ‬\n‫‪1433/11/14‬ه ـ ونــص احلاجــة منــه (نفيدكــم أن العــرف الســائد بــن‬\n‫النــاس أنــه إذا قــدم الرجــل ملخطوبتــه هديــة بــدون شــرط مــن املــرأة أو‬\n‫مــن أهلهــا فإنهــا يف هــذه احلالــة تعتبــر هديــة ‪ ،‬هــذا هــو العــرف الســائد‬\n\n\n                                                                                         ‫‪270‬‬\n\f      ‫بــن النــاس حســب علمنــا خاصــة وأنــه قدمــه لهــا قبــل الــزواج وهــذا‬\n      ‫دليــل علــى أنــه قدمــه ترغيب ـ ًا لهــا يف قبــول الــزواج هــذا مــا ظهــر لنــا‬\n      ‫واهلل املوفــق) وبعــد تالوتــه عليهمــا قــرر املدعــي ‪ :‬أنــا لــم أقدمــه هديــة ‪،‬‬\n      ‫أفهمــت املدعــي بأنــه ليــس لــه إال ميــن املدعــى عليهــا إن طلبهــا ‪ ،‬فطلبهــا‬\n      ‫فأفهمــت املدعــى عليــه وكالــة بإحضــار موكلتــه ألداء اليمــن ففهــم‪،‬‬\n      ‫ويف يــوم الثالثــاء املوافــق‪ 1434/04/09‬هـ افتتحت اجللســة وفيها حضر‬\n      ‫املدعــي وانتهــى الوقــت احملــدد ولــم حتضــر املدعــى عليهــا ألداء اليمــن‬\n      ‫رغــم تبلغهــا عــن طريــق وكيلهــا حســب النظــام ‪ ،‬لــذا أمــرت بتبليــغ‬\n      ‫املدعــى عليهــا حلضــور يــوم الثالثــاء املوافــق ‪1434/4/23‬ه ـ الســاعة‬\n      ‫ال ‪،‬ويف يــوم الثالثــاء‬  ‫الواحــدة ظهــر ًا ألداء اليمــن وإال تعتبــر نــاك ً‬\n      ‫املوافــق ‪1434/4/23‬ه ـ افتتحــت اجللســة الســاعة الواحــدة ظهــر ًا وفيهــا‬\n      ‫حضــرت املدعــى عليهــا ‪ .......‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ .......‬ووكيلهــا املــدون هويتــه ســابق ًا ولــم يحضــر املدعــي رغــم‬\n      ‫معرفتــه باملوعــد ومت عــرض اليمــن عليهــا بعــد تخويفهــا بــاهلل تعالــى‬\n      ‫مــن مغبــة اليمــن الغمــوس فاســتعدت ثــم حلفــت قائلــة ‪ :‬واهلل العظيــم أن‬\n      ‫كل مــا قدمــه لــي مــن أطقــم الذهــب كان هديــة وهــو قدمــه دون طلــب‬\n      ‫منــي وأنــه ليــس بنيــة االرجــاع وال شــرط هــذا وأننــي قلــت لــه الهديــة‬\n      ‫كثيــرة فقــال تســتاهلني أكثــر واهلل علــى مــا أقــول شــهيد هكــذا‬\n      ‫حلفــت ‪ ،‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلنــكار املدعــى‬\n      ‫عليهــا وعــدم بينــة املدعــي وألداء املدعــى عليهــا اليمــن كمــا طلبــت‬\n      ‫منهــا ولقولــه صلــى اهلل عليــه وســلم ( البينــة علــى املدعــي واليمــن علــى‬\n      ‫مــن أنكــر ) وللقاعــدة الفقهيــة ‪ :‬العــادة محكمــة فقــد صرفــت النظــر‬\n      ‫عــن دعــوى املدعــي وأخليــت ســبيل املدعــى عليهــا مــن هــذه الدعــوى هــذا‬\n\n\n‫‪271‬‬\n\f‫مــا ظهــر لــي وبــه حكمــت وقنعــت بــه املدعيــة وقــررت بعــث نســخة مــن‬\n‫احلكــم للمدعــي لتقــدمي اعتراضــه خــال املــدة النظاميــة ويف حــال عــدم‬\n‫تقــدمي اعتراضــه يكتســب احلكــم الصفــة القطعيــة ‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ :‬فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫وبرفقهــا القــرار رقــم ‪ 34240178‬وتاريــخ ‪1434/6/13‬ه ـ املظهــر علــى‬\n‫صــك احلكــم رقــم (‪ )34198975‬وتاريــخ ‪1434/4/27‬ه ـ «ونــص‬\n‫احلاجــة منــه « وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫تقــرر املوافقــة علــى احلكــم واهلل املوفــق ‪ ،‬قاضــي اســتئناف ‪ .......‬ختمــه‬\n‫وتوقيعــه‪ ،‬قاضــي اســتئناف ‪ .......‬ختمــه وتوقيعــه رئيــس الدائــرة قاضــي‬\n‫اســتئناف ‪ .......‬ختمــه وتوقيعــه ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                              ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/07/02‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n‫األولــى لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع‬\n‫علــى املعاملــة الــواردة إلينــا شــفع خطــاب فضيلة رئيــس احملكمة العامة‬\n‫باملدينــة املنــورة املســاعد رقــم ‪ 33/840163‬وتاريــخ ‪1434/5/20‬ه ـ‬\n‫املشــتملة علــى الصــك رقــم ‪ 34198975‬وتاريــخ ‪1434/4/27‬ه ـ الصــادر‬\n‫مــن فضيلــة الشــيخ ‪ .......‬القاضــي باحملكمــة العامــة باملدينــة املنــورة‬\n‫املتضمــن دعــوى ‪ .......‬ضــد ‪ .......‬يف قضيــة زوجيــة وبدراســة الصــك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر املوافقــة علــى احلكــم واهلل‬\n         ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                   ‫‪272‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":265,"source_page_end":272,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"afc937c867ebd9a11e1334b05722e99445bcc49e555ac82f2d17e679b2f6a614","normalized_text_hash":"12750761c4a98d579878ba1fc053458ed69434a5e3e084010978b7e14e1ccbbe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p265-34198975"},{"id":"badb8b84-be9e-59b2-bdff-6423ebf891f5","document_type":"judgment","category":"judicial","subcategory":"general","title":"هبة -رجوع عن هبة إلنفكاك عرى الزوجية -تكييف تسليم مبالغ على أنها هبة -حكم بإخاء سبيل املدعى عليها -تضارب أقوال املدعي أصالة مع أقوال املدعي وكالة قرينة على عدم الصحة .","document_number":"34260389","case_number":"33677765","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ببريدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/5","year":"1434","subject":"هبة -رجوع عن هبة إلنفكاك عرى الزوجية -تكييف تسليم مبالغ على أنها هبة -حكم بإخاء سبيل املدعى عليها -تضارب أقوال املدعي أصالة مع أقوال املدعي وكالة قرينة على عدم الصحة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34260389 :‬تاريخه ‪1434/7/5:‬هـ‬\n                        ‫رقم الدعوى ‪33677765 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34316441‬تاريخه ‪1434/9/10 :‬هـ‬\n\n\n      ‫هبــة ‪ -‬رجــوع عــن هبــة إلنفــكاك عــرى الزوجيــة ‪ -‬تكييــف تســليم مبالــغ‬\n      ‫علــى أنهــا هبــة ‪ -‬حكــم بإخــاء ســبيل املدعــى عليهــا ‪ -‬تضــارب أقــوال‬\n         ‫املدعــي أصالــة مــع أقــوال املدعــي وكالــة قرينــة علــى عــدم الصحــة ‪.‬‬\n\n\n\n\n      ‫عــن ابــن عبــاس رضــى اهلل عنهمــا ان رســول اهلل صلــى اهلل عليــه وســلم‬\n                   ‫قــال «العائــد يف هبتــه كالعائــد يف قيئــه» رواه البخــاري‬\n\n\n\n\n      ‫دعــوى املدعــى وكالــة ضــد املدعــى عليــه وكالــة ومضمــون الدعــوى أن‬\n      ‫املدعــى أصالــة كان زوجــا للمدعــى عليهــا أصالــة وعندمــا كانــت يف‬\n      ‫ذمتــه خرجــت مــن املنــزل دون علــم الــزوج وفــى حوزتهــا مبلغــا ماليـ ًا قــدره‬\n      ‫أربعــة وعشــرون ألــف ريــال عهــدة مصــروف لــم يســتخدم ومبلغــا قــدره‬\n      ‫عشــرون ألــف ريــال مت حتويلــه حلســاب املدعــى عليهــا لغــرض تعاقــد مــع‬\n      ‫خادمــة منزليــة كمــا أنهــا تصرفــت يف مبلــغ قــدره خمســة عشــر ألــف‬\n      ‫ريــال واملدعــى عليهــا لــم تعــد زوجــة للمدعــى أصالــة وطالــب املدعــى‬\n      ‫وكالــة احلكــم علــى املدعــى عليهــا بــرد املبالــغ املصروفــة واحملولــة‬\n      ‫لهــا وقدرهــا كاملــة تســعة وخمســون ألــف ريــال ‪ -‬أجــاب املدعــى عليــه‬\n      ‫وكالــة بــأن املبالــغ املاليــة املشــار إليهــا يف الدعــوى منهــا مــا مت حتويلــه‬\n\n‫‪273‬‬\n\f‫لغــرض النفقــة علــى ابنــه مــدة ســنة ونصــف ســنة ومنهــا مــا مت حتويلــه‬\n‫إرضــاء لزوجــة املدعــى أصالــة عنــد رجوعهــا إليــه ومنهــا مــا مت حتويلــه‬\n‫عنــد قيــام العالقــة الزوجيــة مبحــض إرادتــه مــن بــاب التــودد لزوجتــه‬\n‫بالهديــة ولكــن عندمــا حصــل الفــراق بــن املدعــي أصالــة واملدعــى‬\n‫عليهــا أصالــة طالــب بهــذه املبالــغ ‪ -‬حضــر املدعــى أصالــة وأقــر لــدى‬\n‫ناظــر القضيــة بأنــه دفــع هــذه املبالــغ للمدعــى عليهــا وانــه دفــع لهــا أيضا‬\n‫مبالــغ كثيــرة مــن أجــل ترغيبهــا بالبقــاء عنــده ‪ -‬قــرر ناظــر القضيــة انــه‬\n‫بنــاء علــى إقــرار املدعــى أصالــة بأنــه أعطــى املدعــى عليهــا أصالــة هــذه‬\n‫املبالــغ مــن اجــل ترغيبهــا بالبقــاء عنــده وفــى بيتــه فقــد ظهــر لــه بــان‬\n‫املدعــى أصالــة أعطــى املدعــى عليهــا هــذه املبالــغ هبــة ولقولــه صلــى‬\n‫اهلل عليــه وســلم ((العائــد يف هبتــه كالعائــد يف قيئــه)) لــذا فقــد صــدر‬\n‫احلكــم بصــرف النظــر عــن دعــوى املدعــى ‪ -‬قــرر املدعــى وكالــة عــدم‬\n‫القناعــة ‪ -‬صــدر قــرار محكمــة االســتئناف باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة العامــة‬\n‫ببريــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة ببريــدة برقــم ‪ 33677765‬وتاريــخ ‪ 1433/11/27‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 332122900‬وتاريــخ ‪ 1433/11/27‬ه ـ ففــي‬\n‫يــوم األحــد املوافــق‪ 1433/12/19‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n‫‪ 09‬وفيهــا حضــر ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫بالوكالــة عــن ‪ .......‬مدعيـ ًا علــى احلاضــر معــه يف مجلــس القضــاء ‪.......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم حــال كونــه وكيــا عــن‬\n\n                                                                                        ‫‪274‬‬\n\f      ‫‪ .......‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل بريــدة الثانيــة برقــم‬\n      ‫يف ‪1433/7/19‬ه ـ املخــول لــه فيهــا حــق املطالبــة واملخاصمــة واملدافعــة‬\n      ‫واملرافعــة وإقامــة الدعــاوى وحتريرهــا والــرد عليهــا وتقــدمي الالئحــة‬\n      ‫االعتراضيــة وإقامــة البينــة والدفــع وقبــول احلكــم ونفيــه واالعتــراض‬\n      ‫عليــه وطلــب متييــزه والصلــح قائــا يف دعــواه حيــث أن زوجــة موكلــي‬\n      ‫خرجــت مــن املنــزل دون علمــه وأثنــاء تواجــده يف مدينــة الريــاض ويف‬\n      ‫حوزتهــا مبلــغ وقــدره أربعــة وعشــرون ألــف ريــال عهــدة مصــروف لــم‬\n      ‫يســتخدم ومبلــغ عشــرون ألــف ريــال حتويــل يف حســابها لشــراء عقــد‬\n      ‫خادمــة ومجمــوع املبالــغ املطالــب بهــا هــي أربعــة وأربعــون ألــف ريــال‬\n      ‫إضافــة أنهــا تصرفــت يف مبلــغ خمســة عشــر ألــف ريــال يف ثالثــة أيــام‬\n      ‫أطلــب إلزامهــا بــرد املبالــغ املاليــة املذكــورة وقدرهــا تســعة وخمســون‬\n      ‫ألــف ريــال هــذه دعــواي ‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة‬\n      ‫أجــاب بقولــه مــا ذكــره املدعــي وكالــة مــن حيــث حتويــل املبالغ حلســاب‬\n      ‫موكلتــي فهــذا صحيــح ولكــن األربــع وعشــرين ألــف ريــال التــي ذكــر‬\n      ‫بأنهــا عهــدة هــي مصــروف البنــه مــن موكلتــي لســنة ونصــف وبالنســبة‬\n      ‫للعشــرين ألــف ريــال فهــي ليســت لشــراء عقــد خادمــة والواقــع أن موكل‬\n      ‫املدعــي دفعهــا رضــوة ملوكلتــي عنــد رجعتــه إليهــا واخلمســة عشــر ألــف‬\n      ‫ريــال حولهــا بحســابها عنــد قيــام العالقــة الزوجيــة مبحــض إرادتــه وهــي‬\n      ‫لــم جتبــره عليهــا وإمنــا حولهــا مــن بــاب التــودد لهــا بالهديــة وعندمــا حصل‬\n      ‫بينهمــا الفــراق أراد أن يســتعيد هــذه املبالــغ وموكلتــي ليــس لديهــا‬\n      ‫اســتعداد بــأن تدفــع لــه شــيء هــذه إجابتــي وبعــرض ذلــك علــى املدعــي‬\n      ‫وكالــة أجــاب بقولــه إن موكلــي قــد دفــع املبالــغ ملوكلــة املدعــي‬\n      ‫ولكنهــا لــم متكــث عنــده إال فتــرة وجيــزة ثــم طالبــت بالفســخ هكــذا‬\n\n\n‫‪275‬‬\n\f‫أجــاب وللتأمــل رفعــت اجللســة ثــم يف يوم األحــد املوافق‪1434/03/01‬هـ‬\n‫حضــر املدعــي أصالـ ًة ‪ .......‬ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم‬\n‫‪ .......‬وحضــر حلضــوره املدعــى عليــه وكالــة وبتــاوة مــا مت ضبطــه علــى‬\n‫املدعــي أصالــة أجــاب بقولــه جميــع مــا ذكــره وكيلــي صحيــح مــا‬\n‫عــدا مبلــغ اخلمســة عشــر ألــف ريــال فــان صحــة املبلــغ هــو عشــرة آالف‬\n‫وســبعمائة ريــال ألنــه اتضــح لــي أن مبلــغ أربعــة آالف وثالثمائــة ريــال‬\n‫مت صرفهــا مــن قبلــي علمـ ًا بــان املدعــى عليهــا أخــذت بطاقــة الصــراف‬\n‫بإذنــي وصرفــت املبلــغ املذكــور ولــم أكــن أتوقــع أن تصــرف هــذا‬\n‫املبلــغ هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب‬\n‫بقولــه انــه ظهــر تناقــض يف دعــوى املدعــي وكالــة واملدعــي أصالــة‬\n‫بخصــوص املبلــغ اخلمســة عشــر ألــف ريــال وأود أن أوضــح بــان املبلــغ‬\n‫األربعــة وعشــن ألــف ريــال قــد صرفتــه موكلتــي علــى ابــن املدعــي ملــدة‬\n‫ســنه وســتة أشــهر والعشــرين ألــف ريــال التــي يذكــر بأنهــا مقابــل شــراء‬\n‫عقــد اخلادمــة فاخلادمــة أساســا كانــت موجــودة عنــد موكلتــي وقــد‬\n‫أعطاهــا هــذا املبلــغ مــن اجــل هــذه اخلادمــة وبهــذا فــان املدعــي قــد دفــع‬\n‫ملوكلتــي هــذه املبالــغ بطوعــه واختيــاره وليــس لــدى موكلتــي اســتعداد‬\n‫بــأن تعيــد لــه شــيء كمــا أســلفت هكــذا أجــاب وبعــرض ذلــك علــى‬\n‫املدعــي أصالــة أجــاب بقولــه إننــي دفعــت هــذه املبالــغ ملوكلــة املدعــى‬\n‫عليــه ودفعــت لهــا أيضــا مبالــغ كثيــرة ال ارغــب يف املطالبــة بهــا مــن‬\n‫اجــل ترغيــب موكلــة املدعــى عليــه بالبقــاء عنــدي ويف بيتــي هكــذا‬\n‫أجــاب والنتهــاء الوقــت احملــدد للجلســة فقــد جــرى رفعهــا ثــم يف يــوم‬\n‫األحــد املوافــق‪ 1434/07/02‬ه ـ حضــر ‪ ......‬ســعودي مبوجــب الســجل‬\n‫املدنــي رقــم بالوكالــة عــن املدعــي الصــادرة مــن كتابــة عــدل بريــدة‬\n\n\n                                                                                       ‫‪276‬‬\n\f      ‫الثانيــة برقــم ‪ 34749295‬وتاريــخ ‪1434/06/12‬ه ـ واملخــول لــه فيهــا‬\n      ‫حــق املطالبــة وإقامــة الدعــاوى ‪ -‬املرافعــة واملدافعــة ‪ -‬ســماع الدعــاوى‬\n      ‫والــرد عليهــا ‪ -‬اإلنــكار ‪ -‬اإلقــرار ‪-‬الصلــح ‪ -‬التنــازل‪ -‬احضــار الشــهود‬\n      ‫والبينــات والطعــن فيهــا ‪ -‬االجابــة واجلــرح والتعديــل ‪ -‬الطعــن بالتزويــر‪-‬‬\n      ‫قبــول األحــكام ونفيهــا ‪ -‬االعتــراض علــى األحــكام وطلب االســتئناف‬\n      ‫‪ -‬التمــاس إعــادة النظــر ‪-‬طلــب رد االعتبــار وحضــر حلضــوره ســعودي‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .......‬بالوكالــة عــن املدعى عليهــا الصادرة‬\n      ‫مــن كتابــة عــدل بريــدة الثانيــة برقــم ‪ 34550210‬وتاريــخ ‪1434/5/1‬هـ‬\n      ‫واملخــول لــه فيهــا حــق املطالبــة وإقامــة الدعــاوى ‪ -‬املرافعــة واملدافعــة‬\n      ‫‪ -‬ســماع الدعــاوى والــرد عليهــا ‪ -‬احضــار الشــهود والبينــات والطعــن‬\n      ‫فيهــا ‪ -‬طلــب املنــع مــن الســفر ورفعــه ‪ -‬طلــب احلجــز والتنفيــذ ‪ -‬املطالبــة‬\n      ‫بتنفيــذ األحــكام ‪ -‬االعتــراض علــى األحــكام وطلــب االســتئناف ‪-‬‬\n      ‫التمــاس إعــادة النظــر ‪-‬طلــب رد االعتبــار وبعــد أن جــرى تأمــل القضيــة‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــي أصالــة‬‫فبنـ ً‬\n      ‫يف اجللســة املنعقــدة بتاريــخ ‪1434/3/1‬ه ـ بأنــه أعطاهــا هــذه املبالــغ مــن‬\n      ‫أجــل ترغيبهــا بالبقــاء عنــده ويف بيتــه والــذي يظهــر لــي بــأن املدعــي‬\n      ‫أعطــى املدعــى عليهــا هــذه املبالــغ هبــة ولقــول الرســول صلــى اهلل‬\n      ‫عليــه وســلم عــن ابــن عبــاس (العائــد يف هبتــه كالعائــد يف قيئــه ) رواه‬\n      ‫البخــاري بجميــع مــا تقــدم فقــد صرفــت النظــر عــن دعــوى املدعــي‬\n      ‫وأخليــت ســبيل املدعــى عليهــا مــن دعــوى املدعــي هــذا مــا ظهــر لــي وبــه‬\n      ‫حكمــت وبعــرض ذلــك علــى وكيــل املدعــي قــرر عــدم القناعــة وطلــب‬\n      ‫تســليمه صــورة مــن احلكــم وإمهالــه لالعتــراض فأجبتــه لطلبــه وأفهمتــه‬\n      ‫مبراجعــة احملكمــة يف يــوم األربعــاء املوافــق ‪1434/7/5‬ه ـ وأنه يف حال‬\n\n\n‫‪277‬‬\n\f‫تأخــره ســوف يتــم إيــداع الصــك يف املعاملــة واحتســاب مــدة تأخــره مــن‬\n‫مــدة االعتــراض ففهــم ذلــك كمــا قــرر املدعــى عليــه وكالــة القناعــة‬\n‫وعليــه جــرى التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/07/02‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n‫بتدقيــق قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة ببريــدة برقــم (‪ )332122900‬وتاريــخ ‪1434/8/14‬هــ؛ املقيــدة‬\n‫لــدى احملكمــة برقــم (‪ )342014078‬وتاريــخ ‪1434/8/21‬هــ؛ اخلاصــة‬\n‫بدعــوى‪ ........ /‬الوكيــل عــن ‪ ........ /‬ضــد ‪ ........ /‬الوكيــل عــن ‪........ /‬‬\n‫؛ بشــأن املطالبــة مببلــغ مالــي قــدره تســعة وخمســون ألــف ريــال؛ املنتهيــة‬\n‫بالصــك الصــادر مــن فضيلــة الشــيخ‪ /‬القاضــي باحملكمــة؛ املســجل‬\n‫برقــم (‪ )34260389‬وتاريــخ ‪1434/7/5‬هــ؛ املتضمــن حكــم فضيلتــه‬\n‫بصــرف النظــر عــن دعــوى املدعــي؛ علــى النحــو املفصــل فيــه‪ .‬وبدراســة‬\n‫الصــك وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى ماحكــم‬\n‫بــه فضيلتــه‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                            ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪278‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":273,"source_page_end":278,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"66f26719bc55f11e34b9dc988f83ba7dabc2b091b32574d7b8293e9cfc6f19fc","normalized_text_hash":"a2a7197469dec167611397b1de739fee4e81de15019a3d981e5911f547973695","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p273-34260389"},{"id":"4d9c1e9d-2fe5-5351-bd16-1ecd0a8ef657","document_type":"judgment","category":"judicial","subcategory":"general","title":"هبة -مطالبة بإعادة عقار -مطالبة زوج بإعادة هبة من زوجته بعد حدوث شقاق -شهادة األبناء يف دعوى بن الوالدين -حلف مين - الهبة لسبب تثبت بثبوته وتزول بزواله -احلكم على الزوجة بإعادة العقار لزوجها .","document_number":"34259015","case_number":"34187285","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/ 4","year":"1434","subject":"هبة -مطالبة بإعادة عقار -مطالبة زوج بإعادة هبة من زوجته بعد حدوث شقاق -شهادة األبناء يف دعوى بن الوالدين -حلف مين - الهبة لسبب تثبت بثبوته وتزول بزواله -احلكم على الزوجة بإعادة العقار لزوجها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34259015 :‬تاريخه ‪1434/7/ 4 :‬هـ‬\n                         ‫رقم الدعوى ‪34187285 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34340866‬تاريخه ‪1434/10/26 :‬هـ‬\n\n\n      ‫هبــة ‪ -‬مطالبــة بإعــادة عقــار ‪ -‬مطالبــة زوج بإعــادة هبــة مــن زوجتــه بعــد‬\n      ‫حــدوث شــقاق ‪ -‬شــهادة األبنــاء يف دعــوى بــن الوالديــن ‪ -‬حلــف ميــن ‪-‬‬\n      ‫الهبــة لســبب تثبــت بثبوتــه وتــزول بزوالــه ‪ -‬احلكــم علــى الزوجــة بإعــادة‬\n                                                                     ‫العقــار لزوجها ‪.‬‬\n\n\n\n\n      ‫مــا قــرره شــيخ اإلســام بــن تيميــه بقولــه ( وقــد كتبــت عــن اإلمــام‬\n      ‫احمــد فيمــا إذا أهــدى لهــا هديــة بعــد العقــد فإنهــا تــرد ذلــك إليــه إذا‬\n      ‫زال العقــد الفاســد فهــذا يقتضــي إمنــا وهبــه لهــا بســبب النــكاح فانــه‬\n      ‫يبطــل إذا زال النــكاح وهــذا املنصــوص جــار علــى أصــول املذهــب املوافــق‬\n      ‫ألصــول الشــريعة وهــو أن كل مــن اهــدي لــه شــيء أو وهــب لــه شــيء‬\n                     ‫بســبب يثبــت بثبوتــه ويــزول بزوالــه) االختيــارات صــ‪.232‬‬\n\n\n\n\n      ‫أدعــى الــزوج ضــد املدعــى عليهــا الزوجــة مــن أنــه قــام بكتابــة منزلــه‬\n      ‫الكائــن يف حــي ‪ .....‬واملبــن موقعــه ورقــم ســند امللكيــة يف نص الضبط‬\n      ‫ـاء لهــا بعــد ذهابهــا لبيــت أهلهــا يف‬\n                                             ‫باســم زوجتــه املدعــى عليهــا إرضـ ً‬\n      ‫مكــة ثــم عــادت وبعــد فتــرة قامــت بإخــراج املدعــي مــن املنــزل ومنعــه‬\n      ‫مــن الدخــول فيــه وأقامــت دعــوى تطلــب الطــاق وطلــب املدعــي إعــادة‬\n\n‫‪279‬‬\n\f‫البيــت إلــى ملكــه ‪ -‬أجابــت املدعــى عليهــا أن املدعــي كتــب البيــت‬\n‫باســمها مقابــل وعــد قــدمي بــأن يجعــل البيــت باســمها مكافــأة لهــا وال‬\n‫صحــة ملــا ذكــره املدعــي يف دعــواه ‪ -‬أحضــر املدعــي بينــه وهــم ولــدي‬\n‫طــريف القضيــة شــهدا علــى صحــة دعــوى املدعــي ‪ -‬قــرر املدعــي أنــه‬\n‫منــح زوجتــه البيــت رغبــة يف اســتدامة عقــد الــزواج ‪ -‬حلــف املدعــي علــى‬\n‫صحــة دعــواه بعــد عــرض اليمــن عليــه مــن ناظــر القضيــة ‪ -‬قــرر ناظــر‬\n‫ـاء علــى شــهادة الشــهود مــن أن الهبــة ألجــل عــودة الزوجــة‬  ‫القضيــة بنـ ً‬\n‫وإنهــاء الفرقــة وبــذل املدعــي اليمــن علــى صحــة دعــواه ووجــود قضيــة‬\n‫فســخ نــكاح ولعظــم الشــقاق بينهمــا ومــا هو مقرر عنــد الفقهاء أن كل‬\n‫مــن أهــدي لــه شــيء بســبب يثبــت بثبوتــه و يــزول بزوالــه ‪ -‬فقــد صــدر‬\n‫احلكــم بإعــادة البيــت إلــى املدعــي ‪ -‬قــررت املدعــى عليهــا عــدم القناعــة‬\n‫‪ -‬صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة باملصادقــة علــى‬\n                                                                        ‫احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 34187285‬وتاريــخ ‪ 1434/04/23‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34999694‬وتاريــخ ‪ 1434/04/23‬ه ـ ففــي يــوم‬\n‫األحــد املوافــق‪ 1434/05/26‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n‫عشــرة صباحــا وفيهــا حضــر املدعــي ‪ /‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم وحضــر حلضــوره املدعــى عليهــا ‪ /‬زوجتــه ســعودية‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم وبســؤال املدعــي عــن دعــواه‬\n\n                                                                                     ‫‪280‬‬\n\f      ‫ادعــى قائــا اننــي قمــت بكتابــة منزلــي الكائــن يف حــي ‪ .......‬خلــف‬\n      ‫‪ .......‬املكــون مــن دوريــن وملحــق اململــوك بالصــك رقــم ‪2/7/367/96‬‬\n      ‫وتاريــخ ‪1433/6/11‬ه ـ باســم زوجتــي وذلــك إرضاء لهــا بعد ذهابها الى‬\n      ‫بيــت اهلهــا يف مكــة ثــم عــادت بعــد ذلــك وبعــد فتــرة قامــت بإخراجــي‬\n      ‫مــن املنــزل ومنعــي مــن دخولــه واقامــت دعــوى تطلــب فيهــا الطــاق‬\n      ‫واشــتكتني لــدى الشــرطة اطلــب اعــادة البيــت الــى ملكــي حيــث اننــي‬\n      ‫منحتهــا ايــاه رغبــة يف اســتدامة الــزواج هــذه دعــواي وبعــرض ذلــك علــى‬\n      ‫املدعــى عليهــا اجابــت بقولهــا ماذكــره املدعــي غيــر صحيــح والصحيــح‬\n      ‫انــه قــام بكتابــة املنــزل باســمي وذلــك مقابــل وعــد قــدمي وعدنــي ايــاه أن‬\n      ‫يجعــل البيــت األخيــر باســمي مكافــأة لــي بعــد تفريطــه وبيعــه ألكثــر‬\n      ‫مــن عقــار واســكاننا يف شــقق مفروشــة فتــرة مــن الزمــن ولــم يجعلــه‬\n      ‫مقابــل عودتــي اليــه مــن بيــت اهلــي او رضــوة هكــذا اجابــت وبســؤال‬\n      ‫املدعــي عــن بينتــه أحضــر كال مــن ‪ /‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم و‪ /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وهــم ابنــاء‬\n      ‫الطرفــن طــاب يف التعليــم العالــي ويســكنون يف حــي ‪.......‬مــع والدتهــم‬\n      ‫ومــن مواليــد ‪ 1413‬األول والثانــي مــن مواليــد ‪1415‬ه ـ وبســؤالهم عــن‬\n      ‫مــا لديهــم مــن شــهادة شــهد االول بقولــه اشــهد هلل تعالــى ان والــدي‬\n      ‫قــد وعــد أمــي بــأن يكتــب البيــت باســمها كمــا انــه بعــد ان ذهبــت‬\n      ‫والدتــي الــى اهلهــا يف مكــة بعــد مشــاكل بينهمــا اتصلــت بــه وطلبــت‬\n      ‫منــه احلضــور الــى منــزل اخوالــي وكان دون رضــا والدتــي ومت االجتمــاع‬\n      ‫يف منــزل اخوالــي واتفقــوا علــى ان تعــود معــه الــى منزلــه مقابــل أن‬\n      ‫يكتــب املنــزل باســمها هــذا مــا لــدي مــن شــهادة كمــا شــهد الثانــي‬\n      ‫مبثــل مــا شــهد بــه االول وقــرر ان االتصــال كان مــن قبــل اخيــه هكــذا‬\n\n\n‫‪281‬‬\n\f‫شــهدوا وبعــرض ذلــك علــى املدعــى عليهــا قالــت مــا ذكــره الشــهود‬\n‫صحيــح جملــة وتفصيــا هكــذا أجابــت كمــا قــرر املدعــي بقولــه ان‬\n‫ابنــي اتصــل بــي وقــال ان والدتــي تريــد التفاهــم معــك لــذا احضــر الينــا‬\n‫يف مكــة هكــذا قــرر وبــرد ذلــك علــى الشــاهد قــال انــا مــن ذكــر‬\n‫ذلــك هكــذا قــرر وعنــد وصــول القضيــة الــى هــذا احلــد قــررت رفــع‬\n‫اجللســة للتأمــل ثــم انــه يف يــوم اإلثنــن املوافــق‪ 1434/07/03‬ه ـ افتتحت‬\n‫اجللســة الســاعة الثامنــة والنصــف صباحــا وفيهــا حضــر الطرفــان وجــرى‬\n‫ســؤال املدعــي عــن ســبب منحــه املنــزل للمــرأة فأجــاب بقولــه اننــي‬\n‫منحتهــا ايــاه رغبــة يف اســتدامة الــزواج وعودتهــا الــى بيــت الزوجيــة بعــد‬\n‫خــاف بيننــا كمــا انهــا بعــد ان قمــت بكتابــة املنــزل قامــت بطــردي‬\n‫ومحاولــة فســخ نكاحهــا منــي والقضيــة منظــورة لــدى فضيلــة الشــيخ‬\n‫‪.......‬هكــذا اجــاب وبــرد ذلــك علــى املــرأة احلاضــرة اجابــت بقولهــا‬\n‫اننــي ســبق وان ذكــرت ان ذلــك غيــر صحيــح وامنــا قــام مبنحــي البيــت‬\n‫مقابــل وعــده لــي هكــذا اجابــت ثــم جــرى عــرض اليمــن علــى املدعــي‬\n‫فاســتعد ببذلهــا بعــد ان اذنــت لــه قائــا واهلل العلــي العظيــم الــذي ال‬\n‫الــه اال هــو عالــم الغيــب والشــهادة اننــي كتبــت البيــت باســم زوجتــي‬\n‫مقابــل عودتهــا الــى منزلــي ورغبــة باســتدامة احليــاة الزوجيــة ثــم قامــت‬\n‫بطــردي منــه دون ســبب واهلل العلــي العظيــم هكــذا حلــف وبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واالجابــة وحيــث احضــر املدعــي ابنائــه للشــهادة‬\n‫وقنعــت بهــم املدعــى عليهــا وملــا ذكــره الشــهود مــن ان الهبــة كانــت‬\n‫ألجــل عــودة املــرأة الــى بيــت زوجهــا وانهــاء للفرقــة وحيــث بــذل املدعــي‬\n‫اليمــن علــى صحــة دعــواه وملــا قــرره الطرفــان مــن وجــود قضيــة فســخ‬\n‫نــكاح منظــورة ولعظــم الشــقاق بينهمــا وملــا قــرره شــيخ االســام ابــن‬\n\n\n                                                                                     ‫‪282‬‬\n\f      ‫تيميــه بقولــه (وقــد كتبــت عــن االمــام احمــد فيمــا اذا اهــدي لهــا هديــة‬\n      ‫بعــد العقــد فإنهــا تــرد ذلــك اليــه اذا زال العقــد الفاســد فهــذا يقتضــي امنا‬\n      ‫وهبــه لهــا بســبب النــكاح فانــه يبطــل اذا زال النــكاح وهــذا املنصــوص‬\n      ‫جــار علــى اصــول املذهــب املوافقــة ألصــول الشــريعة وهــو ان كل مــن‬\n      ‫اهــدي لــه شــيء او وهــب لــه شــيء بســبب يثبــت بثبوتــه ويــزول بزوالــه)‬\n      ‫االختيــارات ص‪ 232‬كمــا نــص عليــه يف املنــار ويف املطالــب لذلــك كلــه‬\n      ‫فقــد حكمــت بإعــادة البيــت الــى املدعــي وبعرضــه عليهمــا قنــع املدعــي‬\n      ‫ولــم تقنــع املدعــى عليهــا فجــرى افهمهــا بــأن لهــا حــق االعتــراض وذلــك‬\n      ‫بطلــب االســتئناف وذلــك بتقــدمي الئحــة اعتراضيــة خــال ثالثــون يومــا‬\n      ‫مــن تاريــخ اســتالم احلكــم وان مضــت املــدة دون تقــدمي الئحــة اكتســب‬\n      ‫احلكــم القطعيــة وســقط حقهــا باالعتــراض ثــم جــرى افهامهــا بــأن‬\n      ‫عليهــا مراجعــة احملكمــة يــوم غــدا الثالثــاء الســتالم احلكــم وابتــداء‬\n      ‫املهلــة ففهمــت ذلــك وختمــت اجللســة الســاعة التاســعة صباحــا وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                               ‫يف ‪ 1434/07/03‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم ‪34/999694‬‬\n      ‫وتاريــخ ‪1434/10/19‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫القاضــي باحملكمــة العامــة بالطائــف واملســجل بعــدد ‪34259015‬‬\n      ‫وتاريــخ ‪1434/7/4‬هـ ـ واملتضمــن دعــوى‪ ........ /‬ضــد‪ ........ /‬واحملكــوم‬\n      ‫فيــه مبــا دون باطنــه‪ .‬وبدراســة احلكــم وصــورة ضبطــه والالئحــة‬\n\n\n‫‪283‬‬\n\f‫االعتراضيــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق‪ .‬وصلــى اهلل‬\n                          ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                               ‫‪284‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":279,"source_page_end":284,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0780ccfbe8f3bb70808ff3b14d683c80e9d0ae66392134cbf639c8fc2fc96cbe","normalized_text_hash":"9a3219d491c1a2b03cf90f2164a86aaf33f9a593b4c1279e5a43fd4988b3fd39","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p279-34259015"},{"id":"e54f7e02-ddd8-5ee0-8bf6-3a3d0cc0bf84","document_type":"judgment","category":"judicial","subcategory":"general","title":"هبة -قسمة تركة -مطالبة املدعي ببيع عقار مورثه وتسليمه نصيبه الشرعي -ثبوت انتقال ملكية العقار محل الدعوى ألحد أبناء املورث هبة لعلة وإعاقة -جواز تخصيص األب بالعطية بعض األوالد ملعنى يقتضى تخصيصه -ثبوت العطية ملن وهبت له من الورثة بعد الوفاة دون الرجوع -رد الدعوى .","document_number":"34265813","case_number":"33619017","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/6","year":"1434","subject":"هبة -قسمة تركة -مطالبة املدعي ببيع عقار مورثه وتسليمه نصيبه الشرعي -ثبوت انتقال ملكية العقار محل الدعوى ألحد أبناء املورث هبة لعلة وإعاقة -جواز تخصيص األب بالعطية بعض األوالد ملعنى يقتضى تخصيصه -ثبوت العطية ملن وهبت له من الورثة بعد الوفاة دون الرجوع -رد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34265813 :‬تاريخه‪1434/11/6 :‬هـ‬\n                         ‫رقم الدعوى‪33619017 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34371693‬تاريخه‪1434/11/26 :‬هـ‬\n\n\n      ‫هبــة ‪ -‬قســمة تركــة ‪ -‬مطالبــة املدعــي ببيــع عقــار مورثــه وتســليمه‬\n      ‫نصيبــه الشــرعي ‪ -‬ثبــوت انتقــال ملكيــة العقــار محــل الدعــوى ألحــد‬\n      ‫أبنــاء املــورث هبــة لعلــة وإعاقــة ‪ -‬جــواز تخصيــص األب بالعطيــة بعــض‬\n      ‫األوالد ملعنــى يقتضــى تخصيصــه ‪ -‬ثبــوت العطيــة ملــن وهبــت لــه مــن‬\n                                 ‫الورثــة بعــد الوفــاة دون الرجــوع ‪ -‬رد الدعــوى ‪.‬‬\n\n\n\n      ‫‪ .1‬مــا قــرره الفقهــاء مــن جــواز تخصيــص األب بعــض األوالد ملعنــى‬\n      ‫يقتضــي تخصيصــه مثــل اختصاصــه بحاجــة أو زمانــه أو عمــى أو‬\n      ‫كثــرة عائلــة أو اشــتغاله بالعلــم أو نحــوه مــن الفضائــل أو صــرف‬\n      ‫عطيتــه عــن بعــض ولــده لفســقه أو بدعتــه أو لكونــه يســتعني مبــا‬\n      ‫يأخــذه علــى معصيــة اهلل أو ينفقــه فيهــا (ينظــر املغنــي ج‪ 8/‬ص ‪.)258‬‬\n      ‫‪ .2‬جــاء يف املغنــي ج‪ 270-269/8‬مســألة‪ :‬قــال (فــإن مــات ولــم يــردده فقــد‬\n      ‫ثبــت ملــن وهــب لــه إذا كان ذلــك يف صحتــه) يعنــي إذا فاضــل بــن ولــده‬\n      ‫يف العطايــا أو خــص بعضهــم بعطيــة ثــم مــات قبــل أن يســترده ثبــت‬\n                   ‫ذلــك للموهــوب لــه ولــزم وليــس لبقيــة الورثــة الرجــوع أ‪.‬ه ـ‬\n      ‫‪ .3‬جــاء يف حاشــية الــروض املربــع شــرح زاد املســتقنع ج‪ 6/‬ص ‪( 18‬فــإن‬\n      ‫مــات الواهــب قبلــه أي قبــل الرجــوع أو الزيــادة ثبتــت للمعطــي فليــس‬\n                                                           ‫لبقيــة الورثــة الرجــوع)‪.‬‬\n\n\n‫‪285‬‬\n\f‫ادعــى املدعــي ضــد املدعــى عليــه بــأن مورثــه ومــورث املدعــى عليــه‬\n‫والدهــم قــد تــويف وخلــف العقــار الكائــن بالشــامية بــرأس جبــل القــرن‬\n‫واململــوك مبوجــب الصــك الصــادر مــن كتابــة العــدل وأن العقــار‬\n‫املذكــور ســيزال لصالــح توســعة الســاحات الشــمالية للحــرم املكــي‬\n‫الشــريف وصــك العقــار لــدى املدعــى عليــه ويطلــب احلكــم ببيــع العقــار‬\n‫املذكــور وتســليمه نصيبــه الشــرعي منــه وإلــزام املدعــى عليــه بتســليمه‬\n‫الصــك اخلــاص بالعقــار محــل الدعــوى هكــذا ادعــى ‪ -‬أجــاب املدعــى‬\n‫عليــه باملصادقــة علــى وفــاة مورثهــم وأمــا مــا ذكــره املدعــي مــن أن‬\n‫مورثهــم قــد خلــف العقــار املذكــور يف الدعــوى فغيــر صحيــح والصحيــح‬\n‫ـاء واململوكــة بهــذا‬ ‫أن مورثهــم قــد تنــازل عــن كامــل الــدار أرض ـ ًا وبنـ ً‬\n‫الصــك ألخيــه الشــقيق ‪ ...‬لوجــه اهلل تعالــى لكونــه معاقـ ًا ومعتوهـ ًا وهــو‬\n‫ولــي علــى ‪ ....‬املذكــور وذلــك مبوجــب صــك الواليــة الصــادر مــن هــذه‬\n‫احملكمــة ويطلــب احلكــم بصــرف النظــر عــن دعــوى املدعــي هكــذا‬\n‫أجــاب ‪ -‬صــادق املدعــي علــى إعاقــة أخيــه وعتهــه ونفــى علمــه بتنــازل‬\n‫مورثهــم عــن العقــار وأن املدعــى عليــه ولــي علــى أخيــه ‪ -‬أبــرز املدعــى‬\n‫عليــه صــك العقــار ومهمــش عليــه بالتنــازل ‪ -‬جــرى االستفســار عــن صــك‬\n‫العقــار وصــك الواليــة مــن مصــدره فــورد اجلــواب مبطابقتهمــا لســجلهما‬\n‫وســريان مفعولهمــا ‪ -‬لدفــع املدعــى عليــه واليــة بــأن العقــار ليــس ملــك ًا‬\n‫للمــورث وأنــه ملــك ملــن حتــت واليتــه وأن والــده قــد تنــازل لــه قبــل موتــه‬\n‫لكونــه معاق ـ ًا ومعتوه ـ ًا ‪ -‬وإلقــرار املدعــي بعــدم علمــه مبــا ذكــره‬\n‫املدعــى عليــه واليــة وألن عــدم علــم املدعــي ليــس لــه أثــر يف ذلــك ملــا‬\n\n                                                                                        ‫‪286‬‬\n\f      ‫قــرره الفقهــاء مــن جــواز تخصيــص األب بعــض األوالد ملعنــى يقتضــي‬\n      ‫تخصيصــه مثــل اختصاصــه بحاجــة أو زمانــه ‪( ..‬ينظــر املغنــي ‪/‬ج‪8/‬‬\n      ‫ص ‪ )258‬وكذلــك ملــا قــرره أهــل العلــم مــن ثبــوت الهبــة ملــن وهبــت لــه‬\n      ‫بعــد مــوت األب ينظــر املغنــي (ج‪ 8/‬ص ‪269‬ـ ‪ )270‬وحاشــية الــروض‬\n      ‫املربــع (ج‪ 6/‬ص ‪ - )18‬ملــا تقــدم حكمــت احملكمــة بصــرف النظــر عــن‬\n      ‫طلــب املدعــي وإفهامــه بأنــه ال يســتحق مــا جــاء يف دعــواه ‪ -‬قنــع املدعــى‬\n      ‫عليــه باحلكــم واعتــرض املدعــي بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة‬\n            ‫احلقوقيــة الثانيــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القاضــي يف احملكمــة‬\n      ‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33619017‬وتاريــخ‬\n      ‫‪1433/10/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331873260‬وتاريــخ‬\n      ‫‪1433/10/23‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/02/26‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر ‪.........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪.........‬وادعــى علــى احلاضــر معــه ‪.........‬ي‬\n      ‫ا يف دعــواه لقد‬       ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.........‬قائـ ً‬\n      ‫تــويف مورثــي ومــورث املدعــى عليــه والدنــا ‪.........‬بتاريــخ ‪1424/5/16‬ه ـ‬\n      ‫وانحصــر إرثــه يف أبنائــه مــن زوجــة متوفــاة قبلــه ‪......... ......... .........‬ويف‬\n      ‫زوجته ‪.........‬ويف أبنائه منها‪......... ......... ......... ......... ......... ......... .........‬‬\n      ‫البالغــن و‪.........‬القاصــر عقلي ـ ًا أه ـ وقــد خلــف مورثنــا العقــار الكائــن‬\n      ‫بالشــامية بــرأس جبــل القــرن واململــوك مبوجــب الصــك الصــادر مــن‬\n\n‫‪287‬‬\n\f‫كتابــة العــدل األولــى مبكــة برقــم ‪ 13/67‬يف ‪1420/5/28‬ه ـ والعقــار‬\n‫املذكــور ســيزال لصالــح توســعة الســاحات الشــمالية للحــرم املكــي‬\n‫الشــريف وصــك العقــار لــدى املدعــى عليــه فلذلــك فأنــا أطلــب احلكــم‬\n‫ببيــع العقــار املذكــور وتســليمي نصيبــي الشــرعي منــه وإلــزام املدعــى‬\n‫عليــه بتســليمي الصــك اخلــاص بالعقــار محــل الدعــوى هــذه دعــواي‬\n‫ا مــا ذكــره املدعــي‬    ‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائ ـ ً‬\n‫مــن وفــاة مورثنــا بالتاريــخ املذكــور وإنحصــار ارثــه باملذكوريــن يف‬\n‫دعــواه فهــذا صحيــح وأمــا مــا ذكــره املدعــي مــن أن مورثنــا قــد خلــف‬\n‫العقــار املذكــور يف الدعــوى فهــذا غيــر صحيــح والصحيــح أن مورثنــا‬\n‫ـاء واململوكــة بهــذا الصــك ألخــي‬    ‫قــد تنــازل عــن كامــل الــدار أرضـ ًا وبنـ ً‬\n‫الشــقيق ‪.........‬لوجــه اهلل تعالــى وبــدون ثمــن لكونــه معاق ـ ًا ومعتوه ـ ًا‬\n‫وأنــا ولــي علــى ‪.........‬املذكــور وذلــك مبوجــب صــك الواليــة الصــادر مــن‬\n‫هــذه احملكمــة برقــم ‪ 13/1/122‬يف ‪1424/6/15‬ه ـ وأطلــب احلكــم‬\n‫بصــرف النظــر عــن دعــوى املدعــي هكــذا أجــاب وبعــرض ذلــك علــى‬\n‫ا مــا ذكــره املدعــى عليــه مــن كــون أخــي ‪.........‬معاقـ ًا‬   ‫املدعــي قــرر قائـ ً‬\n‫ومعتوه ـ ًا فهــذا صحيــح وأمــا ا ذكــره املدعــى عليــه مــن كونــه ولي ـ ًا‬\n‫عليــه ومــن تنــازل مورثــي عــن العقــار محــل الدعــوى ‪ ....‬فهــذا ال علــم‬\n‫لــي بــه هكــذا قــرر وقــد جــرى االطــاع علــى الصــك محــل الدعــوى‬\n‫فوجدتــه صــادر ًا مــن كتابــة العــدل األولــى مبكــة املكرمــة برقــم‬\n‫‪ 13/67‬يف ‪1420/5/28‬ه ـ ويتضمــن تنــازل مــورث املدعــن علــي بــن‬\n‫‪.........‬لكامــل الــدار أرض ـ ًا وبنــاء البنــه ‪.........‬بــدون ثمــن لوجــه اهلل‬\n‫ا ال علــم لــي بهــذا الصــك‬    ‫تعالــى أه ـ وبعرضــه علــى املدعــي قــرر قائ ـ ً‬\n‫هكــذا قــرر وقــد ســبقت الكتابــة منــا لكتابــة العــدل األولــى بخطابنــا‬\n\n\n                                                                                           ‫‪288‬‬\n\f      ‫رقــم ‪ 332007478‬يف ‪1433/11/14‬ه ـ وذلــك لالستفســار عــن العقــار‬\n      ‫محــل الدعــوى منهــم اجلــواب رقــم ‪ 332058549‬يف ‪1433/11/24‬ه ـ‬\n      ‫واملتضمــن مطابقــة الصــك لســجله وســريان مفعولــه حتــى تاريخــه أه ـ‬\n      ‫ولالستفســار عــن صــك الواليــة وتأمــل القضيــة فقــد رفعــت اجللســة‬\n      ‫ويف يــوم الســبت املوافــق‪ 1434/07/08‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫وفيهــا حضــر املدعــي أصالــة حــال حضــور املدعــى عليــه واليــة وقــد‬\n      ‫ســبقت الكتابــة منــا ملديــر الســجالت بهــذه احملكمــة بخطابنــا رقــم‬\n                                                     ‫‪ 34492862‬يف ‪1434/2/26‬ه ـ‬\n      ‫فوردنــا اجلــواب منه شــرح ًا على خطابنــا بتاريخ ‪1434/3/1‬هـ واملتضمن‬\n      ‫مطابقة الصك لســجله وســريان مفعوله حتى تاريخه أهـ وقد جرى مني‬\n      ‫االطــاع علــى صــك حصــر ورثــة مــورث املدعــي واملدعــى عليــه ووجدتــه‬\n      ‫مطابــق ملــا جــاء يف الدعــوى وبســؤال الطرفــن هــل لديكمــا مــا تريــدان‬\n      ‫إضافتــه فأجابــا بالنفــي فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫ومبــا أن املدعــي يطلــب احلكــم ببيــع العقــار املذكــور يف الدعــوى بنــاء‬\n      ‫علــى أنــه ملــك ملورثــه والــده ‪.........‬وتســليمه نصيبــه الشــرعي منــه وإلــزام‬\n      ‫املدعــى عليــه بتســليمه صــك امللكيــة اخلــاص بالعقــار ولدفــع املدعــى‬\n      ‫عليــه واليــة بــأن العقــار ليــس ملــك ًا للمــورث وأنــه ملــك ملــن حتــت واليتــه‬\n      ‫وهــو أخــاه الشــقيق ‪.........‬وأن والــده قــد تنــازل لــه قبــل موتــه لكونــه‬\n      ‫معاق ـ ًا ومعتوه ـ ًا وبعــد االطــاع علــى صــك امللكيــة واملتضمــن انتقــال‬\n      ‫ملكيــة العقــار محــل الدعــوى مــن ملــك مــورث املدعــي إلــى أحــد الورثــة‬\n      ‫‪.........‬بتاريــخ ‪1420/5/28‬ه ـ وحيــث جــرى االستفســار عــن ســجل‬\n      ‫الصــك وورد اجلــواب مبطابقــة الصــك لســجله وســريان مفعولــه وعــدم‬\n      ‫وجــود مــا يخــل بــه وإلقــرار املدعــي بعــدم علمــه مبــا ذكــره املدعــى عليــه‬\n\n\n‫‪289‬‬\n\f‫واليــة وألن عــدم علــم املدعــي ليــس لــه أثــر يف ذلــك وملــا قــرره الفقهــاء‬\n‫رحمهــم اهلل تعالــى مــن جــواز تخصيص األب بعض األوالد ملعنى يقتضي‬\n‫تخصيصــه مثــل اختصاصــه بحاجــة أو زمانــه أو عمــى أو كثــرة عائلــة‬\n‫أو اشــتغاله بالعلــم أو نحــوه مــن الفضائــل أو صــرف عطيتــه عــن بعــض‬\n‫ولــده لفســقه أو بدعتــه أو لكونــه يســتعني مبــا يأخــذه علــى معصيــة اهلل‬\n‫أو ينفقــه فيهــا (ينظــر املغنــي ‪/‬ج‪ 8/‬ص ‪ )258‬وكذلــك ملــا قــرره أهــل‬\n‫العلــم رحمهــم اهلل مــن ثبــوت الهبــة ملــن وهبــت لــه بعــد مــوت األب قــال‬\n‫ابــن قدامــه رحمــه اهلل يف املغنــي مســألة ‪ :‬قــال (فــإن مــات ولــم يــردده‬\n‫فقــد ثبــت ملــن وهــب ولــه إذا كان ذلــك يف صحتــه ) يعنــي إذا فاضــل‬\n‫بــن ولــده يف العطايــا أو خــص بعضهــم بعطيــة ثــم مــات قبــل أن يســترده‬\n‫ثبــت ذلــك للموهــوب لــه ولــزم وليــس لبقيــة الورثــة الرجــوع أه ـ املغنــي‬\n‫(ج‪ 8/‬ص ‪ 269‬ـ ‪)270‬وقال يف حاشــية الروض املربع شــرح زاد املســتقنع‬\n‫(ج‪ 6/‬ص ‪ )18‬فــإن مــات الواهــب قبلــه أي قبــل الرجــوع أو الزيــادة ثبتــت‬\n‫للمعطــي فليــس لبقيــة الورثــة الرجــوع ) لذلــك فقــد صرفــت النظــر عــن‬\n‫طلــب املدعــي وأفهمتــه بأنــه ال يســتحق مــا جــاء يف دعــواه وأخليــت ســبيل‬\n‫املدعــى عليــه منهــا وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن‬\n‫قــرر املدعــى عليــه واليــة القناعــة بذلــك أمــا املدعــي فقــد قــرر عــدم‬\n‫القناعــة ويطلــب االســتئناف بالئحــة اعتراضيــة فأجيــب لطلبــه و وأفهــم‬\n‫أن عليــه مراجعــة احملكمــة يف يــوم الســبت املوافــق ‪1434/7/15‬ه ـ‬\n‫الســتالم نســخة مــن احلكــم وإبــداء معارضتــه عليــه كمــا أفهمتــه أن‬\n‫مــدة االعتــراض ثالثــون يومـ ًا مــن هــذا التاريــخ وأنــه إن لــم يعدهــا خاللها‬\n‫فــإن حقــه يف االعتــراض يكــون ســاقط ًا ويكتســب احلكــم القطعيــة‬\n‫ففهــم ذلــك ‪ ..‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n                                                                                       ‫‪290‬‬\n\f                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/07/08‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/10/21‬ه ـ‬\n      ‫افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف برقــم‬\n      ‫‪ 331873260‬يف ‪1434/9/23‬ه ـ وبرفقهــا القــرار رقــم ‪ 34321703‬يف‬\n      ‫‪1434/9/17‬ه ـ ونــص احلاجــة منــه ‪ :‬وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن‬\n      ‫املدعــي ذكــر أن املدعــى عليــه وإخوتــه قــد حتايلــوا علــى والــده وإقناعــه‬\n      ‫بالتنــازل ألخيهــم املذكــور فعلــى فضيلتــه فتــح جلســة للطرفني ومســائلة‬\n      ‫املدعــي عــن هــذا التحايــل وكيفيتــه ومناقشــتهما عــن حــال والدهمــا‬\n      ‫حــن التنــازل وصحتــه وهــل كان يعانــي مــن مــرض وإن كان فمــا هــو‬\n      ‫املــرض الــذي يعانــي منــه وهــل لــه أمــاك غيــر هــذا البيــت واســتجالء‬\n      ‫حقيقــة هــذه الهبــة بــراء ًة للذمــة أه ـ فعليــه أجيــب أصحــاب الفضيلــة بــأن‬\n      ‫العقــار محــل الدعــوى مت إفراغــه للمدعــى عليــه واليــة وليــس للمدعــى‬\n      ‫عليــه أصالــة وذلــك لــدى كاتــب العــدل بتاريــخ ‪1420/5/28‬ه ـ واألصــل‬\n      ‫يف الصكــوك الصــادرة مــن كتابــة العــدل صحتهــا وســامتها وقبولهــا‬\n      ‫وعــدم الطعــن فيهــا وال يتــم إفــراغ العقــار إال بعــد نظــر كاتــب العــدل يف‬\n      ‫حالــة البائــع أو الواهــب املعتبــرة شــرع ًا وإذا كان البائــع أو الواهــب غيــر‬\n      ‫مؤهــل لذلــك فلــن يتــم إجــراء اإلفــراغ كمــا أن مــورث الطرفــن قــد تويف‬\n      ‫يف ‪1424/5/16‬ه ـ واملــدة بــن اإلفــراغ والوفــاة ليســت قريبــة وإذا كان‬\n      ‫املدعــي يطعــن بالصــك أو اإلفــراغ فعليــه التقــدم لــدى اجلهــات املختصــة‬\n      ‫للتحقيــق يف موضــوع اإلفــراغ مــن شــخص فاقــد األهليــة وعنــد ثبــوت‬\n      ‫ذلــك لــدى اجلهــات املختصــة فيتــم التهميــش علــى صــك امللكيــة بذلــك‬\n      ‫وعليــه فإنــه لــم يظهــر لــي خــاف مــا حكمــت بــه وأمــرت بضبــط ذلــك‬\n\n\n‫‪291‬‬\n\f‫واحلاقــه بصكــه وســجله وإعــادة كامــل أوراق املعاملــة إلــى محكمــة‬\n‫االســتئناف حســب املتبــع وبــاهلل التوفيــق ‪ ..‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/10/21‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 331873260‬وتاريــخ‬\n‫‪1434/11/6‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪.........‬‬\n‫باحملكمــة العامــة مبكــة املكرمــة برقــم ‪ 34265813‬وتاريــخ‬\n‫‪1434/7/11‬ه ـ املتضمــن دعــوى ‪.........‬ضــد ‪ ،.........‬وبدراســة الصــك‬\n‫وصــورة ضبطــه الئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n‫احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى‬\n                                   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪292‬‬\n\f293\n\f294\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":285,"source_page_end":294,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"213b187b04c13e00276ef5281286219e77c0e0983fcecaeebaaaa130ce83fe99","normalized_text_hash":"5e59641007cc9087cdd2d4ebb6f6e1eece7da5dfb53d5b19094fd9c2a84b9398","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p285-34265813"},{"id":"e5da3568-8293-5b81-a374-0de33c8e2d70","document_type":"judgment","category":"judicial","subcategory":"general","title":"تركة -إدعاء صورية عقد متلك أرض -حترير صك التملك باسم اإلبن لكون األب غير سعودي -رفض املدعي مين املدعى عليه -شهادة منقوصة -دليل غير موصل -بقاء حق املدعى يف اليمن النافية ولو بعد احلكم.","document_number":"33358233","case_number":"3374028","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/27","year":"1434","subject":"تركة -إدعاء صورية عقد متلك أرض -حترير صك التملك باسم اإلبن لكون األب غير سعودي -رفض املدعي مين املدعى عليه -شهادة منقوصة -دليل غير موصل -بقاء حق املدعى يف اليمن النافية ولو بعد احلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33358233 :‬تاريخه‪1433/7/27 :‬هـ‬\n                          ‫رقم الدعوى‪3374028 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34230712‬تاريخه‪1434/6/5 :‬هـ‬\n\n\n      ‫تركــة ‪ -‬إدعــاء صوريــة عقــد متلــك أرض ‪ -‬حتريــر صــك التملــك‬\n      ‫باســم اإلبــن لكــون األب غيــر ســعودي ‪ -‬رفــض املدعــي ميــن املدعــى‬\n      ‫عليــه ‪ -‬شــهادة منقوصــة ‪ -‬دليــل غيــر موصــل ‪ -‬بقــاء حــق املدعــى يف‬\n                                            ‫اليمــن النافيــة ولــو بعــد احلكــم‪.‬‬\n\n\n\n      ‫قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى مــن‬\n                                                                           ‫أنكــر)‪.‬‬\n\n\n\n      ‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه بأنــه قــد تــويف مــورث موكليــه‬\n      ‫ومــورث املدعــى عليــه والدهــم وخلــف مــن ضمــن تركتــه النصــف مــن‬\n      ‫املزرعــة الواقعــة بالفــرش ضواحــي ينبــع البحــر ومملوكــة بصــك صــادر‬\n      ‫مــن محكمــة ينبــع ومســجله باســم ابنــه املدعــى عليــه لكونــه ســعودي ًا‬\n      ‫ويطلــب احلكــم ببيعهــا وتســليم موكليــه نصيبهــم هكــذا ادعــى‪،‬‬\n      ‫أجــاب املدعــى عليــه باملصادقــة علــى ملكيتــه لــأرض وأنكــر أنهــا‬\n      ‫لوالــده‪ ،‬بينــة املدعــي شــاهد شــهد بــأن مــورث املدعــن واملدعــى عليــه‬\n      ‫أخبــره بشــراء أرض يف ينبــع ولــم يخبــره عــن مكانهــا أو تفاصيــل أخــرى‬\n      ‫وليــس للمدعــي بينــة أخــرى فجــرى إفهامــه بــأن لــه ميــن املدعــى عليــه‬\n      ‫فلــم يقبل‪،‬مبــا أن املدعــي ال بينــة لديــه موصلــة ولقولــه صلــى اهلل عليــه‬\n\n‫‪295‬‬\n\f‫وســلم (البينــة علــى املدعــي واليمــن علــى مــن أنكــر) تقــدر احلكــم‬\n‫بــرد الدعــوى وإفهــام املدعــي وكالــة بــأن ملوكليــه ميــن املدعــى عليــه‬\n‫متــى مــا طلبوهــا‪ ،‬قنــع املدعــى عليــه باحلكــم واعتــرض املدعــي وكالــة‬\n‫بالئحة‪،‬صــدق احلكــم مــن محكمــة االســتئناف مبنطقــة مكــة‬\n                                                                 ‫املكرمــة ‪.‬‬\n\n\n\n‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد فلدي أنا ‪...‬‬\n‫القاضــي يف احملكمــة العامــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة باملدينــة املنورة برقــم ‪3374028‬‬\n‫وتاريــخ ‪1433/01/29‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33193029‬وتاريــخ‬\n‫‪1433/01/29‬ه ـ ففــي يــوم األحــد املوافق‪1433/03/20‬ه ـ حضــر ‪...‬‬\n‫ا عــن نفســه‬‫ســعودي بالســجل املدنــي ‪ ...‬الوكيــل عــن ‪ ...‬بصفتــه أصيـ ً‬\n‫ا عــن ‪ ، ...‬و‪ ، ...‬و‪ ، ...‬و‪ ، ...‬و‪ ، ...‬و‪ ، ...‬و‪ ، ...‬و‪ ، ...‬و‪،...‬‬        ‫ووكي ـ ً‬\n‫و‪ ......‬ووكالــة احلاضــر رقمهــا ‪ 11179‬يف‪1433/02/13‬ه ـ صــادرة‬\n‫مــن كتابــة العــدل الثانيــة باملدينــة املنــورة ‪ ،‬وعــن ‪ ...‬بصفتــه ووكيــا‬\n‫عــن‪ ...‬ووكالــة احلاضــر رقمهــا ‪ 29032‬يف ‪1433/04/24‬ه ـ صــادرة مــن‬\n‫كتابــة العــدل الثانيــة باملدينــة املنــورة وجميــع مــن ُذكــر مــن املدعــن‬\n‫أصالــة واملدعــى عليــه هــم مــن انحصــر إرث ‪ ...‬فيهــم مبوجــب الصــك‬\n‫الصــادر مــن هــذه احملكمــة برقــم ‪ 3262012‬يف ‪ 1432 /4/3‬ه ـ وادعى‬\n‫علــى احلاضــر معــه ‪ ...‬ســعودي بالســجل املدنــي رقــم ‪ ...‬قائــا ‪ :‬لقــد‬\n‫ٌتــويف مــورث موكلــي ومــورث املدعــى عليــه والدهــم وخلــف مــن ضمــن‬\n‫تركتــه النصــف مــن املزرعــة الواقعــة ‪ ...‬ضواحــي ينبــع البحــر احملــدودة‬\n\n                                                                                       ‫‪296‬‬\n\f      ‫شــماال وجنوبــا بالصمــد وشــرقا ملــك ‪ ...‬والبعــض الصمــد وغربــا ملــك ‪...‬‬\n      ‫والبعــض الصمــد واململوكــة بالصــك رقــم ‪ 366‬والصــادر مــن محكمــة‬\n      ‫ينبــع وقــد ســجله باســم ابنــه املدعــى عليــه لكونــه ســعوديا أطلــب‬\n      ‫احلكــم ببيعهــا وتســليم موكلــي مــا يخصهــم هــذه دعــواي ‪ .‬وبســؤال‬\n      ‫املدعــى عليــه ‪ ،‬أجــاب قائــا ‪ :‬مــا ذكــره املدعــي وكالــة مــن أن املزرعــة‬\n      ‫املذكــورة باســمي صحيــح وهــي ملــك لــي ولــي شــريكني فيهــا وهمــا ‪...‬‬\n      ‫و‪ ...‬وهــي بيننــا بالســوية وليــس لوالــدي ملــك فيهــا ‪ ،‬ثــم ســألت املدعــي‬\n      ‫وكالــة ‪ :‬هــل لديــه بينــة ؟ قــال نعــم ثــم احضــر للشــهادة ‪ ...‬مينــي اجلنســية‬\n      ‫ا بــأن والــد احلاضــر ‪ ...‬قــد زارنــي‬      ‫مبوجــب اإلقامــة رقــم ‪ ...‬وشــهد قائ ـ ً‬\n      ‫يف جــدة وقلــت لــه مــا تركــت شــيئا ألوالدك قــال عنــدي خيــر واشــتريت‬\n      ‫أرض يف ينبــع ولــم يخبرنــي عــن مكانهــا أو أي تفاصيــل أخــرى هــذا‬\n      ‫مــا لــدي مــن شــهادة وبعــرض ذلــك علــى املدعــى عليــه قــال الشــاهد ال‬\n      ‫أقــول فيــه شــيئا وشــهادته غيــر صحيحــة ووالــدي أخطــأ عندمــا قــال‬\n      ‫ذلــك ؛ ثــم ســألت املدعــي وكالــة هــل لديــه زيــادة بينــة قــال ال فأفهمتــه‬\n      ‫أن لــه ميــن املدعــى عليــه قــال ال أرغــب يف ميينــه فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة وحيــث ال بينــة موصلــة للمدعــي وكالــة وقــد قــال‬\n      ‫كــر))‬  ‫ن َعلــى َمــنْ أ ْن َ‬\n                                   ‫واليمِ ـ ُ‬\n                                         ‫البي َنـ ُة َعلــى امل َُّدعــي َ‬\n                                                                       ‫صلــى اهلل عليــه وســلم (( َ‬\n      ‫لذلــك كلــه فقــد رددت دعــوى املدعــي وكالــة وأخليــت ســبيل املدعــى‬\n      ‫عليــه وبــه حكمــت وأفهمــت املدعــي وكالــة بــأن ملوكليــه ميــن املدعــى‬\n      ‫عليــه متــى مــا طلبوهــا وبعــرض ذلــك علــى الطرفــن قنــع بــه املدعــى عليــه‬\n      ‫ولــم يقنــع بــه املدعــي وكالــة فأفهــم مبقتضــى تعليمــات االســتئناف‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                          ‫أجمعــن ‪.‬‬\n\n\n‫‪297‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن ‪1434/06/19‬ه ـ وردتنــا‬\n‫املعاملــة مــن رئيــس محكمــة االســتئناف املكلــف مبكــة املكرمــة‬\n‫برقــم ‪ 3491069‬يف ‪1434/06/11‬ه ـ مرفقــا بهــا قــرار الدائــرة‬\n‫احلقوقيــة الرابعــة رقــم ‪ 34230712‬يف ‪1434/06/05‬ه ـ ونــص احلاجــة‬\n‫منــه (( وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت‬\n‫املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر املبنــي علــى قــرار الدائــرة‬\n‫رقــم ‪ 341284‬يف ‪1434/01/04‬ه ـ )) أ‪.‬ه ـ قاضــي اســتئناف د‪ ....‬ختمــه‬\n‫وتوقيعــه قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ ...‬ختمــه‬\n‫وتوقيعــه حتــى ال يخفــى جــرى إثباتــه ؛ وبــاهلل التوفيــق وصلــى اهلل علــى‬\n                                    ‫بنينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪298‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":295,"source_page_end":298,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"246f45c67bd411cd1f65359d4920f86bcb337f0149b097c1ff0a9d2dab695f59","normalized_text_hash":"3f60a949e31c06e85ce70ffb9203b1726767ccf141173978440d169b9973b985","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p295-33358233"},{"id":"c248b117-bf36-5082-b4f1-1d4793175f74","document_type":"judgment","category":"judicial","subcategory":"general","title":"قسمة تركة -وفاة مورث وترك تركة داخل وخارج اململكة -مطالبة املدعية أصالة عن نفسها ووكالة عن أخواتها بأخذ نصيبهم من التركة بعد خصم ما مت استالمه -ضعف البينة -حلف طريف اخلصومة اليمن على انكار استالمهم باقي اإلرث -نقل املورث بعض األماك إلى املدعى عليه كوصية -ال وصية لوارث -عدم اختصاص المحكمة بنظر الدعاوى املتعلقة بعقار خارج اململكة- إلزام املدعى عليه بدفع نصيب املدعيات ورد ما عدا ذلك من","document_number":"3448838","case_number":"3347353","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/12/26","year":"1434","subject":"قسمة تركة -وفاة مورث وترك تركة داخل وخارج اململكة -مطالبة املدعية أصالة عن نفسها ووكالة عن أخواتها بأخذ نصيبهم من التركة بعد خصم ما مت استالمه -ضعف البينة -حلف طريف اخلصومة اليمن على انكار استالمهم باقي اإلرث -نقل املورث بعض األماك إلى املدعى عليه كوصية -ال وصية لوارث -عدم اختصاص المحكمة بنظر الدعاوى املتعلقة بعقار خارج اململكة- إلزام املدعى عليه بدفع نصيب املدعيات ورد ما عدا ذلك من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪3448838 :‬تاريخه‪1434/12/26 :‬هـ‬\n                        ‫رقم الدعوى‪3347353 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪342508599‬تاريخه‪1434/6/25 :‬هـ‬\n\n\n      ‫قســمة تركــة‪ -‬وفــاة مــورث وتــرك تركــة داخل وخــارج اململكة‪ -‬مطالبة‬\n      ‫املدعيــة أصالــة عــن نفســها ووكالــة عــن أخواتهــا بأخــذ نصيبهــم مــن‬\n      ‫التركــة بعــد خصــم مــا مت اســتالمه‪ -‬ضعــف البينــة‪ -‬حلــف طــريف‬\n      ‫اخلصومــة اليمــن علــى انــكار اســتالمهم باقــي اإلرث‪ -‬نقــل املــورث‬\n      ‫بعــض األمــاك إلــى املدعــى عليــه كوصيــة‪ -‬ال وصيــة لــوارث‪ -‬عــدم‬\n      ‫اختصــاص احملكمــة بنظــر الدعــاوى املتعلقــة بعقــار خــارج اململكــة‪-‬‬\n      ‫إلــزام املدعــى عليــه بدفــع نصيــب املدعيــات ورد مــا عــدا ذلــك مــن‬\n                                                                       ‫طلبــات ‪.‬‬\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم (علــى اليــد مــا أخــذت حتــى تؤديــه) رواه‬\n                                                                            ‫األربعة‪.‬‬\n      ‫‪ .2‬ملــا روي (أن النبــي صلــى اهلل عليــه وســلم قضــى أن اليمــن علــى‬\n                                                   ‫املدعــى عليــه) رواه البخــاري‪.‬‬\n      ‫‪ .3‬قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى‬\n                                                   ‫املدعــى عليــه) رواه الترمــذي‪.‬‬\n           ‫‪ .4‬قوله صلى اهلل عليه وسلم (ال وصية لوارث) رواه اإلمام أحمد‪.‬‬\n                                       ‫‪ .5‬املادة ‪ 28‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n‫‪299‬‬\n\f‫أقامــت املدعيــة دعواهــا باألصالــة عــن نفســها وبالوكالــة عــن أخواتهــا‬\n‫قائلــة أن والدهــا تــويف وخلــف تركــة كبيــرة داخــل اململكــة العربيــة‬\n‫الســعودية وخارجهــا‪ ،‬وقــد اســتلمت وأخواتهــا بعــد الوفــاة مبالــغ تخــص‬\n‫مورثهــم مت توزيعهــا عليهــم‪ ،‬لــذا تطالــب بأخــذ نصيبهــا وأخواتهــا مــن‬\n‫التركــة بعــد خصــم مــا مت اســتالمه‪ ،‬مت نقــل ملكيــة بعــض العقــارات‬\n‫واملبالــغ إلــى املدعــى عليــه مبوجــب وصيــة‪ ،‬وقــد أنكــرت املدعيــة‬\n‫هــذه الوصيــة لبطالنهــا ملخالفتهــا احلديــث النبــوي الشــريف (ال وصيــة‬\n‫لــوارث) مت إفهــام الطرفــن أن الدعــاوى املتعلقــة بعقــار خــارج اململكــة‬\n‫ـاء علــى املــادة (‪ )28‬مــن‬\n                          ‫تخــرج عــن اختصــاص محاكــم اململكــة بنـ ً‬\n‫نظــام املرافعــات الشــرعية‪ ،‬بعــد املداولــة حكمــت احملكمــة بالقــدر‬\n‫املتيقــن وذلــك بقيــام املدعــى عليــه بدفــع مبالــغ معينــة للمدعيــات‬\n‫ورد مــا عــدا ذلــك مــن طلبــات لعــدم ثبوتهــا‪ ،‬قنعــت املدعيــة باحلكــم‬\n‫واعتــرض املدعــى عليهمــا بالئحــة‪ ،‬متــت مصادقــة احلكــم مــن محكمــة‬\n                                           ‫االســتئناف مبكــة املكرمــة‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 3347353‬وتاريــخ‬\n‫‪1433/01/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33122398‬وتاريــخ‬\n‫‪1433/01/18‬ه ـ ففــي يــوم الثالثــاء املوافق‪1433/02/16‬ه ـ افتتحــت‬\n\n                                                                                ‫‪300‬‬\n\f      ‫اجللســة الســاعة ‪ 08 : 17‬وفيهــا حضــرت ‪ .....‬لبنانيــة اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم ‪ .....‬واملعــرف بهــا مــن قبــل املدعــى عليهمــا ‪ ،‬وادعــت علــى‬\n      ‫احلاضرين معها ‪ .....‬لبناني اجلنسية مبوجب اإلقامة رقم ‪2028601983‬‬\n      ‫‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬قائلــة ‪ :‬لقــد تــويف‬\n      ‫والدي يف عام ‪1985‬م وخلف تركة ‪ ،‬منها ما كان باســم ‪ .....‬ســعودي‬\n      ‫اجلنســية باعهــا املدعــى عليــه ‪ .....‬واســتلم قيمتهــا ‪ ،‬ومنهــا ما كان باســم‬\n      ‫‪ .....‬ســعودية اجلنســية مت بيعهــا واســتلمت نصيبــي منهــا ‪ ،‬ومنهــا مــا كان‬\n      ‫باســم املدعــى عليــه ‪ .....‬بنــاء علــى إقــرار محــرر منــه بــأوراق الورشــة‬\n      ‫‪ ........................‬يتضمــن ‪ :‬أن جميــع األراضــي التــي باســمي وهــي برقــم‬\n      ‫‪ .....‬و ‪ .....‬مخطط ‪ ......‬والقطعة ‪ .....‬هي ملك والدي ‪ .....‬والورشة املباعة‬\n      ‫مــن الســيد ‪ .....‬هــي ملــك لوالــدي وإخوتــي بعــد مــوت والــدي وجميــع مــا‬\n      ‫فيهــم مــن بضاعــة وأغــراض بضاعــة وليــس لــي فيهــا أي شــيء اجلميــع‬\n      ‫باســمي فقــط وال أملــك مــن ذلــك شــيئا واجلميــع باســمي فقــط ‪ ،‬وموقــع‬\n      ‫مــن قبــل املقــر‪ ،‬وبشــهادة وتوقيــع‪ .....‬واملدعــى عليــه ‪ ، ....‬ومبلــغ ‪30‬‬\n      ‫ألــف ريــال هــي عبــارة عــن إبــراء ذمــة شــخص كان للمــورث مــال عنــده‬\n      ‫اســتلمتها وســلمت الورثــة مــن النســاء نصيبهــم فقــط ‪ ،‬ومبلــغ ‪ 100‬ألــف‬\n      ‫ريــال مت حتصيلهــا مــن ورثــة‪ .....‬ال أعلــم مــن اســتلمها ‪ ،‬ومبلــغ ‪ 60‬ألــف‬\n      ‫ريــال مت حتصيلهــا مــن‪ .....‬اســتلمها املدعــى عليــه علــي ‪ ،‬ومبلــغ ‪ 5‬آالف‬\n      ‫ريــال مت حتصيلهــا مــن‪ .....‬اســتلمها املدعــى عليــه علــي ‪ ،‬وبضاعــة عبــارة‬\n      ‫حديــد وأملونيــوم وإكسســوارات األملونيــوم وســيارات وعفــش البيــت‬\n      ‫والســكاكني وراعفــة شــوكية ‪ ،‬وأطلــب إلزامهمــا بتســليمي نصيبــي‬\n      ‫مــن هــذه التركــة‪ .‬هــذه دعــواي‪ .‬وبعــرض ذلــك علــى املدعــى عليهمــا‬\n      ‫قــاال‪ :‬نطلــب اإلمهــال للــرد‪ .‬وقــرر املدعــى عليــه قائــا ‪ :‬أمــا مــا يخــص‬\n\n\n‫‪301‬‬\n\f‫اإلقــرار املشــار إليــه ســابقا فإننــي مقــر مبــا فيــه ‪ .‬ثــم رفعت اجللســة لذلك‪.‬‬\n‫ويف يــوم الثالثــاء املوافــق‪ 1433/05/11‬ه ـ افتتحــت اجللســة الســاعة ‪30‬‬\n‫‪ 09 :‬وفيهــا حضــر املدعيــة واملدعــى عليهمــا واملعــرف باملدعيــة مــن قبــل‬\n‫املدعــى عليهمــا‪ ،‬وأبــرزت املدعيــة ســند توكيــل عــام صــادر مــن دائــرة‬\n‫الكاتبــة العــدل يف املينــاء باجلمهوريــة اللبنانيــة بعــدد ق ‪ 16‬لعــام ‪2012‬‬\n‫م واملصــادق عليــه مــن اجلمهوريــة اللبنانيــة قســم املصادقــات و املصــادق‬\n‫عليهــا مــن مكتــب التصديــق مــن وزارة العــدل واملتضمــن حضــور كال‬\n‫من ‪ ..... -1‬لبنانية اجلنســية مواليد عام ‪1977‬م رقم الســجل ‪ / .....‬حلبا‬\n‫عــكار بالبطاقــة رقــم ‪ .....‬تاريــخ ‪2009/12/1‬م باألصالــة عــن نفســها‬\n‫وبوكالتهــا العامــة القضائيــة عــن ‪ .....‬الــواردة مــن الســفارة اللبنانيــة‬\n‫برقــم ‪ 2009/1074‬تاريــخ ‪ 2009/8/4‬م واملصــادق عليهــا أصــوال مــن‬\n‫وزارة اخلارجيــة اللبنانيــة ‪/141392‬م تاريــخ ‪2009/8/12‬م وبوكالتهــا‬\n‫اخلاصــة عــن ‪ .....‬الــواردة مــن قنصليــة لبنــان الفخريــة يف تورنتــو ‪ /‬كنــدا‬\n‫برقــم عــام ‪ 2009/306‬رقــم خــاص ‪ 2009/284‬تاريــخ ‪2009/7/15‬م‬\n‫واملصــادق عليهــا أصــوال مــن وزارة اخلارجيــة اللبنانيــة رقــم ‪141393‬‬\n‫تاريــخ ‪2009/8/12‬م ‪ ..... -2‬لبنانيــة اجلنســية مواليــد عــام ‪1969‬م رقــم‬\n‫الســجل ‪/ .....‬حلبــا عــكار بالبطاقــة رقــم ‪ .....‬تاريــخ ‪1992/3/17‬م ‪،‬‬\n‫وقررتــا مبــا يلــي وكلنــا وفوضنــا شــقيقتنا باســمة ‪ .....‬املقيمــة يف جــدة‬\n‫اململكــة العربيــة الســعودية للمرافعــة واملدافعــة عنــا بــكل دعــوى لنــا‬\n‫أم علينــا مــع أي شــخص كان وبــأي صفــه كانــت ‪ ،‬مــع حــق الصلــح‬\n‫واالقــرار واالبــراء والرجــوع عــن احلــق او الدعــوى وقبــول الرجــوع‬\n‫واســترداد الرســوم والكفــاالت ‪ ،‬وقــدم املدعــى عليهمــا مذكــره هــذا‬\n‫نصهــا ‪ :‬ردا علــى الدعــوى املقامــة ضــدي مــن شــقيقتي ‪ .....‬وتدعــي بأنني‬\n\n\n                                                                                         ‫‪302‬‬\n\f      ‫قمــت بعــدم إعطائهــا ميــراث أبيهــا املغفــور لــه بــأذن اهلل ‪ .....‬املتوفــى‬\n      ‫مــن حوالــي تســعة وعشــرون عامــا ودفــن يف مســقط رأســه لبنــان وبعــد‬\n      ‫شــهرين مــن وفاتــه طلبــت مــن والدتــي ‪ ........‬وهــي بحمــد اهلل موجــودة‬\n      ‫تــرزق لكنهــا مريضــة مبــرض الزهيمــر ويف حالــة متقدمــة جــدا حســب‬\n      ‫التقريــر الطبــي مرفــق صورتــه لفضيلتكــم ؛ طلبــت منهــا أن يتــم الوضــع‬\n      ‫كمــا كان يف حالــة حيــاة والــدي ألننــي كنــت الســند والــذراع اليمنــى‬\n      ‫لوالــدي مــن بعــد اهلل يف إدارة إعمالــه وأموالــه حيــث أنهــم الورثــة كانــوا‬\n      ‫خمســة بنــات مقيمــن باململكــة وأخــي ‪ .....‬كان مقيــم بلبنــان وجميــع‬\n      ‫مراحــل دراســته بلبنــان وكنــت اعلــم بالــواردة والشــاردة والصغيــرة‬\n      ‫والكبيــرة ‪ ،‬فضيلــة القاضــي اقســم بــاهلل العظيــم إننــي كنــت اعمــل‬\n      ‫مــع والــدي منــذ كان عمــري عشــرة ســنوات كانــت إجازاتــي املدرســية‬\n      ‫ال اعرفهــا كلهــا اقضيهــا بالعمــل مــع الوالــد كان إخوتــي يســافرون‬\n      ‫مــع الوالــد والوالــدة خــارج اململكــة يف اإلجــازات والعطــات وأكــون‬\n      ‫إنــا بالعمــل وأول إجــازة أخذتهــا وســافرت خــارج اململكــة ألول مــره إلــى‬\n      ‫األمــارات العربيــة كان عمــري عشــرون عامــا وكانــت خمســة عشــر‬\n      ‫يومــا جلســت فيهــا عنــد شــقيقتي التــي تصغرنــي مقيمــة بأمــارة العــن‬\n      ‫‪ ،‬فضيلــة القاضــي عندمــا طلبــت مــن الوالــدة بعــد وفــاة الوالــد أن يتــم‬\n      ‫الوضــع كمــا كان يف حيــاة والــدي ألننــي كنــت متأكــد إن كل‬\n      ‫مــا بنــاه الوالــد رحمــة اهلل عليــه خــال حياتــه ســيدمر ويندثــر فرفضــت‬\n      ‫وقامــت بشــكوتي باحملكمــة الشــرعية الكبــرى مبنطقــة بــاب شــريف‬\n      ‫وتدخــل كبــار عائلــة الوالــدة منهــم مــن مــات ومنهــم مــا زال حــي يــرزق‬\n      ‫وقمــت مبحاســبة والدتــي لوجودهــا دون الورثــة بالســعودية مــا لوالــدي‬\n      ‫ومــا عليــه وســلمتها مــا كان بحوزتــي مــن مســتندات وأوراق تخــص‬\n\n\n‫‪303‬‬\n\f‫أعمــال الوالــد وأمــا بالنســبة إلــى أرض مخطــط اجلبيــري بجنــوب جــده‬\n‫منطقــة اخلمــره فهــم ثالثــة قطــع بصــك واحــد فقلــت لهــا إن والــدي‬\n‫أوصــى بهمــا لــي بعــد مماتــه ألننــي لــم يكتــب لــي أمــاكا كمــا كتــب‬\n‫ألخوتــي اخلمســة وأخــي ‪ .....‬يف لبنــان وأنتــي تعلمــن بوصيتــه ومبشــهد‬\n‫أخــي ‪ .....‬وزوجتــه علــى وصيــة والــدي وكذلــك رواتــب خمســة ســنوات‬\n‫عملــت بهــا عنــد والــدي مــن عــام ‪ 1400‬حتــى منتصــف عــام ‪ 1406‬مائــة‬\n‫وثمانــون إلــف ريــال فرفضــت فاتفقــت معهــا علــى إن قيمــة األرض قدرت‬\n‫عــام ‪ 1406‬مائتــان وخمســون إلــف ريــال تأخــذ الوالــدة ‪ .....‬ســند أمانــه‬\n‫علــى أختهــا ‪ .....‬باعتــراف ‪ .....‬وعلمهــا مببلــغ مائــة وخمســون إلــف ريــال‬\n‫وليــس كمامنهــم‪ ،‬إمــام فضيلتكــم ثالثمائــة إلــف ألن خالتــي مقيمــه‬\n‫بدولــة األردن وباقــي املبلــغ املائــة إلــف مــا تبقــى لــي وكل مــا أخذتــه مــن‬\n‫ارث أبــي والكــن دفعتهــا ديــن عــن إعمــال والــدي كنــت وقتهــا القائــم‬\n‫بأعمــال الوالــد مائــة وثمانــون إلــف ريــال ل‪ .....‬وقــد توفــى قبــل ســنتان‬\n‫وقــد أصــدر صــك شــرعي علــي عنــد فضيلــة القاضــي ‪ ، .....‬وكذلــك‬\n‫ســجنت ثالثــة شــهور ألن يف حيــاة الوالــد كنــت أنــا اســتلم الشــيكات‬\n‫املكتوبــة باســم والــدي مــن العمــاء وأوقــع علــى صــورة االســتالم‬\n‫الشــيكات وبعــد وفــاة والــدي بســنتان ادعــى علــي‪ ..... /‬وكان برتبــة‬\n‫لــواء يف املباحــث العامــة وســجنني ثالثــة أشــهر ظلمــا بعــد تبــرءا ومتلــص‬\n‫إخوتــي مــن املوضــوع وأنهــم غيــر مســئولني وبعدهــا حولــت معاملتــي إلــى‬\n‫احملكمــة الشــرعية ومتــت براءتــي بحمــد اهلل وكذالــك رفضهــم دفــع‬\n‫رواتــب العمالــة الباكســتانية والتركيــة ومواطــن ســعودي وعددهــم‬\n‫خمســة عشــر الذيــن كانــت كفالتهــم الســابقة علــى الورشــة الهندســية‬\n‫ثــم مت نقلهــم بحيــاة الوالــد علــى كفالتــي اقــل راتــب للعامــل ثالثــة أالف‬\n\n\n                                                                                        ‫‪304‬‬\n\f      ‫ريــال وقمــت بتصفيــة عــدد كبيــر منهــم وتســليمهم رواتبهــم وتذاكــر‬\n      ‫ســفر لبلدانهــم مــن مالــي اخلــاص ومــا زال منهــم موجــود يعمــل لــدي‬\n      ‫ومســتعدون للشــهادة علــى كالمــي لرفضهــم الورثــة حتمــل املســئولية‬\n      ‫وكل هــذه األمــور تغاضيــت عنهــا ألننــا إخــوة أشــقاء ولــم اســأل عمــا‬\n      ‫أخــذوه ولــم أحاســبهم واحتســبت أمــري إلــى اهلل علمــا انــه علمــت أنهــم‬\n      ‫قامــوا بعمــل مبايعــة مــع الوالــدة مبنتجــع صيفــي جبلي بدولــة لبنان كان‬\n      ‫لوالــدي ومت شــرائه مــن حــر مالــه وقــام والــدي بحياتــه بكتابتــه باســم‬\n      ‫والدتــي مــع عــدد ســبع بيــوت لضمــان عيشــة وحيــاة والدتــي بعــد مماتــه‬\n      ‫ببيعــه للبنــات فقــط وحرمانــي إنــا وأخــي مــن حصتنــا وحصتــي فيــه إنــا‬\n      ‫لوحــدي تقــدر بثالثمائــة إلــف دوالر وكنــت أحــول لــه مبئــات أالف‬\n      ‫الريــاالت ملصاريفــه ومصاريــف عالجــه ملرضــه بالســرطان حماكــم‬\n      ‫اهلل مــن كل شــر ومكــروه إمــا ادعائهــا بأنهــا لــم تأخــذ نصيبهــا‬\n      ‫مــن ارث أبيهــا يف اململكــة العربيــة الســعودية فهــي تناقــض نفســها‬\n      ‫بادعائهــا إمــام فضيلتكــم وتوثيــق مــا ادعــت بــه أنهــا اســتلمت مبلــغ‬\n      ‫مائــة إلــف ريــال مــن ابنــة ‪ .....‬وهــذا غيــر صحيــح وغيــر صادقــة فاملبلــغ‬\n      ‫الــذي أعطــي لهــم مائتــان إلــف ريــال بوجــود أخــي علــي مــن قيمــة ارض‬\n      ‫مقــام عليهــا عمــارة ســكنية مبســاحة األرض ألفــان وخمســمائة متــر‬\n      ‫علــى ثالثــة شــوارع بحــي ‪ ...........‬بجــوار فنــدق الــدار البيضــاء تبعــد عــن‬\n      ‫خــط املدينــة ثالثمائــة متــر وهــذه األرض واملبانــي عمرهــا الوالــد بيــده‬\n      ‫وكان وقتهــا اليوجــد مصانــع أملنيــوم بالســعودية فقــام بشــراء األملنيــوم‬\n      ‫مــن لبنــان لتركيبهــا واجهــات وشــبابيك للمبنــى وتقــدر قيمتهــا بعــام‬\n      ‫‪ 1407‬أكثــر مــن ثالثــة مليــون ريــال بــأي حــق ومــن خولهــم بالتنــازل‬\n      ‫عــن حــق أبــي وحقوقنــا وبيعهــا واســتالمهم املائتــان إلــف ريــال وتقســيمها‬\n\n\n‫‪305‬‬\n\f‫عليهــم بيعهــم ارض مبنطقــة احملجــر ثمامنائــة وخمســون متــر مربــع عليهــا‬\n‫مبانــي ســكنية ومســتودع علــى شــارعني تبعــد عــن الشــارع الرئيســي‬\n‫مائــة متــر تقــدر بعــام ‪ 1407‬بســتمائة إلــف ريــال بيعــت ل‪ .....‬مبائــة إلــف‬\n‫ريــال دون علمنــا وتقســيمهم املبلــغ بينهمــا فقــط هــم ورثــة املغفــور لــه ‪.....‬‬\n‫فقــط علمــا انــه كانــت هنــاك معــدات صناعيــة تقــدر مبئتــان إلــف ريــال‬\n‫يف املســتودع أيــن هــم ! علمــا انــه قــام ‪ .....‬ويكــون ابــن شــقيق الوالــدة‬\n‫ببيــع األرض بثمامنائــة إلــف ريــال بعــد شــهر مــن شــرائها منهــم ‪ ،‬إمــا‬\n‫مطالبتهــا باملعــدات والســيارات والرافعــة الشــوكية فهــي باعترافهــا‬\n‫إمــام فضيلتكــم باســتالمهم مبلــغ ســتون إلــف ريــال مــن املدعــو ‪.....‬‬\n‫لشــرائه املعــدات وخامــات حديــد وأملنيــوم ومكينــة تصنيــع أبــواب‬\n‫قيمتهــا لوحدهــا خمســون إلــف ريــال وكنــت إنــا أكثــر علمــا مــا يوجــد‬\n‫يف املســتودع بــأرض اخلمــرة اقســم بــاهلل العظيــم إن املعــدات واملوجــودات‬\n‫مــن بضاعــة صناعيــة حديــد وأملنيــوم وإكسســوارات كانــت تقــدر‬\n‫بحوالــي النصــف مليــون ريــال بــأي حــق وبشــرع مــن تهــدر هــذه احلقــوق‬\n                                                                          ‫واألمــوال ‪..‬‬\n‫اســتلمتي أنتــي وإخوتــي البنــات ووالدتــي مبلــغ أربعــون إلــف ريــال مــن‬\n‫ورثــة‪ .....‬بعــد وفــاة والــدي وقمتــم بتوزيعهــا عليكــم انتــم فقــط البنــات‪!..‬‬\n‫وهنــاك ســندات أمانــة كانــت بحوزتكــم يطالــب بهــا والــدي شــخصني‬\n‫احدهــم يدعــى ‪ .....‬الســوري كان الوالــد يطالبــه مبائــة إلــف ريــال‬\n‫والثانــي يدعــى ‪ .....‬صاحــب مؤسســة ‪ .....‬لألملنيــوم يطالبــه الوالــد مبلــغ‬\n‫ثالثمائــة إلــف ريــال مــاذا فعلتــم بتلــك الســندات هــل قمتــم بأخذهــا أم‬\n‫ال علمــا إننــي ذهبــت لألستفســار عــن الشــخصني فوجدتهــم يف ذمــة‬\n‫اهلل‪،‬قمتــم ببيــع ســيارة بــي أم دبليــو تاريــخ الصنــع ‪ 2005‬م تخــص الوالــد‬\n\n\n                                                                                          ‫‪306‬‬\n\f      ‫بلبنــان أيــن قيمــت الســيارة وزعــت علــى البنــات فقــط ‪ ،‬قمتــم ببيــع أثــاث‬\n      ‫منــزل الوالــد بجــده ومت تقســيم املبلــغ دون علمــي عليكــم وزعــت علــى‬\n      ‫البنــات فقــط ! إمــا بطلبهــا اخــذ والدتــي وأن تكــون الوصيــة عليهــا‬\n      ‫فقســم بــاهلل العظيــم تكلفــت مــا تكلفــت مــن مصاريــف وبطيــب خاطر‬\n      ‫وال أطالــب إال األجــر مــن اهلل بعــد مــا ســمعت مــن شــقيقات والدتــي‬\n      ‫بلبنــان إن إخوتــي وأزواجهــم متضايقــن مــن خدمتهــا ونحــن األوالد أحــق‬\n      ‫بخدمتهــا ومصاريفهــا وأن لــم نســتجب ملطالبهــم ســوف يقومــون بوضعها‬\n      ‫بــدار العجــزه بلبنــان والســبب الثانــي لســكنها مــع خادمــة لوحدهمــا‬\n      ‫بالشــقة علمــا إن والدتــي محتاجــة لرعايــة طبيــة ســريريه مســتمرة وال‬\n      ‫تتحكــم بذهابهــا إلــى احلمــام وحذرنــا طبيبهــا اخلــاص بلبنــان أن والدتــي‬\n      ‫قــد تفتــح بــاب الشــقة وتهــرب أو ترمــي نفســها مــن نافــذة الشــقة ألنهــا‬\n      ‫غيــر مدركــة ؛ فضيلتكــم شــقيقتي التــي تدعــي وتطلــب أن تكــون‬\n      ‫الوصايــة لوالدتــي لهــا بشــهود عــدة ســمعوا مــن والدتــي أنهــا ال ترغــب‬\n      ‫بالذهــاب عندهــا ألن أخــر مــرة كانــت الوالــدة عنــد شــقيقتي مبدينــة‬\n      ‫جــده قــام زوج شــقيقتي ‪ .....‬بشــتمها بكلمــة مخلــة للشــرف ورفــع‬\n      ‫يــده عليهــا وتهديدهــا بالضــرب لــو قامــت بالتبــول علــى نفســها وعلــى‬\n      ‫املجلــس مــرة أخــرى وقلــت لشــقيقتي عنــد رغبتــك برؤيــة والدتــك الــدار‬\n      ‫دارك ونحــن خــارج الــدار يف أي وقــت وأي يــوم وهــذا حقــك شــرعا‪ .‬ثــم‬\n      ‫ســألت املدعــى عليــه ‪ .....‬عــن االمــاك التــي كانــت باســم ‪ .....‬فقــال ‪:‬‬\n      ‫ال أعلــم عنهــا شــيئا ‪ .‬وبســؤاله عــن االمــاك التــي بأســمة وأقــر بأنهــا‬\n      ‫ملــك لوالــده فقــال ‪ :‬ان االقــرار صحيــح ‪ ،‬وقــد باعــت املدعيــة بضاعــة‬\n      ‫الورشــة‪ ،‬وامــا الورشــة فهــي مســتأجرة ‪ ،‬وامــا االراضــي الثــاث فقــد‬\n      ‫بعتهــا مببلــغ ‪ 300‬ألــف ريــال وســلمت والدتــي نصــف الثمــن ‪ ،‬والنصــف‬\n\n\n‫‪307‬‬\n\f‫االخــر ســددت بــه ديــون علــى الوالــد عبــارة عــن أجــره ‪ 15‬عــام مببلــغ‬\n‫‪ 45‬ألــف ريــال وأجــرة الورشــة مببلــغ ‪ 25‬ألــف ريــال وديــن مبوجــب صــك‬\n‫شــرعي مببلــغ ‪ 180‬ألــف ريــال ‪ ،‬فــكان االجمالــي مبلــغ وقــدرة ‪250‬‬\n‫ألــف ريــال‪ ،‬فدفعــت مــن مالــي اخلــاص ‪ 100‬ألــف ريــال ‪ .‬وبســؤاله عــن‬\n‫مبلــغ ‪ 100‬ألــف ريــال مــن ورثــة ‪ .....‬قــال ‪ :‬لــم أســتلمها ‪ ،‬واملبلغ يف احلقيقة‬\n‫هــو ‪ 200‬ألــف ريــال ‪ ،‬وأســتلمتها الوالــدة بحضــور املدعــى عليــه‪،.....‬‬\n‫وهــو مــن أخبرنــي بذلــك ‪ .‬وبســؤاله عــن مبلــغ ‪ 60‬ألــف ريــال مــن ‪.....‬‬\n‫قــال ‪ :‬هــي مقابــل بيــع بضاعــة الورشــة وقــد أســتلمتها املدعيــة والوالــدة‬\n‫حســب مــا أعلــم ‪ .‬وبســؤال املدعــى عليــه علــي عــن مبلــغ ‪ 5‬أالف ريــال‬\n‫قــال ‪ :‬لقــد أســتلمتها ولــم أســلم أحــدا منهــا شــيئا ‪ .‬وبســؤاله عــن عــدة‬\n‫الورشــة قــال ‪ :‬لقــد أخذتهــا وهــي عبــارة عــن فريــزر و منشــارين و ثالثــه‬\n‫دريــات وطاولــة وملزمــة ‪ .‬وبعــرض مــا تقــدم علــى املدعيــة قالــت ‪ :‬أطلــب‬\n‫االمهــال للــرد ‪ .‬فأفهمــت املدعيــة بــأن عليهــا مصادقــة الوكالــة مــن‬\n‫اجلهــات الرســمية الســعودية ‪ .‬ثــم رفعــت اجللســة لذلــك ‪ .‬ويف يــوم الســبت‬\n‫املوافق‪1433/06/28‬ه ـ افتتحــت اجللســة الســاعة ‪ 11 : 30‬وفيهــا حضــر‬\n‫الطرفــان ‪ ،‬ثــم أبــرزت املدعيــة أصــل الوكالــة بعــد مصادقــة اجلهــات‬\n‫الرســمية الســعودية عليهــا ‪ ،‬ومت تزويــد أوراق املعاملــة بنســخة منهــا ‪،‬‬\n‫وبســؤالها عمــا طلبــت اإلمهــال مــن أجلــه قدمــت مذكــرة هــذا نصهــا ‪:‬‬\n‫أوالً‪ -:‬ان املدعــى عليــه ‪ .....‬قــد أقــر امــام فضيلتكــم ب ــأنه كان الــذراع‬\n‫اليمنــى لوالــدي ( مورثنــا) يف ادارة اعمالــه وأموالــه ويذكــر بأنــه كان‬\n‫يعلــم الــواردة والشــاردة والصغيــرة والكبيــرة ‪ ،‬وهــذا اقــرار منــه بأنــه‬\n‫كان أمــوال مورثنــا كانــت حتــت يــده وإدارتــه ‪ ،‬ونظــر ًا ألن والدنــا‬\n‫كان ال يحمــل اجلنســية الســعودية واملدعــى عليــه ‪ .....‬يحمــل اجلنســية‬\n\n\n                                                                                        ‫‪308‬‬\n\f      ‫الســعودية فكانــت امــوال مورثنــا مــن عقــارات ومنقــوالت باســم املدعــى‬\n      ‫عليــه وذلــك ثابــت بإقــراره املــؤرخ يف ‪1404/7/26‬ه ـ (املرفــق صورتــه )‬\n                          ‫وان عناصــر التركــة املعلومــة لدينــا هــي عبــارة عــن ‪:‬‬\n      ‫‪ -1‬ثالثة قطع اراضي ذات االرقام (‪ ) 725 -725 -726‬مبخطط ‪......‬‬\n                                                                 ‫‪ -2‬االرض التي باسم ‪......‬‬\n                                  ‫‪ -3‬الورشة الهندسية ألعمال احلديد واألملنيوم ‪.‬‬\n               ‫‪ -4‬بضاعة وأغراض وإكسسوارات بداخل الورشة ومخازنها ‪.‬‬\n                                ‫‪ -5‬ديون لدى الغير مستحق األداء ملورثنا وهي ‪-:‬‬\n                                            ‫‪ 100.000‬ريال لدى املدينني ورثة ‪......‬‬\n                                                     ‫‪ 60.000‬ريال لدى املدين ‪...... /‬‬\n                                                         ‫‪ 5000‬ريال لدى املدين ‪......‬‬\n                                               ‫‪ -6‬معدات وسيارات ورافعة وخالفه ‪.‬‬\n      ‫هــذا بخــاف عناصــر التركــة األخــرى الغيــر معلومــة لنــا ويعلمهــا‬\n      ‫املدعــى عليهــم بإعتبــاره كان القائــم علــى ادارة امــوال والــدي ونطالبــه‬\n                                                                                 ‫بإظهارهــا ‪.‬‬\n      ‫ثاني ـاً‪ -:‬بخصــوص مــا ذكــره املدعــي بــأن والــدي قــد أوصــى بقطــع‬\n      ‫االراضــي اململوكــة بصــك واحــد هــذا قــول غيــر صحيــح ال يوجــد‬\n      ‫مــا يؤيــده ونطلــب احضــار الشــاهدة ‪ .....‬ألخــذ شــهادتها علــى قولــه‬\n                                    ‫‪،‬وتقســيم هــذه األرض او اعطائنــا نصيبنــا‪.‬‬\n      ‫ثالثــا‪ -:‬بخصــوص مــا ذكــره بأننــا اســتلمنا نصيبنــا مــن قيمــة املعــدات‬\n      ‫والســيارات والبضاعــة هــذا قــول مرســل ال يوجــد مــا يؤيــده ‪ ،‬حيــث ان‬\n      ‫احلقيقــة ان جميــع امــوال مورثنــا يف الســعودية حتــت يــده وإدارتــه وال‬\n                                     ‫نســتطيع وضــع يدنــا عليهــا والتصــرف فيهــا ‪.‬‬\n\n\n‫‪309‬‬\n\f‫رابع ـاً‪ -:‬أمــا بخصــوص مــا ذكــره بأننــا اســتلمنا الديــون املســتحقة‬\n‫لوالدنــا لــدى الغيــر فإننــا اســتلمنا البعــض منهــا ومت تقســيمه علــى الورثــة‬\n                            ‫والبعــض األخــرى فقــد اســتلمه املدعــى عليهــم ‪.‬‬\n‫وحفاظ ـ ًا علــى حقــوق جميــع الورثــة فقــد تضمنــت املــادة (‪ )2/124‬مــن‬\n‫نظــام املرافعــات الشــرعية مــا نصــه ( للمحكمــة نــدب اخلبيــر الــذي‬\n ‫يطلبــه أحــد اخلصــوم وليــس للخصــم اآلخــر االعتــراض علــى ذلــك ) ‪.‬‬\n‫وحفاظ ـ ًا علــى وقــت فضيلتكــم ‪ .‬لــذا التمــس مــن فضيلتكــم احالــة‬\n‫القضيــة الــى هيئــة اخلبــراء باحملكمــة لتحديــد كامــل عناصــر التركــة‬\n‫مــن عقــارات ومنقــوالت وأمــوال نقديــة وديــون مســتحقة ملورثنــا لــدى‬\n‫الغيــر وتصفيتهــا وســداد الديــون املســتحق علــى مورثنــا لصالــح الغيــر‬\n‫وحتديــد حصــة ونصيــب كل وريــث ومــن ثــم احلكــم بإلــزام املدعــى‬\n                                                            ‫عليهــم بتســليم مورثــه ‪.‬‬\n‫وبعــرض ذلــك علــى املدعــى عليهمــا أجــاب ‪ .....‬قائــا ‪ :‬ليــس لــدي مــا‬\n‫أضيفــه ‪ .‬وأجــاب ‪ .....‬قائــا ‪ :‬ليــس يف املذكــرة مــا يخصنــي ‪ ،‬ســوى‬\n‫مبلــغ ‪ 5‬آالف ريــال مــن ‪ ، .....‬فقــد أخذتــه لنفســي وتصرفــت فيــه ‪.‬‬\n‫وبعــرض ذلــك علــى املدعيــة قالــت ‪ :‬إن لــدي بينــات تثبــت اســتالم املدعــى‬\n‫عليهمــا بعــض املبالــغ وأطلــب اإلمهــال إلحضارهــا يف جلســة قادمــة ‪ .‬ثــم‬\n‫رفعــت اجللســة لذلــك ‪ .‬ويف يــوم الســبت املوافق‪1433/07/05‬ه ـ افتتحت‬\n‫اجللســة الســاعة ‪ 08 : 15‬وفيهــا حضــر الطرفــان ‪ ،‬وقدمــت املدعيــة‬\n‫مذكــرة هــذا نصهــا ‪ :‬أوال‪ :‬ردا علــى مــا ذكــر مــن املدعــى عليهمــا ‪.....‬‬\n‫و‪ .....‬بأنــي اســتلمت مبلــغ مائــة ألــف ريــال ســعودي مــن أبنــة ‪ .....‬وبعــد‬\n                   ‫ذلــك غيــر املبلــغ ملئتــان ألــف ريــال وأنــه أنــا مــن اســتلمتها‬\n‫الــرد‪ :‬بســؤال الســيدة ‪ .....‬قالــت انهــا لــم ترانــي بحياتهــا وان مــن اســتلم‬\n\n\n                                                                                             ‫‪310‬‬\n\f                                              ‫املبلــغ مــن أخاهــا هــو املدعــي عليــه ‪.....‬‬\n      ‫أضافــة أن الســيد ‪ .....‬أعاطنــي ورقــة بخــط يــده مرفقــه لديكــم تنــص‬\n      ‫علــى أن املدعــي عليــه ‪ .....‬هــو مــن أســتلم املبلــغ وقــدره مئــة ألــف ريــال‬\n                         ‫وليــس أحــد غيــره وهــم مســتعدون للشــهاده يف أي وقــت‬\n      ‫ثانيا‪ :‬أفاد املدعي عليه ‪ .....‬يف اجللســة الســابقة أنه ال يوجد ما يخصه‬\n      ‫ســوى مبلــغ خمســة أالف ريــال أســتلمها مــن ‪ ،.....‬مــع العلــم ان الورقــة‬\n      ‫املرفقــة لديكــم بخــط يــده تثبــت أخــذه ملبالــغ أخــرى فأنــا أطلــب مــن‬\n      ‫ســعادتكم بإحالــة الورقــة خلبيــر خطــوط ألنــه أنكــر خــط يــده ‪ .‬ثالثــا‪:‬‬\n      ‫ادعائــه أننــي اســتلمت مبلــغ ســتون ألــف ريــال مــن ال‪ ، .....‬فالبدايــة أريــد‬\n      ‫االثباتــات أن كان صــادق وباملقابــل الورقــة املرفقــة بخــط يــده التــي‬\n                 ‫ســبق وانكرهــا مكتــوب فيهــا هــو مــن اســتلم املبلــغ بالتحديــد‬\n      ‫رابعــا‪ :‬هــذه النقطــة ســوف أتــرك لســعادتك اســتنتاج مــا حــدث قطعــة‬\n      ‫األرض الــذي قــال املدعــي عليــة ‪ .....‬أنــه لــم يبعهــا وال يعلــم عنهــا شــيء‬\n      ‫وهــي أرض باســم ‪ .....‬الــذي ســلمها للســيدة ‪( .....‬الوالــدة) وأصبحــت‬\n      ‫ذمتــه خاليــة وبعــد ذلــك قامــت الســيدة ‪ .....‬بإعطائهــا للمدعــي عليــه ‪.....‬‬\n      ‫و‪ .....‬ســؤال املشــتري اجلديــد مــن باعــك هــذه األرض قــال املدعــي عليــه‬\n      ‫‪ .....‬مــع أخواتــه البنــات يف احملكمــة مــع العلــم أن جميــع أخواتــه البنــات‬\n      ‫يف وقتهــا موجــودون يف لبنــان (‪.....‬و‪.....‬و‪ ).....‬كانــوا قصــر و‪ .....‬كانــت‬\n      ‫يف األمــارات وأنــا أيضــا كنــت يف لبنــان إذن مــن كان يف احملكمــة‬\n      ‫مــن البنــات أنــا ال أشــكك بنزاهــة القضــاء الســعودي ولكــن هنــاك مــن‬\n                                                                   ‫يتحايــل علــى القانــون‬\n      ‫فالســيد ‪ .....‬قــد أشــترى األرض ثــم باعهــا للســيد ‪ .....‬ومــن ثــم للســيدة‬\n      ‫املوجــودة حاليــا وعــن ســؤالها منــذ خمســة أيــام قالــت أن االرض مت‬\n\n\n‫‪311‬‬\n\f‫بيعهــا علــى الشــكل التالــي باعهــا املدعــي عليــه ‪ .....‬للســيد ‪ .....‬ومــن‬\n‫ثــم للســيد‪ .....‬ثــم لهــا بعــد كل مــا ذكــر أطلــب مــن ســعادتك أن تطلبــوا‬\n‫الصــك مــن املدعــي عليــه ‪ ..... .....‬وأن ثبــت صــدق كالم صاحــب االرض‬\n‫أنــه باعهــا بحضــور املدعــي عليــه ‪ .....‬وأخوتــه البنــات فســوف أجلــب‬\n‫أوراق مــن اجلــوزات تثبــت عــدم وجــود أخوتــه يف اململكــة أثــاء البيــع‬\n‫وأطالــب بالتحقيــق يف املوضــوع ألنــه يعتبــر تزويــر يف أوراق رســميه‬\n                                                                       ‫وشــهادة باطلــة‪.‬‬\n‫خامســا‪ :‬بالنســبة للديــن الــذي أشــارت إليــه وهــو مبلــغ مئــة وثمانــون‬\n‫ألــف ريــال للســيد ‪ .....‬وقــد تــويف قبــل ســنتان وأصــدر الصــك فضيلــة‬\n                                          ‫القاضــي‪ .....‬ومت ســجنه ثالثــة شــهور‬\n‫الــرد فضيلــة الشــيخ ‪:‬لــم يذكــر لــك املدعــي عليــه ‪ .....‬أن القضيــة‬\n‫منــذ أربــع ســنوات والوالــد متــويف مــن أكثــر مــن ســبعه وعشــرون ســنة‬\n‫والقضيــة بــن‪ .....‬والســيد ‪ .....‬الــذي أفادنــا ولــده الســيد ‪ .....‬بــأن والــده‬\n‫تــويف منــذ ثــاث ســنوات وليــس ســنتان كمــا ذكــر املدعــي عليــه ‪.....‬‬\n‫وأن املبلــغ كان مطلــوب مــن املدعــي عليــه ‪ ،.....‬وأفادنــي الســيد ‪ .....‬أن‬\n‫املــال ليــس لوالــده بــل والــده كان الوســيط بــن ‪ .....‬والســيد ‪ .....‬وهــم‬\n‫مازالــوا علــى قيــد احليــاة ويف وقــت القضيــة كان الســيد ‪ .....‬موجــود مــع‬\n‫والــده يف احملكمــة وحكــم القاضــي بدفــع مبلــغ مئــة وثمانــون ألــف‬\n                                                           ‫ريــال علــى النحــو التالــي‬\n‫عشــرون ألــف ريــال يف حينــه وتقســيط املبلــغ ثــاث أالف ريــال كل‬\n                                           ‫شــهر تدفــع مــن خــال احملامــي ‪......‬‬\n‫وبســؤالي لــه هــل دفــع املبلــغ بالكامــل قــال ‪ ......‬بانــه ال يعلــم الن بعــد‬\n‫وفــاة والــده عمــل توكيــل للســيد ‪ .....‬واصبــح الســيد ‪ .....‬يســتلم املبلــغ‬\n\n\n                                                                                           ‫‪312‬‬\n\f      ‫مباشــره مــن احملامــي ‪ ،‬وقــال الســيد ‪ .....‬حــارث انــه مســتعد للشــهادة‬\n      ‫فكيــف يقــول املدعــي عليــه ‪ .....‬أن هــذا ديــن علــى والــده فليتقــي اهلل يف‬\n      ‫قولــه وأطالــب املدعــي عليــه ‪ .....‬بإحضــار صــك القضيــة ووضعهــا أمــام‬\n                                                               ‫ســعادتكم ليظهــر احلــق‬\n      ‫سادســا‪ :‬أمــا قضيــة اللــواء ‪ .....‬يف املباحــث العامــة وبأنــه ســجنه ثالثــة‬\n                            ‫أشــهر ظلمــا بعــد تبرئتــه ومتلــص أخوتــي مــن املوضــوع‬\n      ‫الــرد‪ :‬هــذا الــكالم غيــر صحيــح والســيد اللــواء ‪ .....‬مــازال علــى قيــد‬\n      ‫احليــاة وقــال أن القضيــة كانــت بســبب أعمــال بــن املدعــي عليــه ‪.....‬‬\n      ‫وبينــة وهــو علــى اســتعداد تــام مبواجهــة املدعــي عليــه واحلضــور للشــهادة‬\n      ‫يف أي وقــت وأحمــد اهلل أن اللــواء ‪ .....‬مــازال علــى قيــد احليــاة ليثبــت‬\n      ‫احلــق‪ ،‬وأذا كان لــدى املدعــي عليــه كالم غيــر هــذا فليواجــه اللــواء‪.....‬‬\n                                    ‫أمــام ســعادتكم أو يحضــر مــا يثبــت العكــس‬\n      ‫ســابعا‪ :‬أحــب املدعــي عليــه أن يدخــل مداعبــة علــى القضيــة عندمــا‬\n      ‫قــال أننــي الســيدة باســمه ‪ .....‬قمــت ببيــع ســيارة بــي أم دبليــو تاريــخ‬\n      ‫الصنــع‪ .....‬تخــص الوالــد يف لبنــان أنهــا ليســت دعابــة بــل هــي مشــيئة‬\n      ‫اهلل بإظهــار احلــق فالوالــد متــويف يف عــام ‪ .....‬هــل هنــاك شــركة تصنــع‬\n                                                    ‫ســيارة لعشــرون عــام إلــى االمــام‬\n      ‫الرجــاء التوقــف عــن االســتهزاء بهــذه القضيــة وقــول املنطــق واحلــق‬\n                                   ‫واطلــب االثباتــات مــن جهــة املدعــي عليــه ‪.....‬‬\n      ‫ثامنــا‪ :‬لقــد قــال املدعــي عليــه ‪ .....‬أن والــده أوصــى بــأرض مخطــط ‪.....‬‬\n      ‫بجنــوب جــده منطقــة اخلمــرة فهــم ثــاث قطــع بصــك واحــد فقــال لــي‬\n      ‫أن والــدي أوصــى بهــا بعــد مماتــه النــه لــم يكتــب لــه أي أمــاك كمــا‬\n      ‫كتــب ألخوتــي اخلمســة وأخــي ‪ .....‬يف لبنــان ولقــد أتهمنــي بأنــي شــاهدة‬\n\n\n‫‪313‬‬\n\f                                           ‫علــى هــذا الــكالم وأخــاه وزوجتــه‬\n‫أنــا أقــر وبكامــل قــواي العقليــه أنــي لــم أســمع هــذا الــكالم ولــم أشــهد‬\n‫عليه‪،‬واريــد أن يتــم أحضــار الســيده ‪.......‬للشــهاده وهــي زوجــة أخــاه‬\n‫‪ ،.....‬أمــا مــن الناحيــة القانونيــه والشــرع علــى حــد علمــي أن الوصيــه‬\n‫تكتــب وال تقــال شــفهي باالضافــة الــى الشــهاده تكــون رجــان أو‬\n                                   ‫رجــل وامرأتــان او أربــع نســاء واهلل أعلــم‬\n‫فــأن الوالــد رحمــة اهلل كان صاحــب حــق وأعطــاك الكثيــر ومنهــا‬\n‫اجلنســيه الســعودية التــي كلفتــه يف وقتهــا أكثــر مــن مئتــان ألــف ريــال‬\n‫ســعودي كمــا ذكــر الوالــد ولــم يعطهــا الخيــك واخوتــك البنــات فلمــاذا‬\n                                                      ‫لــم نخســمها مــن التركــة‬\n‫تاســعا‪ :‬قلــت أنــك تعلــم انــه اذا اخــذوا املــال ســوف يدمــر ويندثــر‪ ،‬وقلــت‬\n‫أن هنــاك قضيــة مت رفعهــا عليــك مــن قبــل والدتــك وتدخــل كبــار العائلة‬\n‫حللها الرد هل اذا اعطي كل شــخص حقه حســب الشــريعه االســاميه‬\n‫يكــون الــورث قــد دمــر وهــل ممكــن أن حتضــر صــك القضيــه التــي‬\n              ‫مــن نســج خيالــك لفضيلــة القاضــي وذكــر أســامي االقــارب‬\n      ‫أنا أشهد أن هذا الكالم غير صحيح ولم يتم رفع أي قضيه عليه‬\n‫عاشــرا‪ :‬عندمــا كان الوالــد علــى فــراش املــوت قــال أنــه الديــن عليــه‬\n‫فكيــف تريــد أن أقتنــع أن لــك رواتــب خمــس ســنوات لــم تأخذهــا‬\n‫وكــم كان راتبــك يف حينهــا ومــن أيــن متلــك مبلــغ ثمانــون ألــف ريــال‬\n‫كــم كان عمــرك لتجمــع هــذا املبلــغ وكيــف جمعتــه وأنــت لــم تســتلم‬\n‫رواتبــك كمــا تتدعــي فليــس مــن املنطــق والعقــل أن فتــى مــن اخلامســة‬\n‫عشــر مــن عمــره وطالــب حتــى العشــرين مــن عمــره كان يعمــل عنــد‬\n‫والــده يف الصيــف ويكــون لــه رواتــب خمــس أعــوام لــم يأخــذه وفائــض‬\n\n\n                                                                                      ‫‪314‬‬\n\f      ‫مشــاء اهلل ثمانــون ألــف ريــال أمــا بخصــوص ماقلتــه عــن خالتــك ‪.....‬‬\n      ‫زوجــه ‪ .....‬فلقــد أقــرت بــأن زوجهــا قــد أقتــرض منــك مبلــغ ثالثمئــة ألــف‬\n      ‫ريــال ســعودي وهــي ال تريــد أن تبــرء ذمتــه وقالــت أن أردمت املــال أحلقــوا‬\n      ‫بصاحبــه املتــويف فمــن أيــن لطالــب ولــم يســتلم رواتبــه أن ميلــك هــذا املبلغ‬\n      ‫ثالثمئــة ألــف ريــال ســعودي ســيدي القاضــي هــذا املــال مــن التركــه اي‬\n                                                                 ‫مــال الوالــد رحمــه اهلل‬\n      ‫أحــدى عشــر‪ :‬لقــد قــام املدعــي عليــه بتوجيــه التهمــه لزوجــي الســيد‪.....‬‬\n      ‫أنــه ضــرب والدتــي وقذفهــا بكالم اليســتطيع البوح به أمام ســعادتكم‬\n      ‫الرد أقسم باهلل العظيم أن زوجي لم يضرب أمي بل كان حنون عليها‬\n      ‫فهــو معــروف بأخالقــه العاليــه وحبــه للنــاس ومســاعدتهم وباالخــص‬\n      ‫بــره لوالدتــه التــي كانــت مقعــده وكان يرفــض أن يعاونــه أحــد عليهــا‬\n      ‫فــكان يعامــل والدتــي أحســن معاملــه وبشــهادة الكثيــر مــن النــاس منذ‬\n      ‫وفــاة الوالــد وهــو مــن يدعمهــا ويقــف بجانبهــا يف الوقــت الــذي تركهــا‬\n      ‫فيــه اوالدهــا الرجــال أكثــر مــن خمســة عشــر عــام حتــى اخوتــي البنــات‬\n      ‫عندمــا كانــوا قصــر كان يرعاهــم واطلــب مــن ســعادتك أســتدعاء‬\n      ‫الســيد ‪ .....‬وهــو أبــن املدعــي عليــه ‪ .....‬للشــهاده النــه الوحيد كان يدخل‬\n      ‫البيــت ويــرى كيــف كانــت تعامــل جدتــه ولــن أفكــر املدعــي عليــه ‪.....‬‬\n      ‫و‪ .....‬مــاذا فعــل الســيد ‪ .....‬أجتاههــم وأجتــاه أوالدهــم مــن خيــر‪ ،‬ومــع‬\n      ‫علــم املدعــي عليــه أن والدتــه تعانــي مــن مــرض الزهاميــر مــن الدرجــة‬\n      ‫املتاخــره وانــه بأمــكان أي شــخص يقــول لهــا أي شــيء وتــردده فهــي‬\n      ‫أصبحــت كالطفلــه تــردد ماتســمعه واطلــب مــن ســعادتكم ان تطلــب‬\n      ‫مــن املدعــي عليــه الشــهود الذيــن رئــوا زوجــي يضربهــا ويشــتمها وان لــم‬\n      ‫يحضــر أي شــهود ســوف أرفــع قضيــه أخــرى بسســب االدعــاء الــكاذب‬\n\n\n‫‪315‬‬\n\f‫علــى شــخص لــو ســئل عنــه يقــال هــو ســيد االخــاق واالحتــرام ويخــاف‬\n                                   ‫اهلل وال أقــول غيــر حســبي اهلل ونعــم الوكيــل‬\n‫اثنــى عشــر‪ :‬أمــا األرض التــي أتهمنــي بأنــي بعتهــا لنفســي دون علمــه‬\n                             ‫وهــي أرض بأســم الســيده ‪ .....‬وبشــهود أبنهــا ‪.....‬‬\n‫الــرد ‪ :‬فضيلــة القاضــي كيــف أبيــع أرض لنفســي وهــو شــاهد عليهــا‬\n‫مــاكان دوره مضغــوط عليــه أو يف غيبوبــه ال يعلــم مــاذا حــدث فليقــول‬\n‫املنطــق والعقــل وهنــاك شــهود وهــو ‪ .....‬واملدعــي عليــه ‪ .....‬وانــه مت بيعهــا‬\n‫مبوافقــة أخوتــي البنــات وبعــد وفــاة والــدي بخمســة ســنوات ومت توزيــع‬\n                                                                    ‫املــال علــى أخوتــه‬\n          ‫ثالثة عشر‪ :‬عندما قال املدعي عليهما بأني أخذت عفش املنزل‬\n‫الــرد‪ :‬هــذا غيــر صحيــح فلقــد دفعــت رهنيــة البــراد و التلفــاز وغســالة‬\n‫قدميــة ال تعمــل جيــدا قيمــة الرهنيــة عشــرة أالف ريــال ســعودي مت دفعهــا‬\n‫للســيد ‪ .....‬وكان املنــزل خالــي متامــا مــن االثــاث وهنــاك مــن يشــهد وهــو‬\n‫الســيد ‪ .....‬وأرجــوا أســتدعائة للشــهادة وانــا مــن يطالــب بأخبــاري أيــن‬\n                                                                  ‫ذهــب عفــش املنــزل‬\n‫أربعــة عشــر‪ :‬هنــاك مســتودعات مليئــة بالبضاعــة مت بيعهــا مــن خــال‬\n‫املدعي عليهما ‪ .....‬و‪ .....‬للســيد ‪ .....‬والســيد ‪ .....‬وباإلضافة لبيع مكنة‬\n                                                               ‫تصنيــع أبــواب ســحاب‬\n‫املطلــوب معرفــة قيمــة البضاعــة املذكــورة وإفادتــي بطريقــة توزيعهــا‬\n‫ويف حــال نكــران املدعــي عليهمــا ســيتم جلــب الشــهود التــي تثبــت ان‬\n‫املدعــي عليهمــا ‪ .....‬و‪ .....‬هــم مــن بــاع تلــك البضائــع التــي تقــدر باملاليــن‬\n‫والتــي أفــاد املدعــي عليــه ‪ .....‬يف حينــه أنهــا تقــدر بقيمــة عشــرة ماليــن‬\n‫وحصــة البنــت الواحــدة مليــون ريــال وأخيــرا يف أخــر جلســه عندمــا قــال‬\n\n\n                                                                                            ‫‪316‬‬\n\f      ‫لــك املدعــي عليــه ‪ .....‬أن والــدي قــد تــويف ومالــه قــد نهــب وأن مــن نهبــه‬\n      ‫هــو املدعــي عليــه ‪ .....‬و‪ .....‬وأنــا فهــذا االدعــاء كاذب النــي أطالــب‬\n      ‫بحقــي وحقــوق أخوتــي البنــات وأن كان لديــه دليــل ملمــوس فاليقدمــه‬\n                       ‫أنــا لــم أنهــب مــال والــدي وحفاظــا علــى وقــت فضيلتكــم‬\n      ‫لــذا التمــس مــن فضيلتكــم احالــة القضيــة الــي هيئة اخلبــراء باحملكمة‬\n      ‫لتحديــد كامــل عناصــر التركــه مــن عقــارات ومنقوالت وأمــوال نقدية‬\n      ‫وديــون مســتحقه أن وجــد ملورثنــا لــدى الغيــر وتصفيتهــا وحتديــد حصــة‬\n      ‫ونصيــب كل وريــث ومــن ثــم احلكــم بإلــزام املدعــى عليهــم بتســليم‬\n      ‫مورثه‪،‬كمــا أحضــرت املدعيــة للشــهادة وأدائهــا ‪ .....‬لبنانــي اجلنســية‬\n      ‫مبوجــب اإلقامــة رقــم ‪ .....‬وهــو مــن مواليــد ‪1954‬م ويعمــل يف مصنــع ‪.....‬‬\n      ‫للصناعــات احلديديــة وهــو ابــن خلــال الطرفــن ‪ ،‬وشــهد قائــا ‪ :‬أشــهد‬\n      ‫بــاهلل العظيــم الــذي ال إلــه غيــره أننــي ســمعت أن املدعــى عليهمــا همــا‬\n      ‫مــن بــاع البضاعــة التــي يف الورشــة ‪ ،‬وكان ذلــك بعــد وفــاة املــورث‬\n      ‫بحوالــي عــام ‪ ،‬وفيمــا يخــص األرض التــي باســم والدتــي وهــي ملــك‬\n      ‫للمــورث ‪ ،‬فقــد اشــتريتها مبائــة وعشــرة آالف ريــال يف ‪1409/3/7‬ه ـ ‪،‬‬\n      ‫وقــد ســلمت الثمــن كامــا للورثــة عــدا املدعــى عليهمــا ‪ ،‬فقــد تنــازال‬\n      ‫عــن نصيبهمــا يف هــذه األرض ألخواتهمــا بنــاء علــى إقــرار محــرر وموقــع‬\n      ‫منهمــا ‪ .‬هكــذا شــهد ‪ .‬وبعــرض املذكــرة والشــاهد وشــهادته علــى‬\n      ‫املدعــى عليهمــا قــاال ‪ :‬نطلــب اإلمهــال للــرد ‪ .‬ثــم رفعــت اجللســة لذلــك‬\n      ‫ويف يــوم االثنــن املوافــق ‪1433/07/07‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 02 : 00‬وفيهــا حضــر الطرفــان ‪ ،‬وبســؤال املدعــى عليهمــا عمــا طلبــا‬\n      ‫اإلمهــال مــن أجلــه قــدم املدعــى عليــه ‪ .....‬مذكــرة هــذا نصهــا ‪ :‬ردا علــى‬\n      ‫الدعــوى املقامــة ضــدي مــن شــقيقتي باســمة ‪ ..... .....‬وتدعــي بأننــي قلــت‬\n\n\n‫‪317‬‬\n\f‫إن املبلــغ قــدره مائتــي ألــف ريــال وليــس مائــة ألــف ريــال وأنهــا قامــت هــي‬\n‫باســتالمها ‪ ،‬فإننــي لــم أقــل ذلــك بــل قلــت أنهــا اعترفــت باســتالم مائــة‬\n‫ألــف ريــال أي أنهــا متثــل الورثــة وقمــت بتوضيــح العبــارة بقولــي إنكــم‬\n‫اســتلمتم أنتــم البنــات والوالــدة بوجــود شــقيقي ‪ .....‬ليــس مائــة ألــف بــل‬\n                                                                      ‫مائتــا ألــف ؛؛‬\n‫ردا للبنــد الرابــع قطعــة األرض التــي كانــت معروفــه أنهــا بأســم ‪.....‬‬\n‫وأنــه قــام بتســليمها لوالدتــي وهــي أجنبيــه وقامــت والدتــي بتســليمها لــي‬\n‫وقمــت إنــا بعــد ذالــك ببيعهــا وأخــذت خمســة بنــات للمحكمــة الشــرعية‬\n‫وادعيــت أنهــم إخوتــي وحتايلــت علــى القضــاة والشــرع واحلكومــة وقمت‬\n‫ببيعهــا للمدعــو ‪ !!!.....‬ســيدي هــذا الــكالم لــو صحيــح بإمكانكــم‬\n‫االستفســار عــن طريــق اجلهــات احلكوميــة وأننــي مســتعد ألي أجــراء‬\n                                            ‫قانونــي وشــرعي إذا ثبــت ذالــك ‪،،‬‬\n‫ردا للبنــد اخلامــس قضيــة ‪ .....‬ســيدي قمــت بــردي الســابق بتوضيــح‬\n‫انــه يوجــد صــك شــرعي اصــدر حكــم علــي وبإمــكان فضيلتكــم‬\n‫االســتيضاح وقــراءة الصــك للقضيــة مــن أي عــام كانــت هــذه القضيــة‬\n‫وانــه صــدر حكــم علــي مــن جهــة احلقــوق املدنيــة بجــده املوظــف ‪......‬‬\n‫بســداد مبلــغ مائتــان وكســور توضيــح املبلــغ موجــود بالصــك الشــرعي‬\n‫وأن أقــوم بســداد املبلــغ أقســاط شــهرية كل قســط ألفــان ريــال وبحمــد‬\n‫اهلل ســددت املبلــغ وموجــود شــهود كانــوا يقومــون بتوصيــل املبالــغ‬\n‫واســتالم الســندات وألكــن قبــل ثالثــة ســنوات قــام ‪ .....‬وادعــى انــه لــم‬\n‫يســتلم املبلــغ فطلبــت منــه حلــف اليمــن فحلــف وصــدر صــك شــرعي‬\n                                   ‫وإننــي أقــوم بســداد املبلــغ للمــرة الثانيــة ‪،‬‬\n‫ردا للبنــد الســادس قضيــة ‪ .....‬أمتنــى مــن فضيلتكــم حســب طلبهــا‬\n\n\n                                                                                         ‫‪318‬‬\n\f      ‫وادعائهــا طلبــه للمثــول إمــام فضيلتكــم ومصــر إنــا علــى مواجهتــي‬\n                                ‫أمــام فضيلتكــم وتوضيــح وصــدق مــا قلتــه ‪،،‬‬\n      ‫ردا للبنــد الســابع بيــع الســيارة فأننــي أخطئــت بالتاريــخ فقــط ومت بيــع‬\n                          ‫الســيارة بتاريــخ ‪1986‬م وتقســيم قيمتهــا عليكــم ‪،،‬‬\n      ‫ردا للبنــد الثامــن ارض اخلمــرة ‪ ........‬إمــام فضيلتكــم شــقيقي ‪.....‬‬\n      ‫فاستفســروا منــه وكيــف بحيــات والــدي رحمــة اهلل عليــه مت شــراء‬\n      ‫لــكل فــرد منهــم شــقة مبدينــة بيــروت وطلــب منــي إن يســجل لــي شــقة‬\n      ‫فرفضــت بــان لبنــان ليســت بلــدي وليــس لــي عيشــة فيهــا ومــع ذالــك‬\n      ‫قامــوا إخوتــي البنــات بالتحايــل علــى والدتــي وحرمانــي مــن نصيبــي‬\n      ‫بــأرض وبيــت اجلبــل وكتبــوه باســمهم فقــط علــى حجــة إن والدتــي‬\n                                                   ‫قامــت بإعطائهــم األرض هبــه ؛؛‬\n      ‫ردا علــى البنــد التاســع كان هنــاك قضيــة رفعتهــا والدتــي يف احملكمــة‬\n      ‫الشــرعية يف بــاب شــريف ســابقا وكانــت دعواهــا بأننــي رافــض‬\n      ‫إعطائهــا اثنــن مــن شــقيقاتي كانــا قاصريــن للعيــش معهــا بلبنــان‬\n      ‫وكنــت رافــض إصــدار تأشــيرة خــروج وعــوده لهــا ألننــي كنــت خائــف‬\n      ‫عليهــا ‪ .....‬شــقيقتي مــن إحــداث لبنــان يف تلــك األيــام ورغبتــي بــان يتــم‬\n      ‫الوضــع كمــا حيــاة والــدي وكانــت الدعــوى عنــد فضيلــة الشــيخ ‪.....‬‬\n                                                             ‫هــذا الــذي افتكــره ؛؛‬\n      ‫ردا علــى البنــد العاشــر لقــد قلتــي يف البنــد الثالــث عشــر انــك قمــت‬\n      ‫بســداد عشــرة أالف ريــال رهــن عفــش بيــت الوالــد عــن أشــياء ليســت‬\n      ‫لهــا قيمــة الرهــان حســب قولــك وقبــل وفــاة والــدي قــال لــك إن ال ديــن‬\n      ‫عليــه كيــف يكــون ذالــك !! وعنــد وفــاة والــدي كان عمــري إحــدى‬\n      ‫وعشــرون عامــا وبشــهادة شــقيقي ‪ .....‬وبشــهادة عمــال كانــوا يعملــون‬\n\n\n‫‪319‬‬\n\f‫يف حيــاة والــدي مســتعدون للشــهادة إننــي كنــت اعمــل بالورشــة وكنــت‬\n‫الســاعد األميــن ولــم اقــل إنــي املــك ثمانــون ألــف ريــال بــل قلــت أن والــدي‬\n‫خصــص لــي راتــب شــهري ثالثــة أالف ريــال وعنــد حســاب املــدة ســوف‬\n‫يكــون لــي مائــة وثمانــون ألــف ريــال ؛؛ أمــا بخصــوص خالتــي فأنــي‬\n‫أعطيتهــا مائــة وخمســون ألــف ريــال فقــط وكان هنــاك ســند عليهــا‬\n‫وليــس علــى زوجهــا واملبلــغ كان مــن قيمــة بيــع أرض اخلمــره مائتــان‬\n‫وخمســون ألــف ريــال وكانــت والدتــي علــى علــم وأخــذت منــي الســند‬\n‫لــك ال أقــوم بشــكوة أختهــا وســجنها وإنهــا أي والدتــي ســوف تأخــذ‬\n                              ‫منهــا املبلــغ بطريقتهــا وتقســمه علــى إخوتــي ؛؛‬\n‫ردا علــى البنــد اإلحــدى عشــر بأننــي وجهــت تهمــة لزوجهــا بأنــه ضــرب‬\n   ‫والدتــي هــذا غيــر صحيــح وموجــود لــدى فضيلتكــم مــا قلــت عنــه ؛؛‬\n‫ردا علــى البنــد الثانــي عشــر إنــا لــم اتهمــك بأنــك بعــت األرض احملجــر‬\n‫إلــى نفســك وأنتــي أجنبيــة بــل قلــت أنهــا بيعــت ل‪.......‬وهــو أجنبــي أيضــا‬\n‫ألنهــا بأســم أمــه الســعودية وقســم املبلــغ لكــم انتــم البنــات وهــذا مثبــت‬\n‫لــدى فضيلتكــم ‪ ،،‬ردا علــى البنــد الرابــع عشــر إنــا أطالبهــا بإحضــار‬\n‫‪ .....‬ويثبــت إمــام فضيلتكــم بأننــي بعتــه أي بضاعــة مــن مســتودعات‬\n‫والــدي ألنهــا هــي التــي تعــرف مــكان وجــوده يف الســعودية وعلى تواصل‬\n‫معــه وهــي تقــول أنهــا مســتعدة بإحضــار الشــهود غيــر ‪ ....‬نصــار ألنــه‬\n‫ســمع ولــم يــرى ؛ وكانــت الوالــدة محتاجــة لكميــة كبيــرة مــن املــال‬\n‫لعمــارة بيــت اجلبــل وأمــا بالنســبة حلقــوق املدعيــة‪ .....‬هــي وأخواتهــا البنات‬\n‫فإنــي أريــد مــن فضيلتكــم أن تســألها أيــن ورثنــا أنــا وأخــي ‪ .....‬مــن‬\n‫بيــت اجلبــل( مليــون وثالثمائــة ألــف دوالر أمريكــي ) أيــن حقنــا يف املــال‬\n‫الــذي أخذمتــوه مــن حســاب والدتنــا يف بنــك ‪ .....‬ببيــروت باخلدعة(مائتــي‬\n\n\n                                                                                         ‫‪320‬‬\n\f      ‫ألــف دوالر أمريكــي ) وأيــن ســبايك الذهــب التــي انزلهــا ‪ .....‬لبيــروت‬\n      ‫(أكثــر مــن مليــون دوالر أمريكــي) لقــد ضاعــت مــن بيــت الوالــدة يف‬\n      ‫بيــروت بطريقــة مشــبوهة ونطلــب مــن فضيلــة الشــيخ أن يقضــي بيننــا‬\n      ‫وبينــك وبــن ابنتــك ‪ .....‬بحلفــان اليمــن البينــة علــى مــن ادعــى واليمــن‬\n                                                                        ‫علــى مــن أنكــر‬\n      ‫وبعــرض ذلــك علــى املدعيــة قالــت ‪ :‬ليــس لــدي إجابــة علــى مــا ذكــر‪.‬‬\n      ‫وبســؤال الطرفــن هــل لديكمــا مــا تضيفانــه قــاال ‪ :‬ال ‪ .‬ثــم رفعــت‬\n      ‫اجللســة للتأمــل ‪ .‬ويف يــوم االثنــن املوافق‪1433/07/28‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 01 : 30‬وفيهــا حضــر الطرفــان‪ ،‬وقــررت املدعيــة قائلة‪:‬‬\n      ‫إننــي أطلــب احلكــم مبــا جــاء يف الدعــوى أصالــة عــن نفســي وبصفتــي‬\n      ‫وكيلــة عــن موكالتــي شــقيقاتي ‪.....‬و‪.....‬و‪.....‬و‪ ......‬وبعــد التأمــل ‪،‬‬\n      ‫طلبــت مــن املدعيــة البينــة علــى أن املدعــى عليــه ‪ .....‬هــو مــن بــاع األرض‬\n      ‫التــي باســم ‪ .....‬واململوكــة يف احلقيقــة للمــورث ‪ .....‬فقالــت ‪ :‬ليــس لــدي‬\n      ‫بينــة وأطلــب ميــن املدعــى عليــه ‪ .....‬علــى إنــكار ذلــك ‪ .‬وبســؤالها عــن‬\n      ‫صــورة صــك األرض لالستفســار عنــه لــدى كتابــة العــدل قالــت ‪ :‬ليــس‬\n      ‫لــدي نســخة منــه ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه ‪ .....‬قــال ‪ :‬إن أرض‬\n      ‫احملجــر ليســت باســم ‪ ، .....‬وليــس عليهــا صــك ‪ ،‬وإمنــا باســم ورثــة ‪، .....‬‬\n      ‫وقــد اشــتراها املــورث مبوجــب وثيقــة ‪ ،‬وهــي عبــارة عــن بيتــن شــعبيني‬\n      ‫ومســتودع ‪ ،‬وال أعــرف مبصيرهــا ‪ ،‬ومســتعد باحللــف علــى إنــكار‬\n      ‫بيعــي لــأرض وعلــم مبصيرهــا ‪ .‬ثــم حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال‬\n      ‫إلــه إال هــو أن األرض التــي تدعــي املدعــي أنهــا كانــت باســم ‪ .....‬و‪.....‬‬\n      ‫قــد اشــتراها والــدي املــورث مــن ورثــة نصيــف وليــس عليهــا صــك‪ ،‬ولــم‬\n      ‫أبــع تلــك األرض ولــم اســتلم ثمنهــا وال أعلــم مبصيرهــا ‪ .‬هكــذا حلــف‪.‬‬\n\n\n‫‪321‬‬\n\f‫وبســؤال املدعيــة البينــة علــى بيــع بضاعــة الورشــة ‪ ،‬وبكــم بيعــت ‪،‬‬\n‫ومــن الــذي باعهــا قالــت ‪ :‬لقــد بيعــت البضاعــة لــكل مــن ‪ ..... .....‬مــن‬\n‫قبــل املدعــى عليهمــا ‪ ،‬وال أعــرف بكــم بيعــت ‪ ،‬ولــدي شــاهد هــو ‪.....‬‬\n‫ولكنــه كبيــر يف الســن وال يســتطيع احلضــور للمحكمــة ‪ ،‬وأطلــب‬\n‫نــدب منــدوب مــن احملكمــة لســماع شــهادته ‪ .‬وبســؤالها عــن البينــة علــى‬\n‫أن بذمــة ‪ .....‬ســتون ألــف ريــال للمــورث ‪ ،‬ومقابــل مــاذا ومــن الــذي اســتلم‬\n‫هــذا الديــن قالــت ‪ :‬ليــس لــدي بينــة علــى ذلــك ‪ ،‬وأطلــب ميــن املدعــى‬\n‫عليــه ‪ .....‬علــى إنــكار ذلــك ‪ ،‬علمــا بــأن املبلــغ مقابــل بضاعــة ‪ ،‬وقــد‬\n‫اســتلمه ‪ ......‬وبعــرض ذلــك علــى املدعــى عليــه ‪ .....‬قــال ‪ :‬لــم اســتلم مــن‬\n‫‪ .....‬ســوى ثالثــون ألــف ريــال فقــط ‪ ،‬ومســتعد باحللــف علــى ذلــك ‪ .‬ثــم‬\n‫حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أننــي لــم اســتلم مــن ‪.....‬‬\n‫ســوى مبلــغ قــدره ثالثــون ألــف ريــال ‪ ،‬وذلــك مقابــل بضاعــة الورشــة‬\n‫ومســودع اخلمــرة ‪ .‬هكــذا حلــف ‪ .‬وبســؤال املدعيــة عــن الســيارات‬\n‫والرافعــة الشــوكية التــي ادعــت أنهــا مــن تركــة املــورث قالــت ‪ :‬لــدي‬\n‫شــهود ســأحضرهم يف اجللســة القادمــة ‪ .‬وبســؤال املدعــى عليــه ‪ .....‬عــن‬\n‫البينــة علــى أن املنتجــع الصيفــي الواقــع بجمهوريــة لبنــان واملســجل باســم‬\n‫الوالــدة ‪ .....‬للمــورث قــال ‪ :‬ليــس لــدي بينــة ‪ ،‬وأطلــب ميــن املدعيــة علــى‬\n‫اإلنــكار ‪ .‬وبعرضــه علــى املدعيــة قالــت ‪ :‬هــو ملــك للمــورث ‪ ،‬ومســجل‬\n‫باســم الوالــدة ‪ .‬فأفهمــت الطرفــن أن الدعــاوى املتعلقــة بعقــار خــارج‬\n‫اململكــة ال تختــص محاكــم اململكــة بنظرهــا بنــاء علــى املــادة ‪28‬‬\n‫مــن نظــام املرافعــات الشــرعية ‪ .‬وبســؤال املدعــى عليــه ‪ .....‬عــن الصــك‬\n‫الصــادر مــن هــذه احملكمــة والــذي يدعــي بأنــه صــادر علــى تركــة‬\n‫املــورث قــال‪ :‬ليــس لــدي نســخة منــه ‪ ،‬ويتعــذر ‪ .....‬إحضــاره ‪ .‬وبســؤال‬\n\n\n                                                                                        ‫‪322‬‬\n\f      ‫املدعــى عليــه ‪ .....‬عــن البينــة علــى بيعــه لــأرض املكونــة مــن ثــاث قطــع‬\n      ‫بثالثمائــة ألــف ريــال ‪ ،‬وأنــه ســلم والدتــه نصــف الثمــن والنصــف اآلخــر‬\n      ‫ســداد ديــن يف ذمــة املــورث قــال ‪ :‬ليــس لــدي بينــة وقــد بعتهــا قبــل حوالــي‬\n      ‫ثمانيــة وعشــرون عامــا ‪ ،‬وليــس لــدي نســخة مــن صــك العقــار وبســؤال‬\n      ‫املدعيــة عــن موضــوع الرهينــة قالــت ‪ :‬إنــه بعــد عودتــي مــن ســفر ذهبــت‬\n      ‫لبيــت مســتأجر للمــورث وإذا بــه مغلــق وليــس بــه ســوى بــراد وتلفــاز‬\n      ‫وغســالة قدميــة ال تعمــل جيــدا ‪ ،‬وال يوجــد غيــر ذلــك مــن عفــش البيــت ‪،‬‬\n      ‫وكان علــى املــورث قســط مــن األجــرة قــدره عشــرة آالف ريــال ‪ ،‬وقــد‬\n      ‫دفعتهــا عنــه ‪ .‬وبســؤال املدعيــة عــن الورقــة التــي تنــازل فيهــا املدعــى‬\n      ‫عليهمــا قالــت ‪ :‬هــي وثيقــة البيــع فقــط ‪ ،‬وقــد تنــازال عــن نصيبيهمــا‬\n      ‫للوالــدة ‪ .‬وبعرضــه علــى املدعــى عليهمــا قــاال ‪ :‬لقــد تنازلنــا بنصيبينــا‬\n                                                                                  ‫للوالــدة ‪.‬‬\n      ‫وبســؤال املدعــى عليــه ‪ .....‬عــن قيمــة عــدة الورشــة قــال ‪ :‬تســاوي عشــرة‬\n      ‫آالف ريــال حــن أخذتهــا قبــل حوالــي ثمانيــة وعشــرين عامــا ‪ ،‬والزالــت‬\n      ‫موجــودة حتــى اآلن ‪ ،‬وفريــزر أملونيــوم أملانــي الصنــع مــن شــركة ‪........‬‬\n      ‫ويقــدر بحوالــي خمســة عشــر ألــف ريــال آنذاك ‪ ،‬وثالثة دريــات وطاولة‬\n      ‫وملزمــة تقــدر تلــك جميعــا بخمســمائة ريــال يف ذلــك الوقــت ‪ ،‬وتلــك‬\n      ‫املعــدات ال تعمــل منــذ أكثــر مــن خمســة عشــر ســنة ‪ .‬هكــذا حلــف‪.‬‬\n      ‫وبســؤال املدعــى عليــه ‪ .....‬مــن اســتلم ثمــن البضاعــة التــي كانــت يف‬\n      ‫الورشــة وقــدره ســتون ألــف ريــال قــال ‪ :‬أنــا مــن اســتلمها مــن املشــتري ‪.....‬‬\n      ‫وســلمت الوالــدة مــن ثمنهــا ثالثــون ألــف ريــال ‪ .‬وبعرضــه علــى املدعيــة‬\n      ‫قالــت ‪ :‬غيــر صحيــح ‪ .‬وبطلــب البينــة مــن املدعــى عليــه ‪ .....‬علــى تســليم‬\n      ‫الوالــدة ثالثــون ألــف ريــال مــن ثمــن البضاعــة قــال‪ :‬ال‪ .‬وبعــرض اليمــن‬\n\n\n‫‪323‬‬\n\f‫علــى املدعيــة علــى عــدم علمهــا مبــا دفــع بــه املدعــى عليــه ‪ .....‬اســتعدت‬\n‫لذلــك ‪ ،‬ثــم حلفــت قائلــة ‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أننــي ال‬\n‫أعلــم بــأن املدعــى عليــه ســلم الوالــدة مــن ثمــن البضاعــة التــي كانــت‬\n‫يف ورشــة مورثنــا والتــي ذكــر بأنــه باعهــا بســتني ألــف ريــال شــيئا ‪.‬‬\n‫هكــذا حلفــت ‪ .‬ثــم طلبــت مــن املدعيــة إحضــار بقيــة املدعــن فوعــدت‬\n‫بذلــك يف اجللســة القادمــة‪ .‬ثــم رفعــت اجللســة لذلــك ‪ .‬ويف يــوم االثنــن‬\n‫املوافــق ‪1434/02/25‬ه ـ افتتحــت اجللســة الســاعة ‪ 08 : 30‬وفيهــا‬\n‫حضــر الطرفــان‪ ،‬وحضــرت املدعيــة‪ .....‬لبنانيــة اجلنســية مبوجــب جــواز‬\n‫ســفر رقــم‪ ،.....‬وبعــرض اليمــن علــى املدعيــة ‪ .....‬علــى عــدم علمهــا مبــا‬\n‫دفــع بــه املدعــى عليــه‪ .....‬مــن تســليمه لثمــن البضاعــة التــي كانــت يف‬\n‫ورشــة املــورث والتــي ذكــر أنــه باعهــا بســتني ألــف ريــال ‪ ،‬اســتعدت‬\n‫لذلــك‪ ،‬ثــم حلفــت قائلــة‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أننــي ال أعلــم‬\n‫بــأن املدعــى عليــه ‪ .....‬ســلم الوالــدة مــن ثمــن البضاعــة التــي كانــت يف‬\n‫ورشــة مورثنــا والتــي ذكــر بأنــه باعهــا بســتني ألــف ريــال شــيئا ‪ .‬هكــذا‬\n‫حلفــت‪ .‬وبســؤال املدعيــة عــن بقيــة الورثــة املدعــن قالــت ‪ :‬إنهــن خــارج‬\n‫اململكــة‪ .‬وبعــرض ذلــك علــى املدعــى عليــه‪ .....‬قــال ‪ :‬أكتفــي بيمــن‬\n‫مــن حضــر وحلــف ‪ .‬وبســؤال الطرفــن هــل لديكمــا مــا تضيفانــه قــاال‪:‬‬\n‫ال‪ .‬ثــم رفعــت اجللســة للتأمــل‪ .‬ويف يــوم الثالثــاء املوافــق ‪1434/02/26‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 02 : 15‬وفيهــا حضــر الطرفــان‪ ،‬وبســؤالهما‬\n‫عــن صــك حصــر ورثــة املــورث أبــرزت املدعيــة صــورة منــه‪ ،‬والصــادر‬\n‫مــن احملاكــم الشــرعية الســنية باجلمهوريــة اللبنانيــة واملــدون عليــه رقــم‬\n‫‪ ،492‬ومــدون عليــه أيضــا رقــم ‪ 494‬و ‪ 985/4/3‬واملــؤرخ يف ‪ 3‬نيســان‬\n‫‪1985‬م واملتضمــن وفــاة ‪ .....‬يف بيــروت بتاريــخ ‪1985/3/9‬م وانحصــر‬\n\n\n                                                                                        ‫‪324‬‬\n\f      ‫ورثته يف والدته ‪ .....‬وزوجته ‪ .....‬ويف أوالده منها وهم ‪ .....‬و‪ .....‬و‪ .....‬و‪.....‬‬\n      ‫و‪ .....‬وو‪ .....‬ال وارث لــه ســواهم ‪ .‬أه ـ ومت تزويــد أوراق املعاملــة بــه ‪ .‬فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ‪ ،‬وبنــاء علــى إقــرار املدعــى عليــه‬\n      ‫‪ .....‬احملــرر علــى أوراق الورشــة الهندســية ألعمــال احلديــد واألملونيــوم‬\n      ‫واملتضمــن أن األراضــي رقــم ‪ 724‬و ‪ 726‬و ‪ 729‬مبخطــط اجلبيــري‬\n      ‫والورشــة املشــتراة ‪ .....‬هــي ملــك للمــورث ‪ ،‬وهــي مســجلة باســم املدعــى‬\n      ‫عليــه فقــط ‪ ،‬وصــادق املدعــى عليــه ‪ .....‬علــى ذلــك اإلقــرار احملــرر ‪،‬‬\n      ‫ودفــع بــأن املــورث أوصــى لــه بالقطــع الثــاث مــن مخطــط اجلبيــري بعــد‬\n      ‫مماتــه‪ ،‬وأنكــرت املدعيــة ذلــك ‪ ،‬وهــي وصيــة باطلــة ملخالفتهــا احلديث‬\n      ‫(ال وصيــة لــوارث) رواه اإلمــام أحمــد وغيــره وبنــاء علــى إقــرار املدعــى‬\n      ‫عليــه ‪ .....‬ببيعــه القطــع الثــاث بثالثمائــة ألــف ريــال ‪ ،‬ثــم دفــع بتســليم‬\n      ‫والدتــه نصــف الثمــن ‪ ،‬وأنكــرت املدعيــة ذلــك‪ ،‬كمــا دفــع بســداد‬\n      ‫ديــون علــى املــورث بالنصــف الــذي اســتلمته مــن ثمــن القطــع ‪ ،‬وأنكــرت‬\n      ‫املدعيــة ذلــك ‪ ،‬ولــم يقــم البينــة عليــه وحلفــت املدعيــة علــى إنــكاره ‪،‬‬\n      ‫وعــارض كالمــه هــذا مــا ســبق بــأن القطــع قــد أوصــى لــه مورثــه بهــا ‪،‬‬\n      ‫وهــذا تناقــض يــدل علــى عــدم صدقــه ‪ ،‬وبنــاء علــى إقــرار املدعــى عليــه‬\n      ‫‪ .....‬باســتالمه مبلــغ خمســة آالف ريــال مــن صبــوح النعمانــي وأنــه لــم‬\n      ‫يســلم الورثــة منــه شــيئا ‪ ،‬وبنــاء علــى شــهادة الشــاهد ‪ ..... .....‬بــأن املدعى‬\n      ‫عليهمــا ‪ .....‬و‪ .....‬قــد تنــازال عــن نصيبهمــا يف األرض التــي اشــتراها مــن‬\n      ‫الورثــة مبائــة وعشــرة آالف ريــال إلخوتهمــا ‪ ،‬وبنــاء علــى اإلقــرار احملــرر‬\n      ‫بذلــك ‪ ،‬وقــد صــادق املدعــى عليهمــا ‪ .....‬علــى ذلــك ‪ ،‬وبنــاء علــى إقــرار‬\n      ‫املدعــى عليــه ‪ .....‬باســتالمه مبلــغ مائتــا ألــف ريــال مــن الســيدة ‪، .... /‬‬\n      ‫ودفــع بتســليمه لوالدتهــم دون بينــة ‪ ،‬وأنكــرت املدعيــة ذلــك ‪ ،‬وبنــاء‬\n\n\n‫‪325‬‬\n\f‫علــى إقــرار املدعــى عليــه ‪ .....‬باســتالمه مبلــغ ثالثــون ألــف ريــال مــن‬\n‫الســيد ‪ .....‬وأنكــر مــا عــدا ذلــك ‪ ،‬ولــم تقــم املدعيــة البينــة علــى ذلــك‪،‬‬\n‫وحلــف املدعــى عليــه علــى إنــكار اســتالمه مــن ‪ .....‬أكثــر مــن ذلــك ثــم‬\n‫عــاد فأقــر يف جلســة أخــرى بأنــه اســتلم مبلغــا قــدره ســتون ألــف ريــال من‬\n‫‪ ، .....‬ودفــع بتســليم والدتــه ثالثــون ألــف ريــال منــه ‪ ،‬وأنكــرت املدعيــة‬\n‫ذلــك ‪ ،‬ولــم يقــم البينــة عليــه وحلفــت املدعيــة علــى إنــكار ذلــك ‪ ،‬وبنــاء‬\n‫علــى إنــكار املدعــى عليــه ‪ .....‬بيــع أرض ‪ .....‬وعــدم علمــه مبــا آلــت إليــه‬\n‫ولــم تقــم املدعيــة البينــة علــى مــا أنكــره ‪ ،‬وحلــف علــى إنــكاره ‪ ،‬وبنــاء‬\n‫علــى مــا دفــع بــه املدعــى عليــه ‪ .....‬مــن وجــود ديــون علــى التركــة ‪،‬‬\n‫وأنكــرت املدعيــة ذلــك ‪ ،‬ولــم يقــم البينــة عليــه ‪ ،‬وحلفــت املدعيــة علــى‬\n‫إنــكاره ‪ ،‬وبنــاء علــى إقــرار املدعــى عليــه ‪ .....‬ألخــذه عــدة الورشــة وأنهــا‬\n‫تســاوي عشــرة آالف ريــال حــن أخذهــا ‪ ،‬ثــم أقــر بــأن املعــدات هــي‬\n‫منشــارين أملونيــوم مــن شــركة (كلــن بــاخ) قيمــة الواحد منهما خمســة‬\n‫آالف ريــال ‪ ،‬وفريــزر أملونيــوم أملانــي مــن شــركة ســيدار ويقــدر بحوالــي‬\n‫خمســة عشــر ألــف ريــال ‪ ،‬وثــاث دريــات وطاولــة ملزمــة تقــدر جميعــا‬\n‫بخمســمائة ريــال ‪ ،‬وتعــذر تقديرهــا عــن طريــق أهــل اخلبرة بحســب إفادة‬\n‫املدعيــة ‪ ،‬وطلبــت ميــن املدعــى عليــه ‪ .....‬علــى ذلــك ‪ ،‬فحلــف عليــه ‪،‬‬\n‫وحلديــث (علــى اليــد مــا أخــذت حتــى تؤديــه) رواه األربعــة ‪ ،‬وحلديــث (أن‬\n‫النبــي صلــى اهلل عليــه وســلم قضــى أن اليمــن علــى املدعــى عليــه) رواه‬\n‫البخــاري ‪ ،‬وحلديــث (البينــة علــى املدعــي واليمــن علــى املدعــى عليــه)‬\n‫رواه الترمــذي ‪ ،‬قــال أبــو عيســى ‪ :‬العمــل عنــد أهــل العلــم مــن أصحــاب‬\n‫النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن‬\n‫علــى املدعــى عليــه ‪ ،‬لذلــك كلــه ‪ ،‬فقــد حكمــت علــى املدعــى عليــه‬\n\n\n                                                                                        ‫‪326‬‬\n\f      ‫‪ .....‬دفــع مبلــغ قــدره مائــة وثمانيــة عشــر ألفــا وخمســة وخمســون ريــاال‬\n      ‫وخمســة وخمســون هللــة للمدعيــات ‪ ، ..... ..... .....‬ونصيــب كل مدعيــة‬\n      ‫مــن ذلــك املبلــغ مبلغــا قــدره ثالثــة وعشــرون ألفــا وســتمائة وأحــد عشــر‬\n      ‫ريــاال وأحــد عشــر هللــة ‪ ،‬وحكمــت علــى املدعــى عليــه ‪ .....‬دفــع مبلــغ‬\n      ‫قــدره مائــة وأربعــة عشــر ألفــا وثالثمائــة وســبعة عشــر ريــاال وخمســة‬\n      ‫عشــر هللــة للمدعيــات ‪ ، ..... ..... ..... .....‬ونصيــب كل مدعيــة مــن ذلــك‬\n      ‫املبلــغ مبلغــا قــدره اثنــان وعشــرون ألفــا وثمامنائــة وثالثــة وســتون ريــاال‬\n      ‫وثالثــة وأربعــون هللــة ‪ ،‬ورددت مــا عــدا ذلــك مــن طلبــات لعــدم ثبــوت‬\n      ‫موجبــه ‪ ،‬وأفهمــت املدعــى عليهمــا بــأن لهمــا الرجــوع علــى والدتهمــا‬\n      ‫فيمــا ادعيــا تســليمه لهــا ‪ .‬وبــه حكمــت ‪ .‬وبــه قنعــت املدعيــة ‪ ،‬وقــرر‬\n      ‫املدعــى عليهمــا االعتــراض ‪ ،‬وجــرى تســليمهما نســخة مــن احلكــم‬\n      ‫وإفهامهمــا بــأن لهمــا احلــق يف االعتــراض عليــه خــال ثالثــن يومــا‬\n      ‫‪ ،‬وإال ســقط حقهمــا يف االعتــراض ‪ ،‬واكتســب احلكــم القطعيــة ‪.‬‬\n      ‫وأقفلــت اجللســة الســاعة ‪ . 02 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/26‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة ففــي يــوم االثنــن املوافــق ‪1434/06/05‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 08 : 45‬وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫بخطــاب رئيســها رقــم ‪ 33122398‬وتاريــخ ‪1434/5/27‬ه ـ ومرفــق بــه‬\n      ‫القــرار رقــم ‪ 34216327‬وتاريــخ ‪1434/5/19‬ه ـ واملتضمــن أنــه (تقــرر‬\n      ‫باألكثريــة إعادتهــا لفضيلتــه ملالحظــة مــا يلــي ‪ -1 :‬تعديــل الشــاهد‬\n      ‫مــا دام شــهادته موصلــة ‪ -2‬املــورث لــه ورثــة خــاف املدعيــات فأيــن‬\n      ‫نصيبهــم ونصيــب املدعــى عليهمــا ‪ -3‬تصحيــح األخطــاء اإلمالئيــة‬\n\n\n‫‪327‬‬\n\f‫واللغويــة واملطبعيــة وهــي كثيــرة جــدا) أه ـ وعليــه أجيــب أصحــاب‬\n‫الفضيلــة فيمــا يخــص املالحظــة األولــى فــإن تعديــل الشــاهد لــم يــدل‬\n‫عليهــا دليــل شــرعي صحيــح ‪ ،‬والرســول صلــى اهلل عليــه وســلم كان‬\n‫يقبــل شــهادة الشــاهد دون أن يطلــب تعديلــه ‪ ،‬والغــرض مــن التعديــل‬\n‫أن يكــون املعــدل للشــاهد معــروف احلــال لــدى القاضــي ‪ ،‬وإال فــإن‬\n‫تعديــل الشــاهد مــن قبــل مجهــول احلــال لــدى القاضــي يوجــب الــدور ‪،‬‬\n‫واألصــل يف املســلم العدالــة ‪ ،‬ولــم يطعــن املدعــى عليهمــا بالشــاهد ‪،‬‬\n‫ويف حــال اســتراب ناظــر القضيــة مــن الشــاهد فيتوجــه طلــب تعديلــه ‪،‬‬\n‫وفيمــا يخــص املالحظــة الثانيــة فــإن الدعــوى تنحصــر علــى املدعيــات‬\n‫‪ ،‬فــا يحكــم لغيرهــن ‪ ،‬ونظــر القاضــي قاصــر علــى طلــب املدعــي‬\n‫بالصفــة التــي تخولــه ‪ ،‬فقــد يقبــل غيرهــن بذلــك ‪ ،‬فمــا وجــه احلكــم‬\n‫لهــم مبــا لــم يطالبــوا بــه ‪ ،‬وأمــا نصيــب املدعــى عليهمــا فقــد مت احتســابه‬\n‫مــن مجمــل مــا دار عليــه اخلــاف فلــم يلــزم املدعــى عليهمــا بدفع شــيء إال‬\n‫نصيــب املدعيــات فقــط ‪ ،‬وفيمــا يخــص املالحظــة الثالثــة فمــا وقــع مــن‬\n‫أخطــاء إمنــا هــي ممــا قدمــه الطرفــان مبذكراتهــم ‪ ،‬والتــي يتــم تقدميهــا‬\n‫يف أوعيــة إلكترونيــة ويتــم رصدهــا كمــا هــي ‪ ،‬ويصعــب تدقيــق كل‬\n‫مذكــرة يتقــدم بهــا األطــراف ‪ ،‬الســيما مــع طولهــا ‪ ،‬وعليــه فلــم يظهــر‬\n‫لــي خــاف مــا حكمــت بــه ‪ ،‬وقــررت إحلــاق ذلــك علــى صــك احلكــم‬\n‫وســجله ‪ ،‬وإعــادة املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم بعــد‬\n‫اإلجــراء األخيــر ‪ .‬وأقفلــت اجللســة الســاعة ‪ . 09 : 00‬وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                             ‫‪1434/06/05‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n\n\n                                                                                       ‫‪328‬‬\n\f      ‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة الثانيــة مبحكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بجــدة املســاعد برقــم ‪33122398‬‬\n      ‫وتاريــخ ‪1434/6/7‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫‪ .....‬القاضــي باحملكمــة العامــة بجــدة واملســجل بعــدد ‪3448838‬وتاريــخ‬\n      ‫‪1434/2/26‬ه ـ و املتضمــن دعــوى‪ ..... /‬ضــد‪ ...../‬و ‪ .....‬واحملكــوم فيــه‬\n                                                                    ‫مبــا دون باطنــه ‪.‬‬\n      ‫وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n      ‫باألكثريــة املوافقــة علــى احلكــم واهلل املوفــق‪ .‬علــى نبينــا محمــد وعلــى‬\n                                                               ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪329‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":299,"source_page_end":329,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ac8a8cc7525af54376c523acaa6e55f8dcdefd85b4b73d4b6c7de60ecc3dd8ce","normalized_text_hash":"1778a1ec9682d1c6f8deead9c7c6439def25745f0730d5d67490a135e1450a5b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p299-3448838"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"90a05577-e72d-5f91-9e28-7fb1aa92484c","document_type":"judgment","category":"judicial","subcategory":"general","title":"هبة -هدية زوج -اإلهداء بعد عقد النكاح وقبل الدخول -طلب الزوج إعادة الهدايا -جرى العرف أن ما يهديه الزوج لزوجته قبل الدخول هو من قبيل الهدية -العادة محكمة -حلف اليمن على أن الهدية ليست بنية االرجاع -احلكم بصرف النظر عن دعوى املدعي وإخاء سبيل املدعى عليها .","document_number":"34198975","case_number":"33309200","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/27","year":"1434","subject":"هبة -هدية زوج -اإلهداء بعد عقد النكاح وقبل الدخول -طلب الزوج إعادة الهدايا -جرى العرف أن ما يهديه الزوج لزوجته قبل الدخول هو من قبيل الهدية -العادة محكمة -حلف اليمن على أن الهدية ليست بنية االرجاع -احلكم بصرف النظر عن دعوى املدعي وإخاء سبيل املدعى عليها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34198975 :‬تاريخه ‪1434/4/27 :‬هـ‬\n                        ‫رقم الدعوى‪33309200 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34240178‬تاريخه ‪1434/6/13:‬هـ‬\n\n\n      ‫هبــة ‪ -‬هديــة زوج ‪ -‬اإلهــداء بعــد عقــد النــكاح وقبــل الدخــول ‪ -‬طلــب‬\n      ‫الــزوج إعــادة الهدايــا ‪ -‬جــرى العــرف أن مــا يهديــه الــزوج لزوجتــه قبــل‬\n      ‫الدخــول هــو مــن قبيــل الهديــة ‪ -‬العــادة محكمــة ‪ -‬حلــف اليمــن علــى‬\n      ‫أن الهديــة ليســت بنيــة االرجــاع ‪ -‬احلكــم بصــرف النظــر عــن دعــوى‬\n                                          ‫املدعــي وإخــاء ســبيل املدعــى عليهــا ‪.‬‬\n\n\n\n      ‫‪ -‬قولــه صلــى اهلل عليــه وســلم ‪ ( :‬البنيــة علــى املدعــي واليمــن علــى‬\n                                                                     ‫مــن أنكــر ) ‪.‬‬\n                                        ‫‪ -‬القاعدة الفقهية ( العادة محكمة ) ‪.‬‬\n\n\n\n      ‫حضــر املدعــي وادعــى بأنــه مت عقــد نكاحــه علــى موكلــة املدعــى‬\n      ‫عليــه علــى مهــر وقــدره ثالثــون ألــف ريــال وقــدم لهــا ‪ 4‬أطقــم ذهــب‬\n      ‫مببلــغ ‪ 38150‬ريــال و ‪ 2‬ســاعة رجالــي بقيمــة ‪ 1230‬ريــال وأســورة بقيمــة‬\n      ‫‪ 3229‬وسلســلة بقيمــة ‪ 820‬ريــال وسلســلة تلبيســه بقيمــة ‪ 2100‬ريــال‬\n      ‫ودبلــة أملــاس ســوليتر بقيمــة ‪ 4200‬ريــال ليتــم اختيــار طقــم واحــد مــن‬\n      ‫قبــل املدعــى عليهــا لتناســب فســتانها ثــم تقــوم بإرجــاع الباقــي لتقدميــه‬\n      ‫بعــد الــزواج كاملعتــاد وقــد اســتلمها أخوهــا املدعــى عليــه وكالــة‬\n\n‫‪265‬‬\n\f‫وعنــد مطالبتــه لألغــراض ألن معظمهــا ألهلــه رفضــت املدعيــة وبــدأت‬\n‫بافتعــال املشــاكل وطلبــت فســخ النــكاح ويطلــب إعــادة كل مــا ذكــر‬\n‫وأمــا طقــم الذهــب الرابــع والــذي قيمتــه ‪ 9450‬ريــال فــا مانــع أن يبقــى‬\n‫معهــا حســب العــرف حتــى يــرى هــل يتــم الــزواج أم ال ـ وبعــرض دعــوى‬\n‫املدعــي علــى املدعــى عليــه وكالــة طلــب صــورة مــن الدعــوى لعرضهــا‬\n‫علــى موكلتــه واإلجابــة عنهــا يف اجللســة الثانيــة ‪ .‬و يف جلســة أخــرى‬\n‫حضــر الطرفــان وبســؤال املدعــى عليــه وكالــة عــن جوابــه قــدم جواب ـ ًا‬\n‫محــرر ًا أشــير إليــه يف ضبــط القضيــة وممــا جــاء فيــه مصادقــة املــرأة‬\n‫علــى عقــد النــكاح وعلــى املهــر الــذي ذكــر وقــد خــا بهــا عــدة مــرات‬\n‫خلــوة شــرعية كامل ـةـ ومــا ذكــره بخصــوص تقــدمي األطقــم الذهبيــة‬\n‫واألســورة والسلســلة فــإن املدعــي لــم يحــرر فيهــا دعــواه وقــال إن‬\n‫معظمهــا ألهلــه فمــا هــو الــذي ألهلــه حتديــد ًا ـ مــا ذكــره مــن تســليمه‬\n‫األطقــم الذهبيــة والسلســلة وأســورة الختيــار مــا يناســبها وتعيــد الباقــي‬\n‫فهــذا غيــر صحيــح والصحيــح أنــه قدمهــا لهــا هديــة زوج لزوجتــه كمــا‬\n‫يف عــرف البــاد مــن غيــر طلــب منهــا ولــم يشــترط ذلــك عليــه ولــم تكــن‬\n‫مــن املهــر املســمى يف العقــد وقــد قــدم هــذه األغــراض تبرعـ ًا منــه وهبــة‬\n‫ملكتهــا املدعــى عليهــا بالقبــض بدليــل أن األنــواع مختلفــة ومســمياتها‬\n‫مختلفــة وليســت مــن جنــس واحــد الختيــار مــا يناســب الفســتان وهــذه‬\n‫األغــراض يف عــرف املجتمــع يقدمهــا الــزوج لزوجتــه هديــة زواج وتقديــر‬\n‫ولــو لــم يقدمهــا الــزوج لزوجتــه لــم يؤثــر هــذا يف زواجهــا وال يف عقــد‬\n‫النــكاح ولــن تعيدهــا لــه ـ وأمــا الســاعتني الرجاليــة فقــد ســلمها‬\n‫ألخيهــا املدعــى عليــه وكالــة هديــة منــه ألبيهــا وأخيهــا وقــد قبضاهــا‬\n‫وإذا كان لــه دعــوى فليقمهــا عليهمــا وال شــأن لهــا يف هــذه األغــراض‬\n\n\n                                                                                     ‫‪266‬‬\n\f      ‫ـ وبعــرض ذلــك علــى املدعــى أنكــر اختالئــه باملدعــى عليهــا واللقــاء‬\n      ‫يكــون بحضــرة أمهــا ـ وأمــا مــا ذكرتــه املــرأة بخصــوص األطقــم ألهــل‬\n      ‫املدعــي فيقصــد أن األطقــم منــه ولكــن املبلــغ املشــترى بهــا منــه ألمــه‬\n      ‫ومنــه ألختــه ـ ومــا ذكرتــه مــن كونــه هديــة زوج لزوجتــه فليــس بصحيح‬\n      ‫ـ ومــا ذكرتــه مــن كــون الســاعتني الرجاليــة التــي ســلمت ألخيهــا فهــذا‬\n      ‫صحيــح واألخــرى ســلمها املدعــي ضمــن مجموعــة ولــم يســلمها لوالدهــا‬\n      ‫ولكنهــا ليــس علــى ســبيل الهديــة ـ والتــي جــاء بهــا تلبيــة لطلبهــا لتراهــا‬\n      ‫قبــل موعدهــا ـ بســؤاله عــن بينتــه بــأن مــا قدمــه ممــا ادعــى بــه علــى‬\n      ‫نيــة الرجــوع بعــد مشــاهدته فقــط فأجــاب ليــس لديــه بينــه ولكــن‬\n      ‫العــرف يقتضــي مــا ذكــره يف دعــواه ـ جــرت الكتابــة لقســم اخلبــراء‬\n      ‫لإلفــادة عمــا لديهــم مــن العــرف اجلــاري والســائد يف مثــل هــذه احلالــة ـ‬\n      ‫جــاء اجلــواب مــن قســم اخلبــراء يتضمــن أن العــرف الســائد بــن النــاس‬\n      ‫أنــه إذا قــدم الرجــل ملخطوبتــه هديــة بــدون شــرط مــن املــرأة أو مــن‬\n      ‫أهلهــا فإنهــا يف هــذه احلالــة تعتبــر هديــة هــذا هــو العــرف الســائد ـ وأنــه‬\n      ‫قدمهــا قبــل الــزواج وهــذا دليــل علــى أنــه قدمــه ترغيبـ ًا لهــا يف الــزواج ‪-‬‬\n      ‫بعــرض ذلــك علــى املدعــي قــرر أنــه لــم يقدمــه علــى أنــه هديــة ـ مت إفهــام‬\n      ‫املدعــي بأنــه ليــس لــه إال ميــن املدعــى عليهــا ـ يف جلســة أخــرى حضــرت‬\n      ‫املدعــى عليهــا أصالــة ولــم يحضــر املدعــي رغــم معرفتــه باملوعــد ومت‬\n      ‫عــرض اليمــن عليهــا بعــد تخويفهــا بــاهلل فاســتعدت فحلفــت اليمــن‬\n      ‫كمــا طلــب منهــا ‪ -‬نظــر ًا إلنــكار املدعــى عليهــا وعــدم وجــود بينــة‬\n      ‫للمدعــي وألداء املدعــى عليهــا اليمــن و لقولــه صلــى اهلل عليــه وســلم‬\n      ‫( البينــة علــى املدعــي واليمــن علــى مــن أنكــر ) وللقاعــدة الفقهيــة (‬\n      ‫العــادة محكمــة ) ـ صــدر احلكــم بصــرف النظــر عــن دعــوى املدعــي‬\n\n\n‫‪267‬‬\n\f‫وإخــاء ســبيل املدعــى عليهــا مــن هــذه الدعــوى ـ ـ قــررت املدعــى عليهــا‬\n‫القناعــة ـ مت بعــث نســخة مــن احلكــم للمدعــي لتقــدمي اعتراضــه خــال‬\n‫املــدة النظاميــة وإفهامــه أنــه يف حالــة عــدم تقــدمي اعتراضــه يكتســب‬\n        ‫احلكــم القطعيــة ‪ .‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة باملدينــة املنورة‪/‬املســاعد برقــم ‪ 33309200‬وتاريــخ‬\n‫‪ 1433/05/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33840163‬وتاريــخ‬\n‫‪ 1433/05/03‬ه ـ ففــي يــوم األحــد املوافــق‪ 1433/05/23‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪08 : 52‬وفيهــا حضــر ‪ .......‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .......‬وحضــر حلضــوره ‪ .......‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .......‬مبوجــب الوكالــة رقــم ‪ .......‬وتاريــخ‬\n‫ا ‪ :‬قــد مت عقــد نكاحــي علــى املــرأة ‪.......‬‬‫‪1433/5/22‬ه ـ وادعــى قائـ ً‬\n‫بالعقــد رقــم ‪ .......‬وتاريــخ ‪1433/3/19‬ه ـ علــى مهــر وقــدره ثالثــون‬\n‫ألــف ريــال مت تســليمه وقدمــت لهــا ‪ 4‬أطقــم ذهــب بقيمــة ‪38150‬‬\n‫ريــال و‪ 2‬ســاعة رجالــي بقيمــة ‪1230‬ريــال وأســورة بقيمــة ‪3229‬ريــال‬\n‫وسلســلة بقيمــة ‪ 820‬ريــال وسلســلة تلبيســة بقيمــة‪ 2100‬ريــال ودبلــة‬\n‫أملــاس ســوليتيربقيمة‪ 4200‬ريــال ليتــم اختيــار طقــم واحــد مــن قبلهــا‬\n‫ليناســب فســتانها ثــم تقــوم بإرجــاع الباقــي لتقدميــه بعــد الــزواج كاملعتاد‬\n‫وقــد أســتلمها أخوهــا ‪ .......‬وعنــد مطالبتــي لألغــراض ألن معظمهــا‬\n\n                                                                                     ‫‪268‬‬\n\f      ‫ألهلــي رفضــت وبــدأت بافتعــال املشــاكل وطلبــت فســخ النــكاح لــذا‬\n      ‫أطلــب إعــادة كل مــا ذكــرت وأمــا طقــم الذهــب الرابــع الــذي قيمتــه‬\n      ‫تســعة آالف وأربــع مئــة وخمســون ريــا ًال فــا مانــع أن يبقــى معهــا حســب‬\n      ‫العــرف حتــى نــرى هــل يتــم الــزواج أم ال هكــذا ادعــى ‪ ،‬وبعــرض دعــواه‬\n      ‫علــى املدعــى عليــه وكالــة أجــاب ‪ :‬أطلــب صــورة مــن دعــوى املدعــى‬\n      ‫لعرضهــا علــى موكلتــي واإلجابــة عليهــا يف اجللســة القادمــة فجــرى‬\n      ‫تســليم املدعــى عليــه صــورة مــن دعــوى املدعــي ويف يــوم آخــر حضــر‬\n      ‫الطرفــان وبســؤال املدعــى عليــه وكالــة عــن جوابــه قدمــه مكتوب ـ ًا‬\n      ‫ونــص احلاجــة منــه ‪،‬أوال ‪ :‬مــا ذكــره مــن عقــد النــكاح بــي علــى املهــر‬\n      ‫الــذي ذكــر وقــدره ثالثــون ألــف ريــال فصحيــح أمــا مــا ذكــر مــن عــدم‬\n      ‫حصــول الدخــول بــي فصحيــح أيض ـ ًا إال أن املدعــي قــد خــا بــي عــدة‬\n                                                       ‫مــرات خلــوة شــرعية كاملــة‪.‬‬\n      ‫ثاني ـ ًا ‪ :‬مــا ذكــره مــن تقــدمي األطقــم الذهبيــة واألســورة والسلســة فــان‬\n      ‫املدعــي لــم يحــرر فيهــا دعــواه إذ قــال أن معظمهــا ألهلــه‪ ،‬فمــا هــو الــذي‬\n                                ‫ألهلــه منهــا حتديــد ًا حتــى يكــون اجلــواب مالقيـ ًا‬\n      ‫ثالثـ ًا ‪ :‬مــا ذكــره مــن تســليمه األطقــم الذهبيــة والسلســة وأســورة وأنهــا‬\n      ‫الختيــار مــا يناســبني وأعيــد الباقــي فهــذا غيــر صحيــح والصحيــح أنــه‬\n      ‫قدمهــا لــي هديــة زوج لزوجتــه كمــا هــو عــرف البــاد مــن غيــر طلــب‬\n      ‫منــي ولــم أشــترط ذلــك عليــه ولــم تكــن مــن املهــر املســمى بيننــا يف‬\n      ‫العقــد إذ إن املهــر محــدد يف عقــد النــكاح الشــرعي الــذي ذكــره‬\n      ‫يف دعــواه والشــيء ســواه وقــد قــدم هــذه األغــراض بطوعــه واختيــاره‬\n      ‫وتبــرع منــه وهبــة ملكتهــا بالقبــض وبدليــل أن األغــراض التــي ذكرهــا‬\n      ‫أنواعهــا مختلفــة ومســمياتها مختلفــة وليســت مــن جنــس واحــد حتــى‬\n\n\n‫‪269‬‬\n\f‫يتــم اختيــار مــا يناســب الفســتان كمــا يدعــي ويعــاد مــاال يناســبه وهــذه‬\n‫األغــراض التــي ذكــر يقدمهــا يف عــرف مجتمعنــا الــزوج لزوجتــه هديــة‬\n‫زواج وتقديــر ولــو لــم يقدمهــا الــزوج لزوجتــه لــم يؤثــر هــذا يف زواجهمــا‬\n            ‫وال يف عقــد النــكاح لــذا فــا حــق لــه فيهــا ولــن أعيدهــا لــه‪.‬‬\n‫رابع ـ ًا ‪ :‬أمــا مــا ذكــر مــن الســاعتني الرجاليــة فقــد ســلمها املدعــي‬\n‫ألخــي ‪ ...‬هديــة منــه ألبــي وأخــي وقــد قبضاهــا وإذا كان لــه دعــوى‬\n‫بهــا فليقمهــا عليهمــا وال شــأن لــي يف هــذا ‪ ،‬وبعــرض جوابهــا علــى‬\n‫املدعــي أجــاب ‪ :‬لــم أختــل بهــا وكل لقــاء تكــون أمهــا موجــودة ســوى‬\n‫مــرة خرجــت معــي يف الســيارة إلــى الســوق ومــا ذكرتــه مــن قولــي إن‬\n‫معظــم األطقــم ألهلــي فأقصــد أن األطقــم منــي ولكــن املبلــغ املشــترى‬\n‫بــه منــه مــا أعطتنــي إيــاه أمــي ومنــه مــا أعطتنــي إيــاه أختــي ومــا ذكرتــه‬\n‫مــن كونــه هديــه زوج لزوجتــه فليــس بصحيــح ومــا ذكرتــه مــن كــون‬\n‫الســاعتني الرجاليــة التــي ســلمت واحــدة ألخيهــا ‪ .......‬فهــذا صحيــح‬\n‫واألخــرى ســلمتها مــن ضمــن مجموعــة ولــم أســلمها ألبيهــا ولكنهمــا‬\n‫ليســا علــى ســبيل الهديــة وإمنــا الصحيــح إننــي أتيــت بــكل ذلــك تلبيــة‬\n‫لطلبهــا أن تراهــا قبــل موعدهــا وبســؤاله عــن بينتــه بــأن ماقدمــه ممــا‬\n‫ادعــى بــه علــى نيــة الرجــوع بــه بعــد مشــاهدته فقــط أجــاب ليــس لــدي‬\n‫بينــة ولكــن العــرف يقتضــي مــا ذكرته يف دعــواي ولذا قررت الكتابة‬\n‫لقســم اخلبــراء لإلفــادة عمــا لديهــم مــن العــرف اجلــاري والســائد يف مثــل‬\n‫هــذه احلالــة وقــد وردنــا خطــاب قســم اخلبــراء رقــم ‪ 33840163‬وتاريــخ‬\n‫‪1433/11/14‬ه ـ ونــص احلاجــة منــه (نفيدكــم أن العــرف الســائد بــن‬\n‫النــاس أنــه إذا قــدم الرجــل ملخطوبتــه هديــة بــدون شــرط مــن املــرأة أو‬\n‫مــن أهلهــا فإنهــا يف هــذه احلالــة تعتبــر هديــة ‪ ،‬هــذا هــو العــرف الســائد‬\n\n\n                                                                                         ‫‪270‬‬\n\f      ‫بــن النــاس حســب علمنــا خاصــة وأنــه قدمــه لهــا قبــل الــزواج وهــذا‬\n      ‫دليــل علــى أنــه قدمــه ترغيب ـ ًا لهــا يف قبــول الــزواج هــذا مــا ظهــر لنــا‬\n      ‫واهلل املوفــق) وبعــد تالوتــه عليهمــا قــرر املدعــي ‪ :‬أنــا لــم أقدمــه هديــة ‪،‬‬\n      ‫أفهمــت املدعــي بأنــه ليــس لــه إال ميــن املدعــى عليهــا إن طلبهــا ‪ ،‬فطلبهــا‬\n      ‫فأفهمــت املدعــى عليــه وكالــة بإحضــار موكلتــه ألداء اليمــن ففهــم‪،‬‬\n      ‫ويف يــوم الثالثــاء املوافــق‪ 1434/04/09‬هـ افتتحت اجللســة وفيها حضر‬\n      ‫املدعــي وانتهــى الوقــت احملــدد ولــم حتضــر املدعــى عليهــا ألداء اليمــن‬\n      ‫رغــم تبلغهــا عــن طريــق وكيلهــا حســب النظــام ‪ ،‬لــذا أمــرت بتبليــغ‬\n      ‫املدعــى عليهــا حلضــور يــوم الثالثــاء املوافــق ‪1434/4/23‬ه ـ الســاعة‬\n      ‫ال ‪،‬ويف يــوم الثالثــاء‬  ‫الواحــدة ظهــر ًا ألداء اليمــن وإال تعتبــر نــاك ً‬\n      ‫املوافــق ‪1434/4/23‬ه ـ افتتحــت اجللســة الســاعة الواحــدة ظهــر ًا وفيهــا‬\n      ‫حضــرت املدعــى عليهــا ‪ .......‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ .......‬ووكيلهــا املــدون هويتــه ســابق ًا ولــم يحضــر املدعــي رغــم‬\n      ‫معرفتــه باملوعــد ومت عــرض اليمــن عليهــا بعــد تخويفهــا بــاهلل تعالــى‬\n      ‫مــن مغبــة اليمــن الغمــوس فاســتعدت ثــم حلفــت قائلــة ‪ :‬واهلل العظيــم أن‬\n      ‫كل مــا قدمــه لــي مــن أطقــم الذهــب كان هديــة وهــو قدمــه دون طلــب‬\n      ‫منــي وأنــه ليــس بنيــة االرجــاع وال شــرط هــذا وأننــي قلــت لــه الهديــة‬\n      ‫كثيــرة فقــال تســتاهلني أكثــر واهلل علــى مــا أقــول شــهيد هكــذا‬\n      ‫حلفــت ‪ ،‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلنــكار املدعــى‬\n      ‫عليهــا وعــدم بينــة املدعــي وألداء املدعــى عليهــا اليمــن كمــا طلبــت‬\n      ‫منهــا ولقولــه صلــى اهلل عليــه وســلم ( البينــة علــى املدعــي واليمــن علــى‬\n      ‫مــن أنكــر ) وللقاعــدة الفقهيــة ‪ :‬العــادة محكمــة فقــد صرفــت النظــر‬\n      ‫عــن دعــوى املدعــي وأخليــت ســبيل املدعــى عليهــا مــن هــذه الدعــوى هــذا‬\n\n\n‫‪271‬‬\n\f‫مــا ظهــر لــي وبــه حكمــت وقنعــت بــه املدعيــة وقــررت بعــث نســخة مــن‬\n‫احلكــم للمدعــي لتقــدمي اعتراضــه خــال املــدة النظاميــة ويف حــال عــدم‬\n‫تقــدمي اعتراضــه يكتســب احلكــم الصفــة القطعيــة ‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ :‬فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫وبرفقهــا القــرار رقــم ‪ 34240178‬وتاريــخ ‪1434/6/13‬ه ـ املظهــر علــى‬\n‫صــك احلكــم رقــم (‪ )34198975‬وتاريــخ ‪1434/4/27‬ه ـ «ونــص‬\n‫احلاجــة منــه « وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫تقــرر املوافقــة علــى احلكــم واهلل املوفــق ‪ ،‬قاضــي اســتئناف ‪ .......‬ختمــه‬\n‫وتوقيعــه‪ ،‬قاضــي اســتئناف ‪ .......‬ختمــه وتوقيعــه رئيــس الدائــرة قاضــي‬\n‫اســتئناف ‪ .......‬ختمــه وتوقيعــه ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                              ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/07/02‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n‫األولــى لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع‬\n‫علــى املعاملــة الــواردة إلينــا شــفع خطــاب فضيلة رئيــس احملكمة العامة‬\n‫باملدينــة املنــورة املســاعد رقــم ‪ 33/840163‬وتاريــخ ‪1434/5/20‬ه ـ‬\n‫املشــتملة علــى الصــك رقــم ‪ 34198975‬وتاريــخ ‪1434/4/27‬ه ـ الصــادر‬\n‫مــن فضيلــة الشــيخ ‪ .......‬القاضــي باحملكمــة العامــة باملدينــة املنــورة‬\n‫املتضمــن دعــوى ‪ .......‬ضــد ‪ .......‬يف قضيــة زوجيــة وبدراســة الصــك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر املوافقــة علــى احلكــم واهلل‬\n         ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                   ‫‪272‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":265,"source_page_end":272,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"afc937c867ebd9a11e1334b05722e99445bcc49e555ac82f2d17e679b2f6a614","normalized_text_hash":"12750761c4a98d579878ba1fc053458ed69434a5e3e084010978b7e14e1ccbbe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p265-34198975"},{"id":"badb8b84-be9e-59b2-bdff-6423ebf891f5","document_type":"judgment","category":"judicial","subcategory":"general","title":"هبة -رجوع عن هبة إلنفكاك عرى الزوجية -تكييف تسليم مبالغ على أنها هبة -حكم بإخاء سبيل املدعى عليها -تضارب أقوال املدعي أصالة مع أقوال املدعي وكالة قرينة على عدم الصحة .","document_number":"34260389","case_number":"33677765","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ببريدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/5","year":"1434","subject":"هبة -رجوع عن هبة إلنفكاك عرى الزوجية -تكييف تسليم مبالغ على أنها هبة -حكم بإخاء سبيل املدعى عليها -تضارب أقوال املدعي أصالة مع أقوال املدعي وكالة قرينة على عدم الصحة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34260389 :‬تاريخه ‪1434/7/5:‬هـ‬\n                        ‫رقم الدعوى ‪33677765 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34316441‬تاريخه ‪1434/9/10 :‬هـ‬\n\n\n      ‫هبــة ‪ -‬رجــوع عــن هبــة إلنفــكاك عــرى الزوجيــة ‪ -‬تكييــف تســليم مبالــغ‬\n      ‫علــى أنهــا هبــة ‪ -‬حكــم بإخــاء ســبيل املدعــى عليهــا ‪ -‬تضــارب أقــوال‬\n         ‫املدعــي أصالــة مــع أقــوال املدعــي وكالــة قرينــة علــى عــدم الصحــة ‪.‬‬\n\n\n\n\n      ‫عــن ابــن عبــاس رضــى اهلل عنهمــا ان رســول اهلل صلــى اهلل عليــه وســلم‬\n                   ‫قــال «العائــد يف هبتــه كالعائــد يف قيئــه» رواه البخــاري‬\n\n\n\n\n      ‫دعــوى املدعــى وكالــة ضــد املدعــى عليــه وكالــة ومضمــون الدعــوى أن‬\n      ‫املدعــى أصالــة كان زوجــا للمدعــى عليهــا أصالــة وعندمــا كانــت يف‬\n      ‫ذمتــه خرجــت مــن املنــزل دون علــم الــزوج وفــى حوزتهــا مبلغــا ماليـ ًا قــدره‬\n      ‫أربعــة وعشــرون ألــف ريــال عهــدة مصــروف لــم يســتخدم ومبلغــا قــدره‬\n      ‫عشــرون ألــف ريــال مت حتويلــه حلســاب املدعــى عليهــا لغــرض تعاقــد مــع‬\n      ‫خادمــة منزليــة كمــا أنهــا تصرفــت يف مبلــغ قــدره خمســة عشــر ألــف‬\n      ‫ريــال واملدعــى عليهــا لــم تعــد زوجــة للمدعــى أصالــة وطالــب املدعــى‬\n      ‫وكالــة احلكــم علــى املدعــى عليهــا بــرد املبالــغ املصروفــة واحملولــة‬\n      ‫لهــا وقدرهــا كاملــة تســعة وخمســون ألــف ريــال ‪ -‬أجــاب املدعــى عليــه‬\n      ‫وكالــة بــأن املبالــغ املاليــة املشــار إليهــا يف الدعــوى منهــا مــا مت حتويلــه‬\n\n‫‪273‬‬\n\f‫لغــرض النفقــة علــى ابنــه مــدة ســنة ونصــف ســنة ومنهــا مــا مت حتويلــه‬\n‫إرضــاء لزوجــة املدعــى أصالــة عنــد رجوعهــا إليــه ومنهــا مــا مت حتويلــه‬\n‫عنــد قيــام العالقــة الزوجيــة مبحــض إرادتــه مــن بــاب التــودد لزوجتــه‬\n‫بالهديــة ولكــن عندمــا حصــل الفــراق بــن املدعــي أصالــة واملدعــى‬\n‫عليهــا أصالــة طالــب بهــذه املبالــغ ‪ -‬حضــر املدعــى أصالــة وأقــر لــدى‬\n‫ناظــر القضيــة بأنــه دفــع هــذه املبالــغ للمدعــى عليهــا وانــه دفــع لهــا أيضا‬\n‫مبالــغ كثيــرة مــن أجــل ترغيبهــا بالبقــاء عنــده ‪ -‬قــرر ناظــر القضيــة انــه‬\n‫بنــاء علــى إقــرار املدعــى أصالــة بأنــه أعطــى املدعــى عليهــا أصالــة هــذه‬\n‫املبالــغ مــن اجــل ترغيبهــا بالبقــاء عنــده وفــى بيتــه فقــد ظهــر لــه بــان‬\n‫املدعــى أصالــة أعطــى املدعــى عليهــا هــذه املبالــغ هبــة ولقولــه صلــى‬\n‫اهلل عليــه وســلم ((العائــد يف هبتــه كالعائــد يف قيئــه)) لــذا فقــد صــدر‬\n‫احلكــم بصــرف النظــر عــن دعــوى املدعــى ‪ -‬قــرر املدعــى وكالــة عــدم‬\n‫القناعــة ‪ -‬صــدر قــرار محكمــة االســتئناف باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة العامــة‬\n‫ببريــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة ببريــدة برقــم ‪ 33677765‬وتاريــخ ‪ 1433/11/27‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 332122900‬وتاريــخ ‪ 1433/11/27‬ه ـ ففــي‬\n‫يــوم األحــد املوافــق‪ 1433/12/19‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n‫‪ 09‬وفيهــا حضــر ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫بالوكالــة عــن ‪ .......‬مدعيـ ًا علــى احلاضــر معــه يف مجلــس القضــاء ‪.......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم حــال كونــه وكيــا عــن‬\n\n                                                                                        ‫‪274‬‬\n\f      ‫‪ .......‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل بريــدة الثانيــة برقــم‬\n      ‫يف ‪1433/7/19‬ه ـ املخــول لــه فيهــا حــق املطالبــة واملخاصمــة واملدافعــة‬\n      ‫واملرافعــة وإقامــة الدعــاوى وحتريرهــا والــرد عليهــا وتقــدمي الالئحــة‬\n      ‫االعتراضيــة وإقامــة البينــة والدفــع وقبــول احلكــم ونفيــه واالعتــراض‬\n      ‫عليــه وطلــب متييــزه والصلــح قائــا يف دعــواه حيــث أن زوجــة موكلــي‬\n      ‫خرجــت مــن املنــزل دون علمــه وأثنــاء تواجــده يف مدينــة الريــاض ويف‬\n      ‫حوزتهــا مبلــغ وقــدره أربعــة وعشــرون ألــف ريــال عهــدة مصــروف لــم‬\n      ‫يســتخدم ومبلــغ عشــرون ألــف ريــال حتويــل يف حســابها لشــراء عقــد‬\n      ‫خادمــة ومجمــوع املبالــغ املطالــب بهــا هــي أربعــة وأربعــون ألــف ريــال‬\n      ‫إضافــة أنهــا تصرفــت يف مبلــغ خمســة عشــر ألــف ريــال يف ثالثــة أيــام‬\n      ‫أطلــب إلزامهــا بــرد املبالــغ املاليــة املذكــورة وقدرهــا تســعة وخمســون‬\n      ‫ألــف ريــال هــذه دعــواي ‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة‬\n      ‫أجــاب بقولــه مــا ذكــره املدعــي وكالــة مــن حيــث حتويــل املبالغ حلســاب‬\n      ‫موكلتــي فهــذا صحيــح ولكــن األربــع وعشــرين ألــف ريــال التــي ذكــر‬\n      ‫بأنهــا عهــدة هــي مصــروف البنــه مــن موكلتــي لســنة ونصــف وبالنســبة‬\n      ‫للعشــرين ألــف ريــال فهــي ليســت لشــراء عقــد خادمــة والواقــع أن موكل‬\n      ‫املدعــي دفعهــا رضــوة ملوكلتــي عنــد رجعتــه إليهــا واخلمســة عشــر ألــف‬\n      ‫ريــال حولهــا بحســابها عنــد قيــام العالقــة الزوجيــة مبحــض إرادتــه وهــي‬\n      ‫لــم جتبــره عليهــا وإمنــا حولهــا مــن بــاب التــودد لهــا بالهديــة وعندمــا حصل‬\n      ‫بينهمــا الفــراق أراد أن يســتعيد هــذه املبالــغ وموكلتــي ليــس لديهــا‬\n      ‫اســتعداد بــأن تدفــع لــه شــيء هــذه إجابتــي وبعــرض ذلــك علــى املدعــي‬\n      ‫وكالــة أجــاب بقولــه إن موكلــي قــد دفــع املبالــغ ملوكلــة املدعــي‬\n      ‫ولكنهــا لــم متكــث عنــده إال فتــرة وجيــزة ثــم طالبــت بالفســخ هكــذا‬\n\n\n‫‪275‬‬\n\f‫أجــاب وللتأمــل رفعــت اجللســة ثــم يف يوم األحــد املوافق‪1434/03/01‬هـ‬\n‫حضــر املدعــي أصالـ ًة ‪ .......‬ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم‬\n‫‪ .......‬وحضــر حلضــوره املدعــى عليــه وكالــة وبتــاوة مــا مت ضبطــه علــى‬\n‫املدعــي أصالــة أجــاب بقولــه جميــع مــا ذكــره وكيلــي صحيــح مــا‬\n‫عــدا مبلــغ اخلمســة عشــر ألــف ريــال فــان صحــة املبلــغ هــو عشــرة آالف‬\n‫وســبعمائة ريــال ألنــه اتضــح لــي أن مبلــغ أربعــة آالف وثالثمائــة ريــال‬\n‫مت صرفهــا مــن قبلــي علمـ ًا بــان املدعــى عليهــا أخــذت بطاقــة الصــراف‬\n‫بإذنــي وصرفــت املبلــغ املذكــور ولــم أكــن أتوقــع أن تصــرف هــذا‬\n‫املبلــغ هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب‬\n‫بقولــه انــه ظهــر تناقــض يف دعــوى املدعــي وكالــة واملدعــي أصالــة‬\n‫بخصــوص املبلــغ اخلمســة عشــر ألــف ريــال وأود أن أوضــح بــان املبلــغ‬\n‫األربعــة وعشــن ألــف ريــال قــد صرفتــه موكلتــي علــى ابــن املدعــي ملــدة‬\n‫ســنه وســتة أشــهر والعشــرين ألــف ريــال التــي يذكــر بأنهــا مقابــل شــراء‬\n‫عقــد اخلادمــة فاخلادمــة أساســا كانــت موجــودة عنــد موكلتــي وقــد‬\n‫أعطاهــا هــذا املبلــغ مــن اجــل هــذه اخلادمــة وبهــذا فــان املدعــي قــد دفــع‬\n‫ملوكلتــي هــذه املبالــغ بطوعــه واختيــاره وليــس لــدى موكلتــي اســتعداد‬\n‫بــأن تعيــد لــه شــيء كمــا أســلفت هكــذا أجــاب وبعــرض ذلــك علــى‬\n‫املدعــي أصالــة أجــاب بقولــه إننــي دفعــت هــذه املبالــغ ملوكلــة املدعــى‬\n‫عليــه ودفعــت لهــا أيضــا مبالــغ كثيــرة ال ارغــب يف املطالبــة بهــا مــن‬\n‫اجــل ترغيــب موكلــة املدعــى عليــه بالبقــاء عنــدي ويف بيتــي هكــذا‬\n‫أجــاب والنتهــاء الوقــت احملــدد للجلســة فقــد جــرى رفعهــا ثــم يف يــوم‬\n‫األحــد املوافــق‪ 1434/07/02‬ه ـ حضــر ‪ ......‬ســعودي مبوجــب الســجل‬\n‫املدنــي رقــم بالوكالــة عــن املدعــي الصــادرة مــن كتابــة عــدل بريــدة‬\n\n\n                                                                                       ‫‪276‬‬\n\f      ‫الثانيــة برقــم ‪ 34749295‬وتاريــخ ‪1434/06/12‬ه ـ واملخــول لــه فيهــا‬\n      ‫حــق املطالبــة وإقامــة الدعــاوى ‪ -‬املرافعــة واملدافعــة ‪ -‬ســماع الدعــاوى‬\n      ‫والــرد عليهــا ‪ -‬اإلنــكار ‪ -‬اإلقــرار ‪-‬الصلــح ‪ -‬التنــازل‪ -‬احضــار الشــهود‬\n      ‫والبينــات والطعــن فيهــا ‪ -‬االجابــة واجلــرح والتعديــل ‪ -‬الطعــن بالتزويــر‪-‬‬\n      ‫قبــول األحــكام ونفيهــا ‪ -‬االعتــراض علــى األحــكام وطلب االســتئناف‬\n      ‫‪ -‬التمــاس إعــادة النظــر ‪-‬طلــب رد االعتبــار وحضــر حلضــوره ســعودي‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .......‬بالوكالــة عــن املدعى عليهــا الصادرة‬\n      ‫مــن كتابــة عــدل بريــدة الثانيــة برقــم ‪ 34550210‬وتاريــخ ‪1434/5/1‬هـ‬\n      ‫واملخــول لــه فيهــا حــق املطالبــة وإقامــة الدعــاوى ‪ -‬املرافعــة واملدافعــة‬\n      ‫‪ -‬ســماع الدعــاوى والــرد عليهــا ‪ -‬احضــار الشــهود والبينــات والطعــن‬\n      ‫فيهــا ‪ -‬طلــب املنــع مــن الســفر ورفعــه ‪ -‬طلــب احلجــز والتنفيــذ ‪ -‬املطالبــة‬\n      ‫بتنفيــذ األحــكام ‪ -‬االعتــراض علــى األحــكام وطلــب االســتئناف ‪-‬‬\n      ‫التمــاس إعــادة النظــر ‪-‬طلــب رد االعتبــار وبعــد أن جــرى تأمــل القضيــة‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــي أصالــة‬‫فبنـ ً‬\n      ‫يف اجللســة املنعقــدة بتاريــخ ‪1434/3/1‬ه ـ بأنــه أعطاهــا هــذه املبالــغ مــن‬\n      ‫أجــل ترغيبهــا بالبقــاء عنــده ويف بيتــه والــذي يظهــر لــي بــأن املدعــي‬\n      ‫أعطــى املدعــى عليهــا هــذه املبالــغ هبــة ولقــول الرســول صلــى اهلل‬\n      ‫عليــه وســلم عــن ابــن عبــاس (العائــد يف هبتــه كالعائــد يف قيئــه ) رواه‬\n      ‫البخــاري بجميــع مــا تقــدم فقــد صرفــت النظــر عــن دعــوى املدعــي‬\n      ‫وأخليــت ســبيل املدعــى عليهــا مــن دعــوى املدعــي هــذا مــا ظهــر لــي وبــه‬\n      ‫حكمــت وبعــرض ذلــك علــى وكيــل املدعــي قــرر عــدم القناعــة وطلــب‬\n      ‫تســليمه صــورة مــن احلكــم وإمهالــه لالعتــراض فأجبتــه لطلبــه وأفهمتــه‬\n      ‫مبراجعــة احملكمــة يف يــوم األربعــاء املوافــق ‪1434/7/5‬ه ـ وأنه يف حال‬\n\n\n‫‪277‬‬\n\f‫تأخــره ســوف يتــم إيــداع الصــك يف املعاملــة واحتســاب مــدة تأخــره مــن‬\n‫مــدة االعتــراض ففهــم ذلــك كمــا قــرر املدعــى عليــه وكالــة القناعــة‬\n‫وعليــه جــرى التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/07/02‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n‫بتدقيــق قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة ببريــدة برقــم (‪ )332122900‬وتاريــخ ‪1434/8/14‬هــ؛ املقيــدة‬\n‫لــدى احملكمــة برقــم (‪ )342014078‬وتاريــخ ‪1434/8/21‬هــ؛ اخلاصــة‬\n‫بدعــوى‪ ........ /‬الوكيــل عــن ‪ ........ /‬ضــد ‪ ........ /‬الوكيــل عــن ‪........ /‬‬\n‫؛ بشــأن املطالبــة مببلــغ مالــي قــدره تســعة وخمســون ألــف ريــال؛ املنتهيــة‬\n‫بالصــك الصــادر مــن فضيلــة الشــيخ‪ /‬القاضــي باحملكمــة؛ املســجل‬\n‫برقــم (‪ )34260389‬وتاريــخ ‪1434/7/5‬هــ؛ املتضمــن حكــم فضيلتــه‬\n‫بصــرف النظــر عــن دعــوى املدعــي؛ علــى النحــو املفصــل فيــه‪ .‬وبدراســة‬\n‫الصــك وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى ماحكــم‬\n‫بــه فضيلتــه‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                            ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪278‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":273,"source_page_end":278,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"66f26719bc55f11e34b9dc988f83ba7dabc2b091b32574d7b8293e9cfc6f19fc","normalized_text_hash":"a2a7197469dec167611397b1de739fee4e81de15019a3d981e5911f547973695","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p273-34260389"},{"id":"4d9c1e9d-2fe5-5351-bd16-1ecd0a8ef657","document_type":"judgment","category":"judicial","subcategory":"general","title":"هبة -مطالبة بإعادة عقار -مطالبة زوج بإعادة هبة من زوجته بعد حدوث شقاق -شهادة األبناء يف دعوى بن الوالدين -حلف مين - الهبة لسبب تثبت بثبوته وتزول بزواله -احلكم على الزوجة بإعادة العقار لزوجها .","document_number":"34259015","case_number":"34187285","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/ 4","year":"1434","subject":"هبة -مطالبة بإعادة عقار -مطالبة زوج بإعادة هبة من زوجته بعد حدوث شقاق -شهادة األبناء يف دعوى بن الوالدين -حلف مين - الهبة لسبب تثبت بثبوته وتزول بزواله -احلكم على الزوجة بإعادة العقار لزوجها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34259015 :‬تاريخه ‪1434/7/ 4 :‬هـ‬\n                         ‫رقم الدعوى ‪34187285 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34340866‬تاريخه ‪1434/10/26 :‬هـ‬\n\n\n      ‫هبــة ‪ -‬مطالبــة بإعــادة عقــار ‪ -‬مطالبــة زوج بإعــادة هبــة مــن زوجتــه بعــد‬\n      ‫حــدوث شــقاق ‪ -‬شــهادة األبنــاء يف دعــوى بــن الوالديــن ‪ -‬حلــف ميــن ‪-‬‬\n      ‫الهبــة لســبب تثبــت بثبوتــه وتــزول بزوالــه ‪ -‬احلكــم علــى الزوجــة بإعــادة‬\n                                                                     ‫العقــار لزوجها ‪.‬‬\n\n\n\n\n      ‫مــا قــرره شــيخ اإلســام بــن تيميــه بقولــه ( وقــد كتبــت عــن اإلمــام‬\n      ‫احمــد فيمــا إذا أهــدى لهــا هديــة بعــد العقــد فإنهــا تــرد ذلــك إليــه إذا‬\n      ‫زال العقــد الفاســد فهــذا يقتضــي إمنــا وهبــه لهــا بســبب النــكاح فانــه‬\n      ‫يبطــل إذا زال النــكاح وهــذا املنصــوص جــار علــى أصــول املذهــب املوافــق‬\n      ‫ألصــول الشــريعة وهــو أن كل مــن اهــدي لــه شــيء أو وهــب لــه شــيء‬\n                     ‫بســبب يثبــت بثبوتــه ويــزول بزوالــه) االختيــارات صــ‪.232‬‬\n\n\n\n\n      ‫أدعــى الــزوج ضــد املدعــى عليهــا الزوجــة مــن أنــه قــام بكتابــة منزلــه‬\n      ‫الكائــن يف حــي ‪ .....‬واملبــن موقعــه ورقــم ســند امللكيــة يف نص الضبط‬\n      ‫ـاء لهــا بعــد ذهابهــا لبيــت أهلهــا يف‬\n                                             ‫باســم زوجتــه املدعــى عليهــا إرضـ ً‬\n      ‫مكــة ثــم عــادت وبعــد فتــرة قامــت بإخــراج املدعــي مــن املنــزل ومنعــه‬\n      ‫مــن الدخــول فيــه وأقامــت دعــوى تطلــب الطــاق وطلــب املدعــي إعــادة‬\n\n‫‪279‬‬\n\f‫البيــت إلــى ملكــه ‪ -‬أجابــت املدعــى عليهــا أن املدعــي كتــب البيــت‬\n‫باســمها مقابــل وعــد قــدمي بــأن يجعــل البيــت باســمها مكافــأة لهــا وال‬\n‫صحــة ملــا ذكــره املدعــي يف دعــواه ‪ -‬أحضــر املدعــي بينــه وهــم ولــدي‬\n‫طــريف القضيــة شــهدا علــى صحــة دعــوى املدعــي ‪ -‬قــرر املدعــي أنــه‬\n‫منــح زوجتــه البيــت رغبــة يف اســتدامة عقــد الــزواج ‪ -‬حلــف املدعــي علــى‬\n‫صحــة دعــواه بعــد عــرض اليمــن عليــه مــن ناظــر القضيــة ‪ -‬قــرر ناظــر‬\n‫ـاء علــى شــهادة الشــهود مــن أن الهبــة ألجــل عــودة الزوجــة‬  ‫القضيــة بنـ ً‬\n‫وإنهــاء الفرقــة وبــذل املدعــي اليمــن علــى صحــة دعــواه ووجــود قضيــة‬\n‫فســخ نــكاح ولعظــم الشــقاق بينهمــا ومــا هو مقرر عنــد الفقهاء أن كل‬\n‫مــن أهــدي لــه شــيء بســبب يثبــت بثبوتــه و يــزول بزوالــه ‪ -‬فقــد صــدر‬\n‫احلكــم بإعــادة البيــت إلــى املدعــي ‪ -‬قــررت املدعــى عليهــا عــدم القناعــة‬\n‫‪ -‬صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة باملصادقــة علــى‬\n                                                                        ‫احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 34187285‬وتاريــخ ‪ 1434/04/23‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34999694‬وتاريــخ ‪ 1434/04/23‬ه ـ ففــي يــوم‬\n‫األحــد املوافــق‪ 1434/05/26‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n‫عشــرة صباحــا وفيهــا حضــر املدعــي ‪ /‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم وحضــر حلضــوره املدعــى عليهــا ‪ /‬زوجتــه ســعودية‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم وبســؤال املدعــي عــن دعــواه‬\n\n                                                                                     ‫‪280‬‬\n\f      ‫ادعــى قائــا اننــي قمــت بكتابــة منزلــي الكائــن يف حــي ‪ .......‬خلــف‬\n      ‫‪ .......‬املكــون مــن دوريــن وملحــق اململــوك بالصــك رقــم ‪2/7/367/96‬‬\n      ‫وتاريــخ ‪1433/6/11‬ه ـ باســم زوجتــي وذلــك إرضاء لهــا بعد ذهابها الى‬\n      ‫بيــت اهلهــا يف مكــة ثــم عــادت بعــد ذلــك وبعــد فتــرة قامــت بإخراجــي‬\n      ‫مــن املنــزل ومنعــي مــن دخولــه واقامــت دعــوى تطلــب فيهــا الطــاق‬\n      ‫واشــتكتني لــدى الشــرطة اطلــب اعــادة البيــت الــى ملكــي حيــث اننــي‬\n      ‫منحتهــا ايــاه رغبــة يف اســتدامة الــزواج هــذه دعــواي وبعــرض ذلــك علــى‬\n      ‫املدعــى عليهــا اجابــت بقولهــا ماذكــره املدعــي غيــر صحيــح والصحيــح‬\n      ‫انــه قــام بكتابــة املنــزل باســمي وذلــك مقابــل وعــد قــدمي وعدنــي ايــاه أن‬\n      ‫يجعــل البيــت األخيــر باســمي مكافــأة لــي بعــد تفريطــه وبيعــه ألكثــر‬\n      ‫مــن عقــار واســكاننا يف شــقق مفروشــة فتــرة مــن الزمــن ولــم يجعلــه‬\n      ‫مقابــل عودتــي اليــه مــن بيــت اهلــي او رضــوة هكــذا اجابــت وبســؤال‬\n      ‫املدعــي عــن بينتــه أحضــر كال مــن ‪ /‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم و‪ /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وهــم ابنــاء‬\n      ‫الطرفــن طــاب يف التعليــم العالــي ويســكنون يف حــي ‪.......‬مــع والدتهــم‬\n      ‫ومــن مواليــد ‪ 1413‬األول والثانــي مــن مواليــد ‪1415‬ه ـ وبســؤالهم عــن‬\n      ‫مــا لديهــم مــن شــهادة شــهد االول بقولــه اشــهد هلل تعالــى ان والــدي‬\n      ‫قــد وعــد أمــي بــأن يكتــب البيــت باســمها كمــا انــه بعــد ان ذهبــت‬\n      ‫والدتــي الــى اهلهــا يف مكــة بعــد مشــاكل بينهمــا اتصلــت بــه وطلبــت‬\n      ‫منــه احلضــور الــى منــزل اخوالــي وكان دون رضــا والدتــي ومت االجتمــاع‬\n      ‫يف منــزل اخوالــي واتفقــوا علــى ان تعــود معــه الــى منزلــه مقابــل أن‬\n      ‫يكتــب املنــزل باســمها هــذا مــا لــدي مــن شــهادة كمــا شــهد الثانــي‬\n      ‫مبثــل مــا شــهد بــه االول وقــرر ان االتصــال كان مــن قبــل اخيــه هكــذا‬\n\n\n‫‪281‬‬\n\f‫شــهدوا وبعــرض ذلــك علــى املدعــى عليهــا قالــت مــا ذكــره الشــهود‬\n‫صحيــح جملــة وتفصيــا هكــذا أجابــت كمــا قــرر املدعــي بقولــه ان‬\n‫ابنــي اتصــل بــي وقــال ان والدتــي تريــد التفاهــم معــك لــذا احضــر الينــا‬\n‫يف مكــة هكــذا قــرر وبــرد ذلــك علــى الشــاهد قــال انــا مــن ذكــر‬\n‫ذلــك هكــذا قــرر وعنــد وصــول القضيــة الــى هــذا احلــد قــررت رفــع‬\n‫اجللســة للتأمــل ثــم انــه يف يــوم اإلثنــن املوافــق‪ 1434/07/03‬ه ـ افتتحت‬\n‫اجللســة الســاعة الثامنــة والنصــف صباحــا وفيهــا حضــر الطرفــان وجــرى‬\n‫ســؤال املدعــي عــن ســبب منحــه املنــزل للمــرأة فأجــاب بقولــه اننــي‬\n‫منحتهــا ايــاه رغبــة يف اســتدامة الــزواج وعودتهــا الــى بيــت الزوجيــة بعــد‬\n‫خــاف بيننــا كمــا انهــا بعــد ان قمــت بكتابــة املنــزل قامــت بطــردي‬\n‫ومحاولــة فســخ نكاحهــا منــي والقضيــة منظــورة لــدى فضيلــة الشــيخ‬\n‫‪.......‬هكــذا اجــاب وبــرد ذلــك علــى املــرأة احلاضــرة اجابــت بقولهــا‬\n‫اننــي ســبق وان ذكــرت ان ذلــك غيــر صحيــح وامنــا قــام مبنحــي البيــت‬\n‫مقابــل وعــده لــي هكــذا اجابــت ثــم جــرى عــرض اليمــن علــى املدعــي‬\n‫فاســتعد ببذلهــا بعــد ان اذنــت لــه قائــا واهلل العلــي العظيــم الــذي ال‬\n‫الــه اال هــو عالــم الغيــب والشــهادة اننــي كتبــت البيــت باســم زوجتــي‬\n‫مقابــل عودتهــا الــى منزلــي ورغبــة باســتدامة احليــاة الزوجيــة ثــم قامــت‬\n‫بطــردي منــه دون ســبب واهلل العلــي العظيــم هكــذا حلــف وبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واالجابــة وحيــث احضــر املدعــي ابنائــه للشــهادة‬\n‫وقنعــت بهــم املدعــى عليهــا وملــا ذكــره الشــهود مــن ان الهبــة كانــت‬\n‫ألجــل عــودة املــرأة الــى بيــت زوجهــا وانهــاء للفرقــة وحيــث بــذل املدعــي‬\n‫اليمــن علــى صحــة دعــواه وملــا قــرره الطرفــان مــن وجــود قضيــة فســخ‬\n‫نــكاح منظــورة ولعظــم الشــقاق بينهمــا وملــا قــرره شــيخ االســام ابــن‬\n\n\n                                                                                     ‫‪282‬‬\n\f      ‫تيميــه بقولــه (وقــد كتبــت عــن االمــام احمــد فيمــا اذا اهــدي لهــا هديــة‬\n      ‫بعــد العقــد فإنهــا تــرد ذلــك اليــه اذا زال العقــد الفاســد فهــذا يقتضــي امنا‬\n      ‫وهبــه لهــا بســبب النــكاح فانــه يبطــل اذا زال النــكاح وهــذا املنصــوص‬\n      ‫جــار علــى اصــول املذهــب املوافقــة ألصــول الشــريعة وهــو ان كل مــن‬\n      ‫اهــدي لــه شــيء او وهــب لــه شــيء بســبب يثبــت بثبوتــه ويــزول بزوالــه)‬\n      ‫االختيــارات ص‪ 232‬كمــا نــص عليــه يف املنــار ويف املطالــب لذلــك كلــه‬\n      ‫فقــد حكمــت بإعــادة البيــت الــى املدعــي وبعرضــه عليهمــا قنــع املدعــي‬\n      ‫ولــم تقنــع املدعــى عليهــا فجــرى افهمهــا بــأن لهــا حــق االعتــراض وذلــك‬\n      ‫بطلــب االســتئناف وذلــك بتقــدمي الئحــة اعتراضيــة خــال ثالثــون يومــا‬\n      ‫مــن تاريــخ اســتالم احلكــم وان مضــت املــدة دون تقــدمي الئحــة اكتســب‬\n      ‫احلكــم القطعيــة وســقط حقهــا باالعتــراض ثــم جــرى افهامهــا بــأن‬\n      ‫عليهــا مراجعــة احملكمــة يــوم غــدا الثالثــاء الســتالم احلكــم وابتــداء‬\n      ‫املهلــة ففهمــت ذلــك وختمــت اجللســة الســاعة التاســعة صباحــا وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                               ‫يف ‪ 1434/07/03‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم ‪34/999694‬‬\n      ‫وتاريــخ ‪1434/10/19‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫القاضــي باحملكمــة العامــة بالطائــف واملســجل بعــدد ‪34259015‬‬\n      ‫وتاريــخ ‪1434/7/4‬هـ ـ واملتضمــن دعــوى‪ ........ /‬ضــد‪ ........ /‬واحملكــوم‬\n      ‫فيــه مبــا دون باطنــه‪ .‬وبدراســة احلكــم وصــورة ضبطــه والالئحــة‬\n\n\n‫‪283‬‬\n\f‫االعتراضيــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق‪ .‬وصلــى اهلل‬\n                          ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                               ‫‪284‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":279,"source_page_end":284,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0780ccfbe8f3bb70808ff3b14d683c80e9d0ae66392134cbf639c8fc2fc96cbe","normalized_text_hash":"9a3219d491c1a2b03cf90f2164a86aaf33f9a593b4c1279e5a43fd4988b3fd39","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p279-34259015"},{"id":"e54f7e02-ddd8-5ee0-8bf6-3a3d0cc0bf84","document_type":"judgment","category":"judicial","subcategory":"general","title":"هبة -قسمة تركة -مطالبة املدعي ببيع عقار مورثه وتسليمه نصيبه الشرعي -ثبوت انتقال ملكية العقار محل الدعوى ألحد أبناء املورث هبة لعلة وإعاقة -جواز تخصيص األب بالعطية بعض األوالد ملعنى يقتضى تخصيصه -ثبوت العطية ملن وهبت له من الورثة بعد الوفاة دون الرجوع -رد الدعوى .","document_number":"34265813","case_number":"33619017","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/6","year":"1434","subject":"هبة -قسمة تركة -مطالبة املدعي ببيع عقار مورثه وتسليمه نصيبه الشرعي -ثبوت انتقال ملكية العقار محل الدعوى ألحد أبناء املورث هبة لعلة وإعاقة -جواز تخصيص األب بالعطية بعض األوالد ملعنى يقتضى تخصيصه -ثبوت العطية ملن وهبت له من الورثة بعد الوفاة دون الرجوع -رد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34265813 :‬تاريخه‪1434/11/6 :‬هـ‬\n                         ‫رقم الدعوى‪33619017 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34371693‬تاريخه‪1434/11/26 :‬هـ‬\n\n\n      ‫هبــة ‪ -‬قســمة تركــة ‪ -‬مطالبــة املدعــي ببيــع عقــار مورثــه وتســليمه‬\n      ‫نصيبــه الشــرعي ‪ -‬ثبــوت انتقــال ملكيــة العقــار محــل الدعــوى ألحــد‬\n      ‫أبنــاء املــورث هبــة لعلــة وإعاقــة ‪ -‬جــواز تخصيــص األب بالعطيــة بعــض‬\n      ‫األوالد ملعنــى يقتضــى تخصيصــه ‪ -‬ثبــوت العطيــة ملــن وهبــت لــه مــن‬\n                                 ‫الورثــة بعــد الوفــاة دون الرجــوع ‪ -‬رد الدعــوى ‪.‬‬\n\n\n\n      ‫‪ .1‬مــا قــرره الفقهــاء مــن جــواز تخصيــص األب بعــض األوالد ملعنــى‬\n      ‫يقتضــي تخصيصــه مثــل اختصاصــه بحاجــة أو زمانــه أو عمــى أو‬\n      ‫كثــرة عائلــة أو اشــتغاله بالعلــم أو نحــوه مــن الفضائــل أو صــرف‬\n      ‫عطيتــه عــن بعــض ولــده لفســقه أو بدعتــه أو لكونــه يســتعني مبــا‬\n      ‫يأخــذه علــى معصيــة اهلل أو ينفقــه فيهــا (ينظــر املغنــي ج‪ 8/‬ص ‪.)258‬‬\n      ‫‪ .2‬جــاء يف املغنــي ج‪ 270-269/8‬مســألة‪ :‬قــال (فــإن مــات ولــم يــردده فقــد‬\n      ‫ثبــت ملــن وهــب لــه إذا كان ذلــك يف صحتــه) يعنــي إذا فاضــل بــن ولــده‬\n      ‫يف العطايــا أو خــص بعضهــم بعطيــة ثــم مــات قبــل أن يســترده ثبــت‬\n                   ‫ذلــك للموهــوب لــه ولــزم وليــس لبقيــة الورثــة الرجــوع أ‪.‬ه ـ‬\n      ‫‪ .3‬جــاء يف حاشــية الــروض املربــع شــرح زاد املســتقنع ج‪ 6/‬ص ‪( 18‬فــإن‬\n      ‫مــات الواهــب قبلــه أي قبــل الرجــوع أو الزيــادة ثبتــت للمعطــي فليــس‬\n                                                           ‫لبقيــة الورثــة الرجــوع)‪.‬‬\n\n\n‫‪285‬‬\n\f‫ادعــى املدعــي ضــد املدعــى عليــه بــأن مورثــه ومــورث املدعــى عليــه‬\n‫والدهــم قــد تــويف وخلــف العقــار الكائــن بالشــامية بــرأس جبــل القــرن‬\n‫واململــوك مبوجــب الصــك الصــادر مــن كتابــة العــدل وأن العقــار‬\n‫املذكــور ســيزال لصالــح توســعة الســاحات الشــمالية للحــرم املكــي‬\n‫الشــريف وصــك العقــار لــدى املدعــى عليــه ويطلــب احلكــم ببيــع العقــار‬\n‫املذكــور وتســليمه نصيبــه الشــرعي منــه وإلــزام املدعــى عليــه بتســليمه‬\n‫الصــك اخلــاص بالعقــار محــل الدعــوى هكــذا ادعــى ‪ -‬أجــاب املدعــى‬\n‫عليــه باملصادقــة علــى وفــاة مورثهــم وأمــا مــا ذكــره املدعــي مــن أن‬\n‫مورثهــم قــد خلــف العقــار املذكــور يف الدعــوى فغيــر صحيــح والصحيــح‬\n‫ـاء واململوكــة بهــذا‬ ‫أن مورثهــم قــد تنــازل عــن كامــل الــدار أرض ـ ًا وبنـ ً‬\n‫الصــك ألخيــه الشــقيق ‪ ...‬لوجــه اهلل تعالــى لكونــه معاقـ ًا ومعتوهـ ًا وهــو‬\n‫ولــي علــى ‪ ....‬املذكــور وذلــك مبوجــب صــك الواليــة الصــادر مــن هــذه‬\n‫احملكمــة ويطلــب احلكــم بصــرف النظــر عــن دعــوى املدعــي هكــذا‬\n‫أجــاب ‪ -‬صــادق املدعــي علــى إعاقــة أخيــه وعتهــه ونفــى علمــه بتنــازل‬\n‫مورثهــم عــن العقــار وأن املدعــى عليــه ولــي علــى أخيــه ‪ -‬أبــرز املدعــى‬\n‫عليــه صــك العقــار ومهمــش عليــه بالتنــازل ‪ -‬جــرى االستفســار عــن صــك‬\n‫العقــار وصــك الواليــة مــن مصــدره فــورد اجلــواب مبطابقتهمــا لســجلهما‬\n‫وســريان مفعولهمــا ‪ -‬لدفــع املدعــى عليــه واليــة بــأن العقــار ليــس ملــك ًا‬\n‫للمــورث وأنــه ملــك ملــن حتــت واليتــه وأن والــده قــد تنــازل لــه قبــل موتــه‬\n‫لكونــه معاق ـ ًا ومعتوه ـ ًا ‪ -‬وإلقــرار املدعــي بعــدم علمــه مبــا ذكــره‬\n‫املدعــى عليــه واليــة وألن عــدم علــم املدعــي ليــس لــه أثــر يف ذلــك ملــا‬\n\n                                                                                        ‫‪286‬‬\n\f      ‫قــرره الفقهــاء مــن جــواز تخصيــص األب بعــض األوالد ملعنــى يقتضــي‬\n      ‫تخصيصــه مثــل اختصاصــه بحاجــة أو زمانــه ‪( ..‬ينظــر املغنــي ‪/‬ج‪8/‬‬\n      ‫ص ‪ )258‬وكذلــك ملــا قــرره أهــل العلــم مــن ثبــوت الهبــة ملــن وهبــت لــه‬\n      ‫بعــد مــوت األب ينظــر املغنــي (ج‪ 8/‬ص ‪269‬ـ ‪ )270‬وحاشــية الــروض‬\n      ‫املربــع (ج‪ 6/‬ص ‪ - )18‬ملــا تقــدم حكمــت احملكمــة بصــرف النظــر عــن‬\n      ‫طلــب املدعــي وإفهامــه بأنــه ال يســتحق مــا جــاء يف دعــواه ‪ -‬قنــع املدعــى‬\n      ‫عليــه باحلكــم واعتــرض املدعــي بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة‬\n            ‫احلقوقيــة الثانيــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القاضــي يف احملكمــة‬\n      ‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33619017‬وتاريــخ‬\n      ‫‪1433/10/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331873260‬وتاريــخ‬\n      ‫‪1433/10/23‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/02/26‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر ‪.........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪.........‬وادعــى علــى احلاضــر معــه ‪.........‬ي‬\n      ‫ا يف دعــواه لقد‬       ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.........‬قائـ ً‬\n      ‫تــويف مورثــي ومــورث املدعــى عليــه والدنــا ‪.........‬بتاريــخ ‪1424/5/16‬ه ـ‬\n      ‫وانحصــر إرثــه يف أبنائــه مــن زوجــة متوفــاة قبلــه ‪......... ......... .........‬ويف‬\n      ‫زوجته ‪.........‬ويف أبنائه منها‪......... ......... ......... ......... ......... ......... .........‬‬\n      ‫البالغــن و‪.........‬القاصــر عقلي ـ ًا أه ـ وقــد خلــف مورثنــا العقــار الكائــن‬\n      ‫بالشــامية بــرأس جبــل القــرن واململــوك مبوجــب الصــك الصــادر مــن‬\n\n‫‪287‬‬\n\f‫كتابــة العــدل األولــى مبكــة برقــم ‪ 13/67‬يف ‪1420/5/28‬ه ـ والعقــار‬\n‫املذكــور ســيزال لصالــح توســعة الســاحات الشــمالية للحــرم املكــي‬\n‫الشــريف وصــك العقــار لــدى املدعــى عليــه فلذلــك فأنــا أطلــب احلكــم‬\n‫ببيــع العقــار املذكــور وتســليمي نصيبــي الشــرعي منــه وإلــزام املدعــى‬\n‫عليــه بتســليمي الصــك اخلــاص بالعقــار محــل الدعــوى هــذه دعــواي‬\n‫ا مــا ذكــره املدعــي‬    ‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائ ـ ً‬\n‫مــن وفــاة مورثنــا بالتاريــخ املذكــور وإنحصــار ارثــه باملذكوريــن يف‬\n‫دعــواه فهــذا صحيــح وأمــا مــا ذكــره املدعــي مــن أن مورثنــا قــد خلــف‬\n‫العقــار املذكــور يف الدعــوى فهــذا غيــر صحيــح والصحيــح أن مورثنــا‬\n‫ـاء واململوكــة بهــذا الصــك ألخــي‬    ‫قــد تنــازل عــن كامــل الــدار أرضـ ًا وبنـ ً‬\n‫الشــقيق ‪.........‬لوجــه اهلل تعالــى وبــدون ثمــن لكونــه معاق ـ ًا ومعتوه ـ ًا‬\n‫وأنــا ولــي علــى ‪.........‬املذكــور وذلــك مبوجــب صــك الواليــة الصــادر مــن‬\n‫هــذه احملكمــة برقــم ‪ 13/1/122‬يف ‪1424/6/15‬ه ـ وأطلــب احلكــم‬\n‫بصــرف النظــر عــن دعــوى املدعــي هكــذا أجــاب وبعــرض ذلــك علــى‬\n‫ا مــا ذكــره املدعــى عليــه مــن كــون أخــي ‪.........‬معاقـ ًا‬   ‫املدعــي قــرر قائـ ً‬\n‫ومعتوه ـ ًا فهــذا صحيــح وأمــا ا ذكــره املدعــى عليــه مــن كونــه ولي ـ ًا‬\n‫عليــه ومــن تنــازل مورثــي عــن العقــار محــل الدعــوى ‪ ....‬فهــذا ال علــم‬\n‫لــي بــه هكــذا قــرر وقــد جــرى االطــاع علــى الصــك محــل الدعــوى‬\n‫فوجدتــه صــادر ًا مــن كتابــة العــدل األولــى مبكــة املكرمــة برقــم‬\n‫‪ 13/67‬يف ‪1420/5/28‬ه ـ ويتضمــن تنــازل مــورث املدعــن علــي بــن‬\n‫‪.........‬لكامــل الــدار أرض ـ ًا وبنــاء البنــه ‪.........‬بــدون ثمــن لوجــه اهلل‬\n‫ا ال علــم لــي بهــذا الصــك‬    ‫تعالــى أه ـ وبعرضــه علــى املدعــي قــرر قائ ـ ً‬\n‫هكــذا قــرر وقــد ســبقت الكتابــة منــا لكتابــة العــدل األولــى بخطابنــا‬\n\n\n                                                                                           ‫‪288‬‬\n\f      ‫رقــم ‪ 332007478‬يف ‪1433/11/14‬ه ـ وذلــك لالستفســار عــن العقــار‬\n      ‫محــل الدعــوى منهــم اجلــواب رقــم ‪ 332058549‬يف ‪1433/11/24‬ه ـ‬\n      ‫واملتضمــن مطابقــة الصــك لســجله وســريان مفعولــه حتــى تاريخــه أه ـ‬\n      ‫ولالستفســار عــن صــك الواليــة وتأمــل القضيــة فقــد رفعــت اجللســة‬\n      ‫ويف يــوم الســبت املوافــق‪ 1434/07/08‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫وفيهــا حضــر املدعــي أصالــة حــال حضــور املدعــى عليــه واليــة وقــد‬\n      ‫ســبقت الكتابــة منــا ملديــر الســجالت بهــذه احملكمــة بخطابنــا رقــم‬\n                                                     ‫‪ 34492862‬يف ‪1434/2/26‬ه ـ‬\n      ‫فوردنــا اجلــواب منه شــرح ًا على خطابنــا بتاريخ ‪1434/3/1‬هـ واملتضمن‬\n      ‫مطابقة الصك لســجله وســريان مفعوله حتى تاريخه أهـ وقد جرى مني‬\n      ‫االطــاع علــى صــك حصــر ورثــة مــورث املدعــي واملدعــى عليــه ووجدتــه‬\n      ‫مطابــق ملــا جــاء يف الدعــوى وبســؤال الطرفــن هــل لديكمــا مــا تريــدان‬\n      ‫إضافتــه فأجابــا بالنفــي فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫ومبــا أن املدعــي يطلــب احلكــم ببيــع العقــار املذكــور يف الدعــوى بنــاء‬\n      ‫علــى أنــه ملــك ملورثــه والــده ‪.........‬وتســليمه نصيبــه الشــرعي منــه وإلــزام‬\n      ‫املدعــى عليــه بتســليمه صــك امللكيــة اخلــاص بالعقــار ولدفــع املدعــى‬\n      ‫عليــه واليــة بــأن العقــار ليــس ملــك ًا للمــورث وأنــه ملــك ملــن حتــت واليتــه‬\n      ‫وهــو أخــاه الشــقيق ‪.........‬وأن والــده قــد تنــازل لــه قبــل موتــه لكونــه‬\n      ‫معاق ـ ًا ومعتوه ـ ًا وبعــد االطــاع علــى صــك امللكيــة واملتضمــن انتقــال‬\n      ‫ملكيــة العقــار محــل الدعــوى مــن ملــك مــورث املدعــي إلــى أحــد الورثــة‬\n      ‫‪.........‬بتاريــخ ‪1420/5/28‬ه ـ وحيــث جــرى االستفســار عــن ســجل‬\n      ‫الصــك وورد اجلــواب مبطابقــة الصــك لســجله وســريان مفعولــه وعــدم‬\n      ‫وجــود مــا يخــل بــه وإلقــرار املدعــي بعــدم علمــه مبــا ذكــره املدعــى عليــه‬\n\n\n‫‪289‬‬\n\f‫واليــة وألن عــدم علــم املدعــي ليــس لــه أثــر يف ذلــك وملــا قــرره الفقهــاء‬\n‫رحمهــم اهلل تعالــى مــن جــواز تخصيص األب بعض األوالد ملعنى يقتضي‬\n‫تخصيصــه مثــل اختصاصــه بحاجــة أو زمانــه أو عمــى أو كثــرة عائلــة‬\n‫أو اشــتغاله بالعلــم أو نحــوه مــن الفضائــل أو صــرف عطيتــه عــن بعــض‬\n‫ولــده لفســقه أو بدعتــه أو لكونــه يســتعني مبــا يأخــذه علــى معصيــة اهلل‬\n‫أو ينفقــه فيهــا (ينظــر املغنــي ‪/‬ج‪ 8/‬ص ‪ )258‬وكذلــك ملــا قــرره أهــل‬\n‫العلــم رحمهــم اهلل مــن ثبــوت الهبــة ملــن وهبــت لــه بعــد مــوت األب قــال‬\n‫ابــن قدامــه رحمــه اهلل يف املغنــي مســألة ‪ :‬قــال (فــإن مــات ولــم يــردده‬\n‫فقــد ثبــت ملــن وهــب ولــه إذا كان ذلــك يف صحتــه ) يعنــي إذا فاضــل‬\n‫بــن ولــده يف العطايــا أو خــص بعضهــم بعطيــة ثــم مــات قبــل أن يســترده‬\n‫ثبــت ذلــك للموهــوب لــه ولــزم وليــس لبقيــة الورثــة الرجــوع أه ـ املغنــي‬\n‫(ج‪ 8/‬ص ‪ 269‬ـ ‪)270‬وقال يف حاشــية الروض املربع شــرح زاد املســتقنع‬\n‫(ج‪ 6/‬ص ‪ )18‬فــإن مــات الواهــب قبلــه أي قبــل الرجــوع أو الزيــادة ثبتــت‬\n‫للمعطــي فليــس لبقيــة الورثــة الرجــوع ) لذلــك فقــد صرفــت النظــر عــن‬\n‫طلــب املدعــي وأفهمتــه بأنــه ال يســتحق مــا جــاء يف دعــواه وأخليــت ســبيل‬\n‫املدعــى عليــه منهــا وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن‬\n‫قــرر املدعــى عليــه واليــة القناعــة بذلــك أمــا املدعــي فقــد قــرر عــدم‬\n‫القناعــة ويطلــب االســتئناف بالئحــة اعتراضيــة فأجيــب لطلبــه و وأفهــم‬\n‫أن عليــه مراجعــة احملكمــة يف يــوم الســبت املوافــق ‪1434/7/15‬ه ـ‬\n‫الســتالم نســخة مــن احلكــم وإبــداء معارضتــه عليــه كمــا أفهمتــه أن‬\n‫مــدة االعتــراض ثالثــون يومـ ًا مــن هــذا التاريــخ وأنــه إن لــم يعدهــا خاللها‬\n‫فــإن حقــه يف االعتــراض يكــون ســاقط ًا ويكتســب احلكــم القطعيــة‬\n‫ففهــم ذلــك ‪ ..‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n                                                                                       ‫‪290‬‬\n\f                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/07/08‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/10/21‬ه ـ‬\n      ‫افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف برقــم‬\n      ‫‪ 331873260‬يف ‪1434/9/23‬ه ـ وبرفقهــا القــرار رقــم ‪ 34321703‬يف‬\n      ‫‪1434/9/17‬ه ـ ونــص احلاجــة منــه ‪ :‬وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن‬\n      ‫املدعــي ذكــر أن املدعــى عليــه وإخوتــه قــد حتايلــوا علــى والــده وإقناعــه‬\n      ‫بالتنــازل ألخيهــم املذكــور فعلــى فضيلتــه فتــح جلســة للطرفني ومســائلة‬\n      ‫املدعــي عــن هــذا التحايــل وكيفيتــه ومناقشــتهما عــن حــال والدهمــا‬\n      ‫حــن التنــازل وصحتــه وهــل كان يعانــي مــن مــرض وإن كان فمــا هــو‬\n      ‫املــرض الــذي يعانــي منــه وهــل لــه أمــاك غيــر هــذا البيــت واســتجالء‬\n      ‫حقيقــة هــذه الهبــة بــراء ًة للذمــة أه ـ فعليــه أجيــب أصحــاب الفضيلــة بــأن‬\n      ‫العقــار محــل الدعــوى مت إفراغــه للمدعــى عليــه واليــة وليــس للمدعــى‬\n      ‫عليــه أصالــة وذلــك لــدى كاتــب العــدل بتاريــخ ‪1420/5/28‬ه ـ واألصــل‬\n      ‫يف الصكــوك الصــادرة مــن كتابــة العــدل صحتهــا وســامتها وقبولهــا‬\n      ‫وعــدم الطعــن فيهــا وال يتــم إفــراغ العقــار إال بعــد نظــر كاتــب العــدل يف‬\n      ‫حالــة البائــع أو الواهــب املعتبــرة شــرع ًا وإذا كان البائــع أو الواهــب غيــر‬\n      ‫مؤهــل لذلــك فلــن يتــم إجــراء اإلفــراغ كمــا أن مــورث الطرفــن قــد تويف‬\n      ‫يف ‪1424/5/16‬ه ـ واملــدة بــن اإلفــراغ والوفــاة ليســت قريبــة وإذا كان‬\n      ‫املدعــي يطعــن بالصــك أو اإلفــراغ فعليــه التقــدم لــدى اجلهــات املختصــة‬\n      ‫للتحقيــق يف موضــوع اإلفــراغ مــن شــخص فاقــد األهليــة وعنــد ثبــوت‬\n      ‫ذلــك لــدى اجلهــات املختصــة فيتــم التهميــش علــى صــك امللكيــة بذلــك‬\n      ‫وعليــه فإنــه لــم يظهــر لــي خــاف مــا حكمــت بــه وأمــرت بضبــط ذلــك‬\n\n\n‫‪291‬‬\n\f‫واحلاقــه بصكــه وســجله وإعــادة كامــل أوراق املعاملــة إلــى محكمــة‬\n‫االســتئناف حســب املتبــع وبــاهلل التوفيــق ‪ ..‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/10/21‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 331873260‬وتاريــخ‬\n‫‪1434/11/6‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪.........‬‬\n‫باحملكمــة العامــة مبكــة املكرمــة برقــم ‪ 34265813‬وتاريــخ‬\n‫‪1434/7/11‬ه ـ املتضمــن دعــوى ‪.........‬ضــد ‪ ،.........‬وبدراســة الصــك‬\n‫وصــورة ضبطــه الئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n‫احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى‬\n                                   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪292‬‬\n\f293\n\f294\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":285,"source_page_end":294,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"213b187b04c13e00276ef5281286219e77c0e0983fcecaeebaaaa130ce83fe99","normalized_text_hash":"5e59641007cc9087cdd2d4ebb6f6e1eece7da5dfb53d5b19094fd9c2a84b9398","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p285-34265813"},{"id":"e5da3568-8293-5b81-a374-0de33c8e2d70","document_type":"judgment","category":"judicial","subcategory":"general","title":"تركة -إدعاء صورية عقد متلك أرض -حترير صك التملك باسم اإلبن لكون األب غير سعودي -رفض املدعي مين املدعى عليه -شهادة منقوصة -دليل غير موصل -بقاء حق املدعى يف اليمن النافية ولو بعد احلكم.","document_number":"33358233","case_number":"3374028","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/27","year":"1434","subject":"تركة -إدعاء صورية عقد متلك أرض -حترير صك التملك باسم اإلبن لكون األب غير سعودي -رفض املدعي مين املدعى عليه -شهادة منقوصة -دليل غير موصل -بقاء حق املدعى يف اليمن النافية ولو بعد احلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33358233 :‬تاريخه‪1433/7/27 :‬هـ‬\n                          ‫رقم الدعوى‪3374028 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34230712‬تاريخه‪1434/6/5 :‬هـ‬\n\n\n      ‫تركــة ‪ -‬إدعــاء صوريــة عقــد متلــك أرض ‪ -‬حتريــر صــك التملــك‬\n      ‫باســم اإلبــن لكــون األب غيــر ســعودي ‪ -‬رفــض املدعــي ميــن املدعــى‬\n      ‫عليــه ‪ -‬شــهادة منقوصــة ‪ -‬دليــل غيــر موصــل ‪ -‬بقــاء حــق املدعــى يف‬\n                                            ‫اليمــن النافيــة ولــو بعــد احلكــم‪.‬‬\n\n\n\n      ‫قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى مــن‬\n                                                                           ‫أنكــر)‪.‬‬\n\n\n\n      ‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه بأنــه قــد تــويف مــورث موكليــه‬\n      ‫ومــورث املدعــى عليــه والدهــم وخلــف مــن ضمــن تركتــه النصــف مــن‬\n      ‫املزرعــة الواقعــة بالفــرش ضواحــي ينبــع البحــر ومملوكــة بصــك صــادر‬\n      ‫مــن محكمــة ينبــع ومســجله باســم ابنــه املدعــى عليــه لكونــه ســعودي ًا‬\n      ‫ويطلــب احلكــم ببيعهــا وتســليم موكليــه نصيبهــم هكــذا ادعــى‪،‬‬\n      ‫أجــاب املدعــى عليــه باملصادقــة علــى ملكيتــه لــأرض وأنكــر أنهــا‬\n      ‫لوالــده‪ ،‬بينــة املدعــي شــاهد شــهد بــأن مــورث املدعــن واملدعــى عليــه‬\n      ‫أخبــره بشــراء أرض يف ينبــع ولــم يخبــره عــن مكانهــا أو تفاصيــل أخــرى‬\n      ‫وليــس للمدعــي بينــة أخــرى فجــرى إفهامــه بــأن لــه ميــن املدعــى عليــه‬\n      ‫فلــم يقبل‪،‬مبــا أن املدعــي ال بينــة لديــه موصلــة ولقولــه صلــى اهلل عليــه‬\n\n‫‪295‬‬\n\f‫وســلم (البينــة علــى املدعــي واليمــن علــى مــن أنكــر) تقــدر احلكــم‬\n‫بــرد الدعــوى وإفهــام املدعــي وكالــة بــأن ملوكليــه ميــن املدعــى عليــه‬\n‫متــى مــا طلبوهــا‪ ،‬قنــع املدعــى عليــه باحلكــم واعتــرض املدعــي وكالــة‬\n‫بالئحة‪،‬صــدق احلكــم مــن محكمــة االســتئناف مبنطقــة مكــة‬\n                                                                 ‫املكرمــة ‪.‬‬\n\n\n\n‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد فلدي أنا ‪...‬‬\n‫القاضــي يف احملكمــة العامــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة باملدينــة املنورة برقــم ‪3374028‬‬\n‫وتاريــخ ‪1433/01/29‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33193029‬وتاريــخ‬\n‫‪1433/01/29‬ه ـ ففــي يــوم األحــد املوافق‪1433/03/20‬ه ـ حضــر ‪...‬‬\n‫ا عــن نفســه‬‫ســعودي بالســجل املدنــي ‪ ...‬الوكيــل عــن ‪ ...‬بصفتــه أصيـ ً‬\n‫ا عــن ‪ ، ...‬و‪ ، ...‬و‪ ، ...‬و‪ ، ...‬و‪ ، ...‬و‪ ، ...‬و‪ ، ...‬و‪ ، ...‬و‪،...‬‬        ‫ووكي ـ ً‬\n‫و‪ ......‬ووكالــة احلاضــر رقمهــا ‪ 11179‬يف‪1433/02/13‬ه ـ صــادرة‬\n‫مــن كتابــة العــدل الثانيــة باملدينــة املنــورة ‪ ،‬وعــن ‪ ...‬بصفتــه ووكيــا‬\n‫عــن‪ ...‬ووكالــة احلاضــر رقمهــا ‪ 29032‬يف ‪1433/04/24‬ه ـ صــادرة مــن‬\n‫كتابــة العــدل الثانيــة باملدينــة املنــورة وجميــع مــن ُذكــر مــن املدعــن‬\n‫أصالــة واملدعــى عليــه هــم مــن انحصــر إرث ‪ ...‬فيهــم مبوجــب الصــك‬\n‫الصــادر مــن هــذه احملكمــة برقــم ‪ 3262012‬يف ‪ 1432 /4/3‬ه ـ وادعى‬\n‫علــى احلاضــر معــه ‪ ...‬ســعودي بالســجل املدنــي رقــم ‪ ...‬قائــا ‪ :‬لقــد‬\n‫ٌتــويف مــورث موكلــي ومــورث املدعــى عليــه والدهــم وخلــف مــن ضمــن‬\n‫تركتــه النصــف مــن املزرعــة الواقعــة ‪ ...‬ضواحــي ينبــع البحــر احملــدودة‬\n\n                                                                                       ‫‪296‬‬\n\f      ‫شــماال وجنوبــا بالصمــد وشــرقا ملــك ‪ ...‬والبعــض الصمــد وغربــا ملــك ‪...‬‬\n      ‫والبعــض الصمــد واململوكــة بالصــك رقــم ‪ 366‬والصــادر مــن محكمــة‬\n      ‫ينبــع وقــد ســجله باســم ابنــه املدعــى عليــه لكونــه ســعوديا أطلــب‬\n      ‫احلكــم ببيعهــا وتســليم موكلــي مــا يخصهــم هــذه دعــواي ‪ .‬وبســؤال‬\n      ‫املدعــى عليــه ‪ ،‬أجــاب قائــا ‪ :‬مــا ذكــره املدعــي وكالــة مــن أن املزرعــة‬\n      ‫املذكــورة باســمي صحيــح وهــي ملــك لــي ولــي شــريكني فيهــا وهمــا ‪...‬‬\n      ‫و‪ ...‬وهــي بيننــا بالســوية وليــس لوالــدي ملــك فيهــا ‪ ،‬ثــم ســألت املدعــي‬\n      ‫وكالــة ‪ :‬هــل لديــه بينــة ؟ قــال نعــم ثــم احضــر للشــهادة ‪ ...‬مينــي اجلنســية‬\n      ‫ا بــأن والــد احلاضــر ‪ ...‬قــد زارنــي‬      ‫مبوجــب اإلقامــة رقــم ‪ ...‬وشــهد قائ ـ ً‬\n      ‫يف جــدة وقلــت لــه مــا تركــت شــيئا ألوالدك قــال عنــدي خيــر واشــتريت‬\n      ‫أرض يف ينبــع ولــم يخبرنــي عــن مكانهــا أو أي تفاصيــل أخــرى هــذا‬\n      ‫مــا لــدي مــن شــهادة وبعــرض ذلــك علــى املدعــى عليــه قــال الشــاهد ال‬\n      ‫أقــول فيــه شــيئا وشــهادته غيــر صحيحــة ووالــدي أخطــأ عندمــا قــال‬\n      ‫ذلــك ؛ ثــم ســألت املدعــي وكالــة هــل لديــه زيــادة بينــة قــال ال فأفهمتــه‬\n      ‫أن لــه ميــن املدعــى عليــه قــال ال أرغــب يف ميينــه فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة وحيــث ال بينــة موصلــة للمدعــي وكالــة وقــد قــال‬\n      ‫كــر))‬  ‫ن َعلــى َمــنْ أ ْن َ‬\n                                   ‫واليمِ ـ ُ‬\n                                         ‫البي َنـ ُة َعلــى امل َُّدعــي َ‬\n                                                                       ‫صلــى اهلل عليــه وســلم (( َ‬\n      ‫لذلــك كلــه فقــد رددت دعــوى املدعــي وكالــة وأخليــت ســبيل املدعــى‬\n      ‫عليــه وبــه حكمــت وأفهمــت املدعــي وكالــة بــأن ملوكليــه ميــن املدعــى‬\n      ‫عليــه متــى مــا طلبوهــا وبعــرض ذلــك علــى الطرفــن قنــع بــه املدعــى عليــه‬\n      ‫ولــم يقنــع بــه املدعــي وكالــة فأفهــم مبقتضــى تعليمــات االســتئناف‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                          ‫أجمعــن ‪.‬‬\n\n\n‫‪297‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن ‪1434/06/19‬ه ـ وردتنــا‬\n‫املعاملــة مــن رئيــس محكمــة االســتئناف املكلــف مبكــة املكرمــة‬\n‫برقــم ‪ 3491069‬يف ‪1434/06/11‬ه ـ مرفقــا بهــا قــرار الدائــرة‬\n‫احلقوقيــة الرابعــة رقــم ‪ 34230712‬يف ‪1434/06/05‬ه ـ ونــص احلاجــة‬\n‫منــه (( وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت‬\n‫املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر املبنــي علــى قــرار الدائــرة‬\n‫رقــم ‪ 341284‬يف ‪1434/01/04‬ه ـ )) أ‪.‬ه ـ قاضــي اســتئناف د‪ ....‬ختمــه‬\n‫وتوقيعــه قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ ...‬ختمــه‬\n‫وتوقيعــه حتــى ال يخفــى جــرى إثباتــه ؛ وبــاهلل التوفيــق وصلــى اهلل علــى‬\n                                    ‫بنينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪298‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":295,"source_page_end":298,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"246f45c67bd411cd1f65359d4920f86bcb337f0149b097c1ff0a9d2dab695f59","normalized_text_hash":"3f60a949e31c06e85ce70ffb9203b1726767ccf141173978440d169b9973b985","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p295-33358233"},{"id":"c248b117-bf36-5082-b4f1-1d4793175f74","document_type":"judgment","category":"judicial","subcategory":"general","title":"قسمة تركة -وفاة مورث وترك تركة داخل وخارج اململكة -مطالبة املدعية أصالة عن نفسها ووكالة عن أخواتها بأخذ نصيبهم من التركة بعد خصم ما مت استالمه -ضعف البينة -حلف طريف اخلصومة اليمن على انكار استالمهم باقي اإلرث -نقل املورث بعض األماك إلى املدعى عليه كوصية -ال وصية لوارث -عدم اختصاص المحكمة بنظر الدعاوى املتعلقة بعقار خارج اململكة- إلزام املدعى عليه بدفع نصيب املدعيات ورد ما عدا ذلك من","document_number":"3448838","case_number":"3347353","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/12/26","year":"1434","subject":"قسمة تركة -وفاة مورث وترك تركة داخل وخارج اململكة -مطالبة املدعية أصالة عن نفسها ووكالة عن أخواتها بأخذ نصيبهم من التركة بعد خصم ما مت استالمه -ضعف البينة -حلف طريف اخلصومة اليمن على انكار استالمهم باقي اإلرث -نقل املورث بعض األماك إلى املدعى عليه كوصية -ال وصية لوارث -عدم اختصاص المحكمة بنظر الدعاوى املتعلقة بعقار خارج اململكة- إلزام املدعى عليه بدفع نصيب املدعيات ورد ما عدا ذلك من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪3448838 :‬تاريخه‪1434/12/26 :‬هـ‬\n                        ‫رقم الدعوى‪3347353 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪342508599‬تاريخه‪1434/6/25 :‬هـ‬\n\n\n      ‫قســمة تركــة‪ -‬وفــاة مــورث وتــرك تركــة داخل وخــارج اململكة‪ -‬مطالبة‬\n      ‫املدعيــة أصالــة عــن نفســها ووكالــة عــن أخواتهــا بأخــذ نصيبهــم مــن‬\n      ‫التركــة بعــد خصــم مــا مت اســتالمه‪ -‬ضعــف البينــة‪ -‬حلــف طــريف‬\n      ‫اخلصومــة اليمــن علــى انــكار اســتالمهم باقــي اإلرث‪ -‬نقــل املــورث‬\n      ‫بعــض األمــاك إلــى املدعــى عليــه كوصيــة‪ -‬ال وصيــة لــوارث‪ -‬عــدم‬\n      ‫اختصــاص احملكمــة بنظــر الدعــاوى املتعلقــة بعقــار خــارج اململكــة‪-‬‬\n      ‫إلــزام املدعــى عليــه بدفــع نصيــب املدعيــات ورد مــا عــدا ذلــك مــن‬\n                                                                       ‫طلبــات ‪.‬‬\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم (علــى اليــد مــا أخــذت حتــى تؤديــه) رواه‬\n                                                                            ‫األربعة‪.‬‬\n      ‫‪ .2‬ملــا روي (أن النبــي صلــى اهلل عليــه وســلم قضــى أن اليمــن علــى‬\n                                                   ‫املدعــى عليــه) رواه البخــاري‪.‬‬\n      ‫‪ .3‬قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى‬\n                                                   ‫املدعــى عليــه) رواه الترمــذي‪.‬‬\n           ‫‪ .4‬قوله صلى اهلل عليه وسلم (ال وصية لوارث) رواه اإلمام أحمد‪.‬‬\n                                       ‫‪ .5‬املادة ‪ 28‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n‫‪299‬‬\n\f‫أقامــت املدعيــة دعواهــا باألصالــة عــن نفســها وبالوكالــة عــن أخواتهــا‬\n‫قائلــة أن والدهــا تــويف وخلــف تركــة كبيــرة داخــل اململكــة العربيــة‬\n‫الســعودية وخارجهــا‪ ،‬وقــد اســتلمت وأخواتهــا بعــد الوفــاة مبالــغ تخــص‬\n‫مورثهــم مت توزيعهــا عليهــم‪ ،‬لــذا تطالــب بأخــذ نصيبهــا وأخواتهــا مــن‬\n‫التركــة بعــد خصــم مــا مت اســتالمه‪ ،‬مت نقــل ملكيــة بعــض العقــارات‬\n‫واملبالــغ إلــى املدعــى عليــه مبوجــب وصيــة‪ ،‬وقــد أنكــرت املدعيــة‬\n‫هــذه الوصيــة لبطالنهــا ملخالفتهــا احلديــث النبــوي الشــريف (ال وصيــة‬\n‫لــوارث) مت إفهــام الطرفــن أن الدعــاوى املتعلقــة بعقــار خــارج اململكــة‬\n‫ـاء علــى املــادة (‪ )28‬مــن‬\n                          ‫تخــرج عــن اختصــاص محاكــم اململكــة بنـ ً‬\n‫نظــام املرافعــات الشــرعية‪ ،‬بعــد املداولــة حكمــت احملكمــة بالقــدر‬\n‫املتيقــن وذلــك بقيــام املدعــى عليــه بدفــع مبالــغ معينــة للمدعيــات‬\n‫ورد مــا عــدا ذلــك مــن طلبــات لعــدم ثبوتهــا‪ ،‬قنعــت املدعيــة باحلكــم‬\n‫واعتــرض املدعــى عليهمــا بالئحــة‪ ،‬متــت مصادقــة احلكــم مــن محكمــة‬\n                                           ‫االســتئناف مبكــة املكرمــة‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 3347353‬وتاريــخ‬\n‫‪1433/01/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33122398‬وتاريــخ‬\n‫‪1433/01/18‬ه ـ ففــي يــوم الثالثــاء املوافق‪1433/02/16‬ه ـ افتتحــت‬\n\n                                                                                ‫‪300‬‬\n\f      ‫اجللســة الســاعة ‪ 08 : 17‬وفيهــا حضــرت ‪ .....‬لبنانيــة اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم ‪ .....‬واملعــرف بهــا مــن قبــل املدعــى عليهمــا ‪ ،‬وادعــت علــى‬\n      ‫احلاضرين معها ‪ .....‬لبناني اجلنسية مبوجب اإلقامة رقم ‪2028601983‬‬\n      ‫‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬قائلــة ‪ :‬لقــد تــويف‬\n      ‫والدي يف عام ‪1985‬م وخلف تركة ‪ ،‬منها ما كان باســم ‪ .....‬ســعودي‬\n      ‫اجلنســية باعهــا املدعــى عليــه ‪ .....‬واســتلم قيمتهــا ‪ ،‬ومنهــا ما كان باســم‬\n      ‫‪ .....‬ســعودية اجلنســية مت بيعهــا واســتلمت نصيبــي منهــا ‪ ،‬ومنهــا مــا كان‬\n      ‫باســم املدعــى عليــه ‪ .....‬بنــاء علــى إقــرار محــرر منــه بــأوراق الورشــة‬\n      ‫‪ ........................‬يتضمــن ‪ :‬أن جميــع األراضــي التــي باســمي وهــي برقــم‬\n      ‫‪ .....‬و ‪ .....‬مخطط ‪ ......‬والقطعة ‪ .....‬هي ملك والدي ‪ .....‬والورشة املباعة‬\n      ‫مــن الســيد ‪ .....‬هــي ملــك لوالــدي وإخوتــي بعــد مــوت والــدي وجميــع مــا‬\n      ‫فيهــم مــن بضاعــة وأغــراض بضاعــة وليــس لــي فيهــا أي شــيء اجلميــع‬\n      ‫باســمي فقــط وال أملــك مــن ذلــك شــيئا واجلميــع باســمي فقــط ‪ ،‬وموقــع‬\n      ‫مــن قبــل املقــر‪ ،‬وبشــهادة وتوقيــع‪ .....‬واملدعــى عليــه ‪ ، ....‬ومبلــغ ‪30‬‬\n      ‫ألــف ريــال هــي عبــارة عــن إبــراء ذمــة شــخص كان للمــورث مــال عنــده‬\n      ‫اســتلمتها وســلمت الورثــة مــن النســاء نصيبهــم فقــط ‪ ،‬ومبلــغ ‪ 100‬ألــف‬\n      ‫ريــال مت حتصيلهــا مــن ورثــة‪ .....‬ال أعلــم مــن اســتلمها ‪ ،‬ومبلــغ ‪ 60‬ألــف‬\n      ‫ريــال مت حتصيلهــا مــن‪ .....‬اســتلمها املدعــى عليــه علــي ‪ ،‬ومبلــغ ‪ 5‬آالف‬\n      ‫ريــال مت حتصيلهــا مــن‪ .....‬اســتلمها املدعــى عليــه علــي ‪ ،‬وبضاعــة عبــارة‬\n      ‫حديــد وأملونيــوم وإكسســوارات األملونيــوم وســيارات وعفــش البيــت‬\n      ‫والســكاكني وراعفــة شــوكية ‪ ،‬وأطلــب إلزامهمــا بتســليمي نصيبــي‬\n      ‫مــن هــذه التركــة‪ .‬هــذه دعــواي‪ .‬وبعــرض ذلــك علــى املدعــى عليهمــا‬\n      ‫قــاال‪ :‬نطلــب اإلمهــال للــرد‪ .‬وقــرر املدعــى عليــه قائــا ‪ :‬أمــا مــا يخــص‬\n\n\n‫‪301‬‬\n\f‫اإلقــرار املشــار إليــه ســابقا فإننــي مقــر مبــا فيــه ‪ .‬ثــم رفعت اجللســة لذلك‪.‬‬\n‫ويف يــوم الثالثــاء املوافــق‪ 1433/05/11‬ه ـ افتتحــت اجللســة الســاعة ‪30‬‬\n‫‪ 09 :‬وفيهــا حضــر املدعيــة واملدعــى عليهمــا واملعــرف باملدعيــة مــن قبــل‬\n‫املدعــى عليهمــا‪ ،‬وأبــرزت املدعيــة ســند توكيــل عــام صــادر مــن دائــرة‬\n‫الكاتبــة العــدل يف املينــاء باجلمهوريــة اللبنانيــة بعــدد ق ‪ 16‬لعــام ‪2012‬‬\n‫م واملصــادق عليــه مــن اجلمهوريــة اللبنانيــة قســم املصادقــات و املصــادق‬\n‫عليهــا مــن مكتــب التصديــق مــن وزارة العــدل واملتضمــن حضــور كال‬\n‫من ‪ ..... -1‬لبنانية اجلنســية مواليد عام ‪1977‬م رقم الســجل ‪ / .....‬حلبا‬\n‫عــكار بالبطاقــة رقــم ‪ .....‬تاريــخ ‪2009/12/1‬م باألصالــة عــن نفســها‬\n‫وبوكالتهــا العامــة القضائيــة عــن ‪ .....‬الــواردة مــن الســفارة اللبنانيــة‬\n‫برقــم ‪ 2009/1074‬تاريــخ ‪ 2009/8/4‬م واملصــادق عليهــا أصــوال مــن‬\n‫وزارة اخلارجيــة اللبنانيــة ‪/141392‬م تاريــخ ‪2009/8/12‬م وبوكالتهــا‬\n‫اخلاصــة عــن ‪ .....‬الــواردة مــن قنصليــة لبنــان الفخريــة يف تورنتــو ‪ /‬كنــدا‬\n‫برقــم عــام ‪ 2009/306‬رقــم خــاص ‪ 2009/284‬تاريــخ ‪2009/7/15‬م‬\n‫واملصــادق عليهــا أصــوال مــن وزارة اخلارجيــة اللبنانيــة رقــم ‪141393‬‬\n‫تاريــخ ‪2009/8/12‬م ‪ ..... -2‬لبنانيــة اجلنســية مواليــد عــام ‪1969‬م رقــم‬\n‫الســجل ‪/ .....‬حلبــا عــكار بالبطاقــة رقــم ‪ .....‬تاريــخ ‪1992/3/17‬م ‪،‬‬\n‫وقررتــا مبــا يلــي وكلنــا وفوضنــا شــقيقتنا باســمة ‪ .....‬املقيمــة يف جــدة‬\n‫اململكــة العربيــة الســعودية للمرافعــة واملدافعــة عنــا بــكل دعــوى لنــا‬\n‫أم علينــا مــع أي شــخص كان وبــأي صفــه كانــت ‪ ،‬مــع حــق الصلــح‬\n‫واالقــرار واالبــراء والرجــوع عــن احلــق او الدعــوى وقبــول الرجــوع‬\n‫واســترداد الرســوم والكفــاالت ‪ ،‬وقــدم املدعــى عليهمــا مذكــره هــذا‬\n‫نصهــا ‪ :‬ردا علــى الدعــوى املقامــة ضــدي مــن شــقيقتي ‪ .....‬وتدعــي بأنني‬\n\n\n                                                                                         ‫‪302‬‬\n\f      ‫قمــت بعــدم إعطائهــا ميــراث أبيهــا املغفــور لــه بــأذن اهلل ‪ .....‬املتوفــى‬\n      ‫مــن حوالــي تســعة وعشــرون عامــا ودفــن يف مســقط رأســه لبنــان وبعــد‬\n      ‫شــهرين مــن وفاتــه طلبــت مــن والدتــي ‪ ........‬وهــي بحمــد اهلل موجــودة‬\n      ‫تــرزق لكنهــا مريضــة مبــرض الزهيمــر ويف حالــة متقدمــة جــدا حســب‬\n      ‫التقريــر الطبــي مرفــق صورتــه لفضيلتكــم ؛ طلبــت منهــا أن يتــم الوضــع‬\n      ‫كمــا كان يف حالــة حيــاة والــدي ألننــي كنــت الســند والــذراع اليمنــى‬\n      ‫لوالــدي مــن بعــد اهلل يف إدارة إعمالــه وأموالــه حيــث أنهــم الورثــة كانــوا‬\n      ‫خمســة بنــات مقيمــن باململكــة وأخــي ‪ .....‬كان مقيــم بلبنــان وجميــع‬\n      ‫مراحــل دراســته بلبنــان وكنــت اعلــم بالــواردة والشــاردة والصغيــرة‬\n      ‫والكبيــرة ‪ ،‬فضيلــة القاضــي اقســم بــاهلل العظيــم إننــي كنــت اعمــل‬\n      ‫مــع والــدي منــذ كان عمــري عشــرة ســنوات كانــت إجازاتــي املدرســية‬\n      ‫ال اعرفهــا كلهــا اقضيهــا بالعمــل مــع الوالــد كان إخوتــي يســافرون‬\n      ‫مــع الوالــد والوالــدة خــارج اململكــة يف اإلجــازات والعطــات وأكــون‬\n      ‫إنــا بالعمــل وأول إجــازة أخذتهــا وســافرت خــارج اململكــة ألول مــره إلــى‬\n      ‫األمــارات العربيــة كان عمــري عشــرون عامــا وكانــت خمســة عشــر‬\n      ‫يومــا جلســت فيهــا عنــد شــقيقتي التــي تصغرنــي مقيمــة بأمــارة العــن‬\n      ‫‪ ،‬فضيلــة القاضــي عندمــا طلبــت مــن الوالــدة بعــد وفــاة الوالــد أن يتــم‬\n      ‫الوضــع كمــا كان يف حيــاة والــدي ألننــي كنــت متأكــد إن كل‬\n      ‫مــا بنــاه الوالــد رحمــة اهلل عليــه خــال حياتــه ســيدمر ويندثــر فرفضــت‬\n      ‫وقامــت بشــكوتي باحملكمــة الشــرعية الكبــرى مبنطقــة بــاب شــريف‬\n      ‫وتدخــل كبــار عائلــة الوالــدة منهــم مــن مــات ومنهــم مــا زال حــي يــرزق‬\n      ‫وقمــت مبحاســبة والدتــي لوجودهــا دون الورثــة بالســعودية مــا لوالــدي‬\n      ‫ومــا عليــه وســلمتها مــا كان بحوزتــي مــن مســتندات وأوراق تخــص‬\n\n\n‫‪303‬‬\n\f‫أعمــال الوالــد وأمــا بالنســبة إلــى أرض مخطــط اجلبيــري بجنــوب جــده‬\n‫منطقــة اخلمــره فهــم ثالثــة قطــع بصــك واحــد فقلــت لهــا إن والــدي‬\n‫أوصــى بهمــا لــي بعــد مماتــه ألننــي لــم يكتــب لــي أمــاكا كمــا كتــب‬\n‫ألخوتــي اخلمســة وأخــي ‪ .....‬يف لبنــان وأنتــي تعلمــن بوصيتــه ومبشــهد‬\n‫أخــي ‪ .....‬وزوجتــه علــى وصيــة والــدي وكذلــك رواتــب خمســة ســنوات‬\n‫عملــت بهــا عنــد والــدي مــن عــام ‪ 1400‬حتــى منتصــف عــام ‪ 1406‬مائــة‬\n‫وثمانــون إلــف ريــال فرفضــت فاتفقــت معهــا علــى إن قيمــة األرض قدرت‬\n‫عــام ‪ 1406‬مائتــان وخمســون إلــف ريــال تأخــذ الوالــدة ‪ .....‬ســند أمانــه‬\n‫علــى أختهــا ‪ .....‬باعتــراف ‪ .....‬وعلمهــا مببلــغ مائــة وخمســون إلــف ريــال‬\n‫وليــس كمامنهــم‪ ،‬إمــام فضيلتكــم ثالثمائــة إلــف ألن خالتــي مقيمــه‬\n‫بدولــة األردن وباقــي املبلــغ املائــة إلــف مــا تبقــى لــي وكل مــا أخذتــه مــن‬\n‫ارث أبــي والكــن دفعتهــا ديــن عــن إعمــال والــدي كنــت وقتهــا القائــم‬\n‫بأعمــال الوالــد مائــة وثمانــون إلــف ريــال ل‪ .....‬وقــد توفــى قبــل ســنتان‬\n‫وقــد أصــدر صــك شــرعي علــي عنــد فضيلــة القاضــي ‪ ، .....‬وكذلــك‬\n‫ســجنت ثالثــة شــهور ألن يف حيــاة الوالــد كنــت أنــا اســتلم الشــيكات‬\n‫املكتوبــة باســم والــدي مــن العمــاء وأوقــع علــى صــورة االســتالم‬\n‫الشــيكات وبعــد وفــاة والــدي بســنتان ادعــى علــي‪ ..... /‬وكان برتبــة‬\n‫لــواء يف املباحــث العامــة وســجنني ثالثــة أشــهر ظلمــا بعــد تبــرءا ومتلــص‬\n‫إخوتــي مــن املوضــوع وأنهــم غيــر مســئولني وبعدهــا حولــت معاملتــي إلــى‬\n‫احملكمــة الشــرعية ومتــت براءتــي بحمــد اهلل وكذالــك رفضهــم دفــع‬\n‫رواتــب العمالــة الباكســتانية والتركيــة ومواطــن ســعودي وعددهــم‬\n‫خمســة عشــر الذيــن كانــت كفالتهــم الســابقة علــى الورشــة الهندســية‬\n‫ثــم مت نقلهــم بحيــاة الوالــد علــى كفالتــي اقــل راتــب للعامــل ثالثــة أالف‬\n\n\n                                                                                        ‫‪304‬‬\n\f      ‫ريــال وقمــت بتصفيــة عــدد كبيــر منهــم وتســليمهم رواتبهــم وتذاكــر‬\n      ‫ســفر لبلدانهــم مــن مالــي اخلــاص ومــا زال منهــم موجــود يعمــل لــدي‬\n      ‫ومســتعدون للشــهادة علــى كالمــي لرفضهــم الورثــة حتمــل املســئولية‬\n      ‫وكل هــذه األمــور تغاضيــت عنهــا ألننــا إخــوة أشــقاء ولــم اســأل عمــا‬\n      ‫أخــذوه ولــم أحاســبهم واحتســبت أمــري إلــى اهلل علمــا انــه علمــت أنهــم‬\n      ‫قامــوا بعمــل مبايعــة مــع الوالــدة مبنتجــع صيفــي جبلي بدولــة لبنان كان‬\n      ‫لوالــدي ومت شــرائه مــن حــر مالــه وقــام والــدي بحياتــه بكتابتــه باســم‬\n      ‫والدتــي مــع عــدد ســبع بيــوت لضمــان عيشــة وحيــاة والدتــي بعــد مماتــه‬\n      ‫ببيعــه للبنــات فقــط وحرمانــي إنــا وأخــي مــن حصتنــا وحصتــي فيــه إنــا‬\n      ‫لوحــدي تقــدر بثالثمائــة إلــف دوالر وكنــت أحــول لــه مبئــات أالف‬\n      ‫الريــاالت ملصاريفــه ومصاريــف عالجــه ملرضــه بالســرطان حماكــم‬\n      ‫اهلل مــن كل شــر ومكــروه إمــا ادعائهــا بأنهــا لــم تأخــذ نصيبهــا‬\n      ‫مــن ارث أبيهــا يف اململكــة العربيــة الســعودية فهــي تناقــض نفســها‬\n      ‫بادعائهــا إمــام فضيلتكــم وتوثيــق مــا ادعــت بــه أنهــا اســتلمت مبلــغ‬\n      ‫مائــة إلــف ريــال مــن ابنــة ‪ .....‬وهــذا غيــر صحيــح وغيــر صادقــة فاملبلــغ‬\n      ‫الــذي أعطــي لهــم مائتــان إلــف ريــال بوجــود أخــي علــي مــن قيمــة ارض‬\n      ‫مقــام عليهــا عمــارة ســكنية مبســاحة األرض ألفــان وخمســمائة متــر‬\n      ‫علــى ثالثــة شــوارع بحــي ‪ ...........‬بجــوار فنــدق الــدار البيضــاء تبعــد عــن‬\n      ‫خــط املدينــة ثالثمائــة متــر وهــذه األرض واملبانــي عمرهــا الوالــد بيــده‬\n      ‫وكان وقتهــا اليوجــد مصانــع أملنيــوم بالســعودية فقــام بشــراء األملنيــوم‬\n      ‫مــن لبنــان لتركيبهــا واجهــات وشــبابيك للمبنــى وتقــدر قيمتهــا بعــام‬\n      ‫‪ 1407‬أكثــر مــن ثالثــة مليــون ريــال بــأي حــق ومــن خولهــم بالتنــازل‬\n      ‫عــن حــق أبــي وحقوقنــا وبيعهــا واســتالمهم املائتــان إلــف ريــال وتقســيمها‬\n\n\n‫‪305‬‬\n\f‫عليهــم بيعهــم ارض مبنطقــة احملجــر ثمامنائــة وخمســون متــر مربــع عليهــا‬\n‫مبانــي ســكنية ومســتودع علــى شــارعني تبعــد عــن الشــارع الرئيســي‬\n‫مائــة متــر تقــدر بعــام ‪ 1407‬بســتمائة إلــف ريــال بيعــت ل‪ .....‬مبائــة إلــف‬\n‫ريــال دون علمنــا وتقســيمهم املبلــغ بينهمــا فقــط هــم ورثــة املغفــور لــه ‪.....‬‬\n‫فقــط علمــا انــه كانــت هنــاك معــدات صناعيــة تقــدر مبئتــان إلــف ريــال‬\n‫يف املســتودع أيــن هــم ! علمــا انــه قــام ‪ .....‬ويكــون ابــن شــقيق الوالــدة‬\n‫ببيــع األرض بثمامنائــة إلــف ريــال بعــد شــهر مــن شــرائها منهــم ‪ ،‬إمــا‬\n‫مطالبتهــا باملعــدات والســيارات والرافعــة الشــوكية فهــي باعترافهــا‬\n‫إمــام فضيلتكــم باســتالمهم مبلــغ ســتون إلــف ريــال مــن املدعــو ‪.....‬‬\n‫لشــرائه املعــدات وخامــات حديــد وأملنيــوم ومكينــة تصنيــع أبــواب‬\n‫قيمتهــا لوحدهــا خمســون إلــف ريــال وكنــت إنــا أكثــر علمــا مــا يوجــد‬\n‫يف املســتودع بــأرض اخلمــرة اقســم بــاهلل العظيــم إن املعــدات واملوجــودات‬\n‫مــن بضاعــة صناعيــة حديــد وأملنيــوم وإكسســوارات كانــت تقــدر‬\n‫بحوالــي النصــف مليــون ريــال بــأي حــق وبشــرع مــن تهــدر هــذه احلقــوق‬\n                                                                          ‫واألمــوال ‪..‬‬\n‫اســتلمتي أنتــي وإخوتــي البنــات ووالدتــي مبلــغ أربعــون إلــف ريــال مــن‬\n‫ورثــة‪ .....‬بعــد وفــاة والــدي وقمتــم بتوزيعهــا عليكــم انتــم فقــط البنــات‪!..‬‬\n‫وهنــاك ســندات أمانــة كانــت بحوزتكــم يطالــب بهــا والــدي شــخصني‬\n‫احدهــم يدعــى ‪ .....‬الســوري كان الوالــد يطالبــه مبائــة إلــف ريــال‬\n‫والثانــي يدعــى ‪ .....‬صاحــب مؤسســة ‪ .....‬لألملنيــوم يطالبــه الوالــد مبلــغ‬\n‫ثالثمائــة إلــف ريــال مــاذا فعلتــم بتلــك الســندات هــل قمتــم بأخذهــا أم‬\n‫ال علمــا إننــي ذهبــت لألستفســار عــن الشــخصني فوجدتهــم يف ذمــة‬\n‫اهلل‪،‬قمتــم ببيــع ســيارة بــي أم دبليــو تاريــخ الصنــع ‪ 2005‬م تخــص الوالــد‬\n\n\n                                                                                          ‫‪306‬‬\n\f      ‫بلبنــان أيــن قيمــت الســيارة وزعــت علــى البنــات فقــط ‪ ،‬قمتــم ببيــع أثــاث‬\n      ‫منــزل الوالــد بجــده ومت تقســيم املبلــغ دون علمــي عليكــم وزعــت علــى‬\n      ‫البنــات فقــط ! إمــا بطلبهــا اخــذ والدتــي وأن تكــون الوصيــة عليهــا‬\n      ‫فقســم بــاهلل العظيــم تكلفــت مــا تكلفــت مــن مصاريــف وبطيــب خاطر‬\n      ‫وال أطالــب إال األجــر مــن اهلل بعــد مــا ســمعت مــن شــقيقات والدتــي‬\n      ‫بلبنــان إن إخوتــي وأزواجهــم متضايقــن مــن خدمتهــا ونحــن األوالد أحــق‬\n      ‫بخدمتهــا ومصاريفهــا وأن لــم نســتجب ملطالبهــم ســوف يقومــون بوضعها‬\n      ‫بــدار العجــزه بلبنــان والســبب الثانــي لســكنها مــع خادمــة لوحدهمــا‬\n      ‫بالشــقة علمــا إن والدتــي محتاجــة لرعايــة طبيــة ســريريه مســتمرة وال‬\n      ‫تتحكــم بذهابهــا إلــى احلمــام وحذرنــا طبيبهــا اخلــاص بلبنــان أن والدتــي‬\n      ‫قــد تفتــح بــاب الشــقة وتهــرب أو ترمــي نفســها مــن نافــذة الشــقة ألنهــا‬\n      ‫غيــر مدركــة ؛ فضيلتكــم شــقيقتي التــي تدعــي وتطلــب أن تكــون‬\n      ‫الوصايــة لوالدتــي لهــا بشــهود عــدة ســمعوا مــن والدتــي أنهــا ال ترغــب‬\n      ‫بالذهــاب عندهــا ألن أخــر مــرة كانــت الوالــدة عنــد شــقيقتي مبدينــة‬\n      ‫جــده قــام زوج شــقيقتي ‪ .....‬بشــتمها بكلمــة مخلــة للشــرف ورفــع‬\n      ‫يــده عليهــا وتهديدهــا بالضــرب لــو قامــت بالتبــول علــى نفســها وعلــى‬\n      ‫املجلــس مــرة أخــرى وقلــت لشــقيقتي عنــد رغبتــك برؤيــة والدتــك الــدار‬\n      ‫دارك ونحــن خــارج الــدار يف أي وقــت وأي يــوم وهــذا حقــك شــرعا‪ .‬ثــم‬\n      ‫ســألت املدعــى عليــه ‪ .....‬عــن االمــاك التــي كانــت باســم ‪ .....‬فقــال ‪:‬‬\n      ‫ال أعلــم عنهــا شــيئا ‪ .‬وبســؤاله عــن االمــاك التــي بأســمة وأقــر بأنهــا‬\n      ‫ملــك لوالــده فقــال ‪ :‬ان االقــرار صحيــح ‪ ،‬وقــد باعــت املدعيــة بضاعــة‬\n      ‫الورشــة‪ ،‬وامــا الورشــة فهــي مســتأجرة ‪ ،‬وامــا االراضــي الثــاث فقــد‬\n      ‫بعتهــا مببلــغ ‪ 300‬ألــف ريــال وســلمت والدتــي نصــف الثمــن ‪ ،‬والنصــف‬\n\n\n‫‪307‬‬\n\f‫االخــر ســددت بــه ديــون علــى الوالــد عبــارة عــن أجــره ‪ 15‬عــام مببلــغ‬\n‫‪ 45‬ألــف ريــال وأجــرة الورشــة مببلــغ ‪ 25‬ألــف ريــال وديــن مبوجــب صــك‬\n‫شــرعي مببلــغ ‪ 180‬ألــف ريــال ‪ ،‬فــكان االجمالــي مبلــغ وقــدرة ‪250‬‬\n‫ألــف ريــال‪ ،‬فدفعــت مــن مالــي اخلــاص ‪ 100‬ألــف ريــال ‪ .‬وبســؤاله عــن‬\n‫مبلــغ ‪ 100‬ألــف ريــال مــن ورثــة ‪ .....‬قــال ‪ :‬لــم أســتلمها ‪ ،‬واملبلغ يف احلقيقة‬\n‫هــو ‪ 200‬ألــف ريــال ‪ ،‬وأســتلمتها الوالــدة بحضــور املدعــى عليــه‪،.....‬‬\n‫وهــو مــن أخبرنــي بذلــك ‪ .‬وبســؤاله عــن مبلــغ ‪ 60‬ألــف ريــال مــن ‪.....‬‬\n‫قــال ‪ :‬هــي مقابــل بيــع بضاعــة الورشــة وقــد أســتلمتها املدعيــة والوالــدة‬\n‫حســب مــا أعلــم ‪ .‬وبســؤال املدعــى عليــه علــي عــن مبلــغ ‪ 5‬أالف ريــال‬\n‫قــال ‪ :‬لقــد أســتلمتها ولــم أســلم أحــدا منهــا شــيئا ‪ .‬وبســؤاله عــن عــدة‬\n‫الورشــة قــال ‪ :‬لقــد أخذتهــا وهــي عبــارة عــن فريــزر و منشــارين و ثالثــه‬\n‫دريــات وطاولــة وملزمــة ‪ .‬وبعــرض مــا تقــدم علــى املدعيــة قالــت ‪ :‬أطلــب‬\n‫االمهــال للــرد ‪ .‬فأفهمــت املدعيــة بــأن عليهــا مصادقــة الوكالــة مــن‬\n‫اجلهــات الرســمية الســعودية ‪ .‬ثــم رفعــت اجللســة لذلــك ‪ .‬ويف يــوم الســبت‬\n‫املوافق‪1433/06/28‬ه ـ افتتحــت اجللســة الســاعة ‪ 11 : 30‬وفيهــا حضــر‬\n‫الطرفــان ‪ ،‬ثــم أبــرزت املدعيــة أصــل الوكالــة بعــد مصادقــة اجلهــات‬\n‫الرســمية الســعودية عليهــا ‪ ،‬ومت تزويــد أوراق املعاملــة بنســخة منهــا ‪،‬‬\n‫وبســؤالها عمــا طلبــت اإلمهــال مــن أجلــه قدمــت مذكــرة هــذا نصهــا ‪:‬‬\n‫أوالً‪ -:‬ان املدعــى عليــه ‪ .....‬قــد أقــر امــام فضيلتكــم ب ــأنه كان الــذراع‬\n‫اليمنــى لوالــدي ( مورثنــا) يف ادارة اعمالــه وأموالــه ويذكــر بأنــه كان‬\n‫يعلــم الــواردة والشــاردة والصغيــرة والكبيــرة ‪ ،‬وهــذا اقــرار منــه بأنــه‬\n‫كان أمــوال مورثنــا كانــت حتــت يــده وإدارتــه ‪ ،‬ونظــر ًا ألن والدنــا‬\n‫كان ال يحمــل اجلنســية الســعودية واملدعــى عليــه ‪ .....‬يحمــل اجلنســية‬\n\n\n                                                                                        ‫‪308‬‬\n\f      ‫الســعودية فكانــت امــوال مورثنــا مــن عقــارات ومنقــوالت باســم املدعــى‬\n      ‫عليــه وذلــك ثابــت بإقــراره املــؤرخ يف ‪1404/7/26‬ه ـ (املرفــق صورتــه )‬\n                          ‫وان عناصــر التركــة املعلومــة لدينــا هــي عبــارة عــن ‪:‬‬\n      ‫‪ -1‬ثالثة قطع اراضي ذات االرقام (‪ ) 725 -725 -726‬مبخطط ‪......‬‬\n                                                                 ‫‪ -2‬االرض التي باسم ‪......‬‬\n                                  ‫‪ -3‬الورشة الهندسية ألعمال احلديد واألملنيوم ‪.‬‬\n               ‫‪ -4‬بضاعة وأغراض وإكسسوارات بداخل الورشة ومخازنها ‪.‬‬\n                                ‫‪ -5‬ديون لدى الغير مستحق األداء ملورثنا وهي ‪-:‬‬\n                                            ‫‪ 100.000‬ريال لدى املدينني ورثة ‪......‬‬\n                                                     ‫‪ 60.000‬ريال لدى املدين ‪...... /‬‬\n                                                         ‫‪ 5000‬ريال لدى املدين ‪......‬‬\n                                               ‫‪ -6‬معدات وسيارات ورافعة وخالفه ‪.‬‬\n      ‫هــذا بخــاف عناصــر التركــة األخــرى الغيــر معلومــة لنــا ويعلمهــا‬\n      ‫املدعــى عليهــم بإعتبــاره كان القائــم علــى ادارة امــوال والــدي ونطالبــه‬\n                                                                                 ‫بإظهارهــا ‪.‬‬\n      ‫ثاني ـاً‪ -:‬بخصــوص مــا ذكــره املدعــي بــأن والــدي قــد أوصــى بقطــع‬\n      ‫االراضــي اململوكــة بصــك واحــد هــذا قــول غيــر صحيــح ال يوجــد‬\n      ‫مــا يؤيــده ونطلــب احضــار الشــاهدة ‪ .....‬ألخــذ شــهادتها علــى قولــه‬\n                                    ‫‪،‬وتقســيم هــذه األرض او اعطائنــا نصيبنــا‪.‬‬\n      ‫ثالثــا‪ -:‬بخصــوص مــا ذكــره بأننــا اســتلمنا نصيبنــا مــن قيمــة املعــدات‬\n      ‫والســيارات والبضاعــة هــذا قــول مرســل ال يوجــد مــا يؤيــده ‪ ،‬حيــث ان‬\n      ‫احلقيقــة ان جميــع امــوال مورثنــا يف الســعودية حتــت يــده وإدارتــه وال‬\n                                     ‫نســتطيع وضــع يدنــا عليهــا والتصــرف فيهــا ‪.‬‬\n\n\n‫‪309‬‬\n\f‫رابع ـاً‪ -:‬أمــا بخصــوص مــا ذكــره بأننــا اســتلمنا الديــون املســتحقة‬\n‫لوالدنــا لــدى الغيــر فإننــا اســتلمنا البعــض منهــا ومت تقســيمه علــى الورثــة‬\n                            ‫والبعــض األخــرى فقــد اســتلمه املدعــى عليهــم ‪.‬‬\n‫وحفاظ ـ ًا علــى حقــوق جميــع الورثــة فقــد تضمنــت املــادة (‪ )2/124‬مــن‬\n‫نظــام املرافعــات الشــرعية مــا نصــه ( للمحكمــة نــدب اخلبيــر الــذي‬\n ‫يطلبــه أحــد اخلصــوم وليــس للخصــم اآلخــر االعتــراض علــى ذلــك ) ‪.‬‬\n‫وحفاظ ـ ًا علــى وقــت فضيلتكــم ‪ .‬لــذا التمــس مــن فضيلتكــم احالــة‬\n‫القضيــة الــى هيئــة اخلبــراء باحملكمــة لتحديــد كامــل عناصــر التركــة‬\n‫مــن عقــارات ومنقــوالت وأمــوال نقديــة وديــون مســتحقة ملورثنــا لــدى‬\n‫الغيــر وتصفيتهــا وســداد الديــون املســتحق علــى مورثنــا لصالــح الغيــر‬\n‫وحتديــد حصــة ونصيــب كل وريــث ومــن ثــم احلكــم بإلــزام املدعــى‬\n                                                            ‫عليهــم بتســليم مورثــه ‪.‬‬\n‫وبعــرض ذلــك علــى املدعــى عليهمــا أجــاب ‪ .....‬قائــا ‪ :‬ليــس لــدي مــا‬\n‫أضيفــه ‪ .‬وأجــاب ‪ .....‬قائــا ‪ :‬ليــس يف املذكــرة مــا يخصنــي ‪ ،‬ســوى‬\n‫مبلــغ ‪ 5‬آالف ريــال مــن ‪ ، .....‬فقــد أخذتــه لنفســي وتصرفــت فيــه ‪.‬‬\n‫وبعــرض ذلــك علــى املدعيــة قالــت ‪ :‬إن لــدي بينــات تثبــت اســتالم املدعــى‬\n‫عليهمــا بعــض املبالــغ وأطلــب اإلمهــال إلحضارهــا يف جلســة قادمــة ‪ .‬ثــم‬\n‫رفعــت اجللســة لذلــك ‪ .‬ويف يــوم الســبت املوافق‪1433/07/05‬ه ـ افتتحت‬\n‫اجللســة الســاعة ‪ 08 : 15‬وفيهــا حضــر الطرفــان ‪ ،‬وقدمــت املدعيــة‬\n‫مذكــرة هــذا نصهــا ‪ :‬أوال‪ :‬ردا علــى مــا ذكــر مــن املدعــى عليهمــا ‪.....‬‬\n‫و‪ .....‬بأنــي اســتلمت مبلــغ مائــة ألــف ريــال ســعودي مــن أبنــة ‪ .....‬وبعــد‬\n                   ‫ذلــك غيــر املبلــغ ملئتــان ألــف ريــال وأنــه أنــا مــن اســتلمتها‬\n‫الــرد‪ :‬بســؤال الســيدة ‪ .....‬قالــت انهــا لــم ترانــي بحياتهــا وان مــن اســتلم‬\n\n\n                                                                                             ‫‪310‬‬\n\f                                              ‫املبلــغ مــن أخاهــا هــو املدعــي عليــه ‪.....‬‬\n      ‫أضافــة أن الســيد ‪ .....‬أعاطنــي ورقــة بخــط يــده مرفقــه لديكــم تنــص‬\n      ‫علــى أن املدعــي عليــه ‪ .....‬هــو مــن أســتلم املبلــغ وقــدره مئــة ألــف ريــال‬\n                         ‫وليــس أحــد غيــره وهــم مســتعدون للشــهاده يف أي وقــت‬\n      ‫ثانيا‪ :‬أفاد املدعي عليه ‪ .....‬يف اجللســة الســابقة أنه ال يوجد ما يخصه‬\n      ‫ســوى مبلــغ خمســة أالف ريــال أســتلمها مــن ‪ ،.....‬مــع العلــم ان الورقــة‬\n      ‫املرفقــة لديكــم بخــط يــده تثبــت أخــذه ملبالــغ أخــرى فأنــا أطلــب مــن‬\n      ‫ســعادتكم بإحالــة الورقــة خلبيــر خطــوط ألنــه أنكــر خــط يــده ‪ .‬ثالثــا‪:‬‬\n      ‫ادعائــه أننــي اســتلمت مبلــغ ســتون ألــف ريــال مــن ال‪ ، .....‬فالبدايــة أريــد‬\n      ‫االثباتــات أن كان صــادق وباملقابــل الورقــة املرفقــة بخــط يــده التــي‬\n                 ‫ســبق وانكرهــا مكتــوب فيهــا هــو مــن اســتلم املبلــغ بالتحديــد‬\n      ‫رابعــا‪ :‬هــذه النقطــة ســوف أتــرك لســعادتك اســتنتاج مــا حــدث قطعــة‬\n      ‫األرض الــذي قــال املدعــي عليــة ‪ .....‬أنــه لــم يبعهــا وال يعلــم عنهــا شــيء‬\n      ‫وهــي أرض باســم ‪ .....‬الــذي ســلمها للســيدة ‪( .....‬الوالــدة) وأصبحــت‬\n      ‫ذمتــه خاليــة وبعــد ذلــك قامــت الســيدة ‪ .....‬بإعطائهــا للمدعــي عليــه ‪.....‬‬\n      ‫و‪ .....‬ســؤال املشــتري اجلديــد مــن باعــك هــذه األرض قــال املدعــي عليــه‬\n      ‫‪ .....‬مــع أخواتــه البنــات يف احملكمــة مــع العلــم أن جميــع أخواتــه البنــات‬\n      ‫يف وقتهــا موجــودون يف لبنــان (‪.....‬و‪.....‬و‪ ).....‬كانــوا قصــر و‪ .....‬كانــت‬\n      ‫يف األمــارات وأنــا أيضــا كنــت يف لبنــان إذن مــن كان يف احملكمــة‬\n      ‫مــن البنــات أنــا ال أشــكك بنزاهــة القضــاء الســعودي ولكــن هنــاك مــن‬\n                                                                   ‫يتحايــل علــى القانــون‬\n      ‫فالســيد ‪ .....‬قــد أشــترى األرض ثــم باعهــا للســيد ‪ .....‬ومــن ثــم للســيدة‬\n      ‫املوجــودة حاليــا وعــن ســؤالها منــذ خمســة أيــام قالــت أن االرض مت‬\n\n\n‫‪311‬‬\n\f‫بيعهــا علــى الشــكل التالــي باعهــا املدعــي عليــه ‪ .....‬للســيد ‪ .....‬ومــن‬\n‫ثــم للســيد‪ .....‬ثــم لهــا بعــد كل مــا ذكــر أطلــب مــن ســعادتك أن تطلبــوا‬\n‫الصــك مــن املدعــي عليــه ‪ ..... .....‬وأن ثبــت صــدق كالم صاحــب االرض‬\n‫أنــه باعهــا بحضــور املدعــي عليــه ‪ .....‬وأخوتــه البنــات فســوف أجلــب‬\n‫أوراق مــن اجلــوزات تثبــت عــدم وجــود أخوتــه يف اململكــة أثــاء البيــع‬\n‫وأطالــب بالتحقيــق يف املوضــوع ألنــه يعتبــر تزويــر يف أوراق رســميه‬\n                                                                       ‫وشــهادة باطلــة‪.‬‬\n‫خامســا‪ :‬بالنســبة للديــن الــذي أشــارت إليــه وهــو مبلــغ مئــة وثمانــون‬\n‫ألــف ريــال للســيد ‪ .....‬وقــد تــويف قبــل ســنتان وأصــدر الصــك فضيلــة‬\n                                          ‫القاضــي‪ .....‬ومت ســجنه ثالثــة شــهور‬\n‫الــرد فضيلــة الشــيخ ‪:‬لــم يذكــر لــك املدعــي عليــه ‪ .....‬أن القضيــة‬\n‫منــذ أربــع ســنوات والوالــد متــويف مــن أكثــر مــن ســبعه وعشــرون ســنة‬\n‫والقضيــة بــن‪ .....‬والســيد ‪ .....‬الــذي أفادنــا ولــده الســيد ‪ .....‬بــأن والــده‬\n‫تــويف منــذ ثــاث ســنوات وليــس ســنتان كمــا ذكــر املدعــي عليــه ‪.....‬‬\n‫وأن املبلــغ كان مطلــوب مــن املدعــي عليــه ‪ ،.....‬وأفادنــي الســيد ‪ .....‬أن‬\n‫املــال ليــس لوالــده بــل والــده كان الوســيط بــن ‪ .....‬والســيد ‪ .....‬وهــم‬\n‫مازالــوا علــى قيــد احليــاة ويف وقــت القضيــة كان الســيد ‪ .....‬موجــود مــع‬\n‫والــده يف احملكمــة وحكــم القاضــي بدفــع مبلــغ مئــة وثمانــون ألــف‬\n                                                           ‫ريــال علــى النحــو التالــي‬\n‫عشــرون ألــف ريــال يف حينــه وتقســيط املبلــغ ثــاث أالف ريــال كل‬\n                                           ‫شــهر تدفــع مــن خــال احملامــي ‪......‬‬\n‫وبســؤالي لــه هــل دفــع املبلــغ بالكامــل قــال ‪ ......‬بانــه ال يعلــم الن بعــد‬\n‫وفــاة والــده عمــل توكيــل للســيد ‪ .....‬واصبــح الســيد ‪ .....‬يســتلم املبلــغ‬\n\n\n                                                                                           ‫‪312‬‬\n\f      ‫مباشــره مــن احملامــي ‪ ،‬وقــال الســيد ‪ .....‬حــارث انــه مســتعد للشــهادة‬\n      ‫فكيــف يقــول املدعــي عليــه ‪ .....‬أن هــذا ديــن علــى والــده فليتقــي اهلل يف‬\n      ‫قولــه وأطالــب املدعــي عليــه ‪ .....‬بإحضــار صــك القضيــة ووضعهــا أمــام‬\n                                                               ‫ســعادتكم ليظهــر احلــق‬\n      ‫سادســا‪ :‬أمــا قضيــة اللــواء ‪ .....‬يف املباحــث العامــة وبأنــه ســجنه ثالثــة‬\n                            ‫أشــهر ظلمــا بعــد تبرئتــه ومتلــص أخوتــي مــن املوضــوع‬\n      ‫الــرد‪ :‬هــذا الــكالم غيــر صحيــح والســيد اللــواء ‪ .....‬مــازال علــى قيــد‬\n      ‫احليــاة وقــال أن القضيــة كانــت بســبب أعمــال بــن املدعــي عليــه ‪.....‬‬\n      ‫وبينــة وهــو علــى اســتعداد تــام مبواجهــة املدعــي عليــه واحلضــور للشــهادة‬\n      ‫يف أي وقــت وأحمــد اهلل أن اللــواء ‪ .....‬مــازال علــى قيــد احليــاة ليثبــت‬\n      ‫احلــق‪ ،‬وأذا كان لــدى املدعــي عليــه كالم غيــر هــذا فليواجــه اللــواء‪.....‬‬\n                                    ‫أمــام ســعادتكم أو يحضــر مــا يثبــت العكــس‬\n      ‫ســابعا‪ :‬أحــب املدعــي عليــه أن يدخــل مداعبــة علــى القضيــة عندمــا‬\n      ‫قــال أننــي الســيدة باســمه ‪ .....‬قمــت ببيــع ســيارة بــي أم دبليــو تاريــخ‬\n      ‫الصنــع‪ .....‬تخــص الوالــد يف لبنــان أنهــا ليســت دعابــة بــل هــي مشــيئة‬\n      ‫اهلل بإظهــار احلــق فالوالــد متــويف يف عــام ‪ .....‬هــل هنــاك شــركة تصنــع‬\n                                                    ‫ســيارة لعشــرون عــام إلــى االمــام‬\n      ‫الرجــاء التوقــف عــن االســتهزاء بهــذه القضيــة وقــول املنطــق واحلــق‬\n                                   ‫واطلــب االثباتــات مــن جهــة املدعــي عليــه ‪.....‬‬\n      ‫ثامنــا‪ :‬لقــد قــال املدعــي عليــه ‪ .....‬أن والــده أوصــى بــأرض مخطــط ‪.....‬‬\n      ‫بجنــوب جــده منطقــة اخلمــرة فهــم ثــاث قطــع بصــك واحــد فقــال لــي‬\n      ‫أن والــدي أوصــى بهــا بعــد مماتــه النــه لــم يكتــب لــه أي أمــاك كمــا‬\n      ‫كتــب ألخوتــي اخلمســة وأخــي ‪ .....‬يف لبنــان ولقــد أتهمنــي بأنــي شــاهدة‬\n\n\n‫‪313‬‬\n\f                                           ‫علــى هــذا الــكالم وأخــاه وزوجتــه‬\n‫أنــا أقــر وبكامــل قــواي العقليــه أنــي لــم أســمع هــذا الــكالم ولــم أشــهد‬\n‫عليه‪،‬واريــد أن يتــم أحضــار الســيده ‪.......‬للشــهاده وهــي زوجــة أخــاه‬\n‫‪ ،.....‬أمــا مــن الناحيــة القانونيــه والشــرع علــى حــد علمــي أن الوصيــه‬\n‫تكتــب وال تقــال شــفهي باالضافــة الــى الشــهاده تكــون رجــان أو‬\n                                   ‫رجــل وامرأتــان او أربــع نســاء واهلل أعلــم‬\n‫فــأن الوالــد رحمــة اهلل كان صاحــب حــق وأعطــاك الكثيــر ومنهــا‬\n‫اجلنســيه الســعودية التــي كلفتــه يف وقتهــا أكثــر مــن مئتــان ألــف ريــال‬\n‫ســعودي كمــا ذكــر الوالــد ولــم يعطهــا الخيــك واخوتــك البنــات فلمــاذا‬\n                                                      ‫لــم نخســمها مــن التركــة‬\n‫تاســعا‪ :‬قلــت أنــك تعلــم انــه اذا اخــذوا املــال ســوف يدمــر ويندثــر‪ ،‬وقلــت‬\n‫أن هنــاك قضيــة مت رفعهــا عليــك مــن قبــل والدتــك وتدخــل كبــار العائلة‬\n‫حللها الرد هل اذا اعطي كل شــخص حقه حســب الشــريعه االســاميه‬\n‫يكــون الــورث قــد دمــر وهــل ممكــن أن حتضــر صــك القضيــه التــي‬\n              ‫مــن نســج خيالــك لفضيلــة القاضــي وذكــر أســامي االقــارب‬\n      ‫أنا أشهد أن هذا الكالم غير صحيح ولم يتم رفع أي قضيه عليه‬\n‫عاشــرا‪ :‬عندمــا كان الوالــد علــى فــراش املــوت قــال أنــه الديــن عليــه‬\n‫فكيــف تريــد أن أقتنــع أن لــك رواتــب خمــس ســنوات لــم تأخذهــا‬\n‫وكــم كان راتبــك يف حينهــا ومــن أيــن متلــك مبلــغ ثمانــون ألــف ريــال‬\n‫كــم كان عمــرك لتجمــع هــذا املبلــغ وكيــف جمعتــه وأنــت لــم تســتلم‬\n‫رواتبــك كمــا تتدعــي فليــس مــن املنطــق والعقــل أن فتــى مــن اخلامســة‬\n‫عشــر مــن عمــره وطالــب حتــى العشــرين مــن عمــره كان يعمــل عنــد‬\n‫والــده يف الصيــف ويكــون لــه رواتــب خمــس أعــوام لــم يأخــذه وفائــض‬\n\n\n                                                                                      ‫‪314‬‬\n\f      ‫مشــاء اهلل ثمانــون ألــف ريــال أمــا بخصــوص ماقلتــه عــن خالتــك ‪.....‬‬\n      ‫زوجــه ‪ .....‬فلقــد أقــرت بــأن زوجهــا قــد أقتــرض منــك مبلــغ ثالثمئــة ألــف‬\n      ‫ريــال ســعودي وهــي ال تريــد أن تبــرء ذمتــه وقالــت أن أردمت املــال أحلقــوا‬\n      ‫بصاحبــه املتــويف فمــن أيــن لطالــب ولــم يســتلم رواتبــه أن ميلــك هــذا املبلغ‬\n      ‫ثالثمئــة ألــف ريــال ســعودي ســيدي القاضــي هــذا املــال مــن التركــه اي‬\n                                                                 ‫مــال الوالــد رحمــه اهلل‬\n      ‫أحــدى عشــر‪ :‬لقــد قــام املدعــي عليــه بتوجيــه التهمــه لزوجــي الســيد‪.....‬‬\n      ‫أنــه ضــرب والدتــي وقذفهــا بكالم اليســتطيع البوح به أمام ســعادتكم‬\n      ‫الرد أقسم باهلل العظيم أن زوجي لم يضرب أمي بل كان حنون عليها‬\n      ‫فهــو معــروف بأخالقــه العاليــه وحبــه للنــاس ومســاعدتهم وباالخــص‬\n      ‫بــره لوالدتــه التــي كانــت مقعــده وكان يرفــض أن يعاونــه أحــد عليهــا‬\n      ‫فــكان يعامــل والدتــي أحســن معاملــه وبشــهادة الكثيــر مــن النــاس منذ‬\n      ‫وفــاة الوالــد وهــو مــن يدعمهــا ويقــف بجانبهــا يف الوقــت الــذي تركهــا‬\n      ‫فيــه اوالدهــا الرجــال أكثــر مــن خمســة عشــر عــام حتــى اخوتــي البنــات‬\n      ‫عندمــا كانــوا قصــر كان يرعاهــم واطلــب مــن ســعادتك أســتدعاء‬\n      ‫الســيد ‪ .....‬وهــو أبــن املدعــي عليــه ‪ .....‬للشــهاده النــه الوحيد كان يدخل‬\n      ‫البيــت ويــرى كيــف كانــت تعامــل جدتــه ولــن أفكــر املدعــي عليــه ‪.....‬‬\n      ‫و‪ .....‬مــاذا فعــل الســيد ‪ .....‬أجتاههــم وأجتــاه أوالدهــم مــن خيــر‪ ،‬ومــع‬\n      ‫علــم املدعــي عليــه أن والدتــه تعانــي مــن مــرض الزهاميــر مــن الدرجــة‬\n      ‫املتاخــره وانــه بأمــكان أي شــخص يقــول لهــا أي شــيء وتــردده فهــي‬\n      ‫أصبحــت كالطفلــه تــردد ماتســمعه واطلــب مــن ســعادتكم ان تطلــب‬\n      ‫مــن املدعــي عليــه الشــهود الذيــن رئــوا زوجــي يضربهــا ويشــتمها وان لــم‬\n      ‫يحضــر أي شــهود ســوف أرفــع قضيــه أخــرى بسســب االدعــاء الــكاذب‬\n\n\n‫‪315‬‬\n\f‫علــى شــخص لــو ســئل عنــه يقــال هــو ســيد االخــاق واالحتــرام ويخــاف‬\n                                   ‫اهلل وال أقــول غيــر حســبي اهلل ونعــم الوكيــل‬\n‫اثنــى عشــر‪ :‬أمــا األرض التــي أتهمنــي بأنــي بعتهــا لنفســي دون علمــه‬\n                             ‫وهــي أرض بأســم الســيده ‪ .....‬وبشــهود أبنهــا ‪.....‬‬\n‫الــرد ‪ :‬فضيلــة القاضــي كيــف أبيــع أرض لنفســي وهــو شــاهد عليهــا‬\n‫مــاكان دوره مضغــوط عليــه أو يف غيبوبــه ال يعلــم مــاذا حــدث فليقــول‬\n‫املنطــق والعقــل وهنــاك شــهود وهــو ‪ .....‬واملدعــي عليــه ‪ .....‬وانــه مت بيعهــا‬\n‫مبوافقــة أخوتــي البنــات وبعــد وفــاة والــدي بخمســة ســنوات ومت توزيــع‬\n                                                                    ‫املــال علــى أخوتــه‬\n          ‫ثالثة عشر‪ :‬عندما قال املدعي عليهما بأني أخذت عفش املنزل‬\n‫الــرد‪ :‬هــذا غيــر صحيــح فلقــد دفعــت رهنيــة البــراد و التلفــاز وغســالة‬\n‫قدميــة ال تعمــل جيــدا قيمــة الرهنيــة عشــرة أالف ريــال ســعودي مت دفعهــا‬\n‫للســيد ‪ .....‬وكان املنــزل خالــي متامــا مــن االثــاث وهنــاك مــن يشــهد وهــو‬\n‫الســيد ‪ .....‬وأرجــوا أســتدعائة للشــهادة وانــا مــن يطالــب بأخبــاري أيــن‬\n                                                                  ‫ذهــب عفــش املنــزل‬\n‫أربعــة عشــر‪ :‬هنــاك مســتودعات مليئــة بالبضاعــة مت بيعهــا مــن خــال‬\n‫املدعي عليهما ‪ .....‬و‪ .....‬للســيد ‪ .....‬والســيد ‪ .....‬وباإلضافة لبيع مكنة‬\n                                                               ‫تصنيــع أبــواب ســحاب‬\n‫املطلــوب معرفــة قيمــة البضاعــة املذكــورة وإفادتــي بطريقــة توزيعهــا‬\n‫ويف حــال نكــران املدعــي عليهمــا ســيتم جلــب الشــهود التــي تثبــت ان‬\n‫املدعــي عليهمــا ‪ .....‬و‪ .....‬هــم مــن بــاع تلــك البضائــع التــي تقــدر باملاليــن‬\n‫والتــي أفــاد املدعــي عليــه ‪ .....‬يف حينــه أنهــا تقــدر بقيمــة عشــرة ماليــن‬\n‫وحصــة البنــت الواحــدة مليــون ريــال وأخيــرا يف أخــر جلســه عندمــا قــال‬\n\n\n                                                                                            ‫‪316‬‬\n\f      ‫لــك املدعــي عليــه ‪ .....‬أن والــدي قــد تــويف ومالــه قــد نهــب وأن مــن نهبــه‬\n      ‫هــو املدعــي عليــه ‪ .....‬و‪ .....‬وأنــا فهــذا االدعــاء كاذب النــي أطالــب‬\n      ‫بحقــي وحقــوق أخوتــي البنــات وأن كان لديــه دليــل ملمــوس فاليقدمــه‬\n                       ‫أنــا لــم أنهــب مــال والــدي وحفاظــا علــى وقــت فضيلتكــم‬\n      ‫لــذا التمــس مــن فضيلتكــم احالــة القضيــة الــي هيئة اخلبــراء باحملكمة‬\n      ‫لتحديــد كامــل عناصــر التركــه مــن عقــارات ومنقوالت وأمــوال نقدية‬\n      ‫وديــون مســتحقه أن وجــد ملورثنــا لــدى الغيــر وتصفيتهــا وحتديــد حصــة‬\n      ‫ونصيــب كل وريــث ومــن ثــم احلكــم بإلــزام املدعــى عليهــم بتســليم‬\n      ‫مورثه‪،‬كمــا أحضــرت املدعيــة للشــهادة وأدائهــا ‪ .....‬لبنانــي اجلنســية‬\n      ‫مبوجــب اإلقامــة رقــم ‪ .....‬وهــو مــن مواليــد ‪1954‬م ويعمــل يف مصنــع ‪.....‬‬\n      ‫للصناعــات احلديديــة وهــو ابــن خلــال الطرفــن ‪ ،‬وشــهد قائــا ‪ :‬أشــهد‬\n      ‫بــاهلل العظيــم الــذي ال إلــه غيــره أننــي ســمعت أن املدعــى عليهمــا همــا‬\n      ‫مــن بــاع البضاعــة التــي يف الورشــة ‪ ،‬وكان ذلــك بعــد وفــاة املــورث‬\n      ‫بحوالــي عــام ‪ ،‬وفيمــا يخــص األرض التــي باســم والدتــي وهــي ملــك‬\n      ‫للمــورث ‪ ،‬فقــد اشــتريتها مبائــة وعشــرة آالف ريــال يف ‪1409/3/7‬ه ـ ‪،‬‬\n      ‫وقــد ســلمت الثمــن كامــا للورثــة عــدا املدعــى عليهمــا ‪ ،‬فقــد تنــازال‬\n      ‫عــن نصيبهمــا يف هــذه األرض ألخواتهمــا بنــاء علــى إقــرار محــرر وموقــع‬\n      ‫منهمــا ‪ .‬هكــذا شــهد ‪ .‬وبعــرض املذكــرة والشــاهد وشــهادته علــى‬\n      ‫املدعــى عليهمــا قــاال ‪ :‬نطلــب اإلمهــال للــرد ‪ .‬ثــم رفعــت اجللســة لذلــك‬\n      ‫ويف يــوم االثنــن املوافــق ‪1433/07/07‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 02 : 00‬وفيهــا حضــر الطرفــان ‪ ،‬وبســؤال املدعــى عليهمــا عمــا طلبــا‬\n      ‫اإلمهــال مــن أجلــه قــدم املدعــى عليــه ‪ .....‬مذكــرة هــذا نصهــا ‪ :‬ردا علــى‬\n      ‫الدعــوى املقامــة ضــدي مــن شــقيقتي باســمة ‪ ..... .....‬وتدعــي بأننــي قلــت‬\n\n\n‫‪317‬‬\n\f‫إن املبلــغ قــدره مائتــي ألــف ريــال وليــس مائــة ألــف ريــال وأنهــا قامــت هــي‬\n‫باســتالمها ‪ ،‬فإننــي لــم أقــل ذلــك بــل قلــت أنهــا اعترفــت باســتالم مائــة‬\n‫ألــف ريــال أي أنهــا متثــل الورثــة وقمــت بتوضيــح العبــارة بقولــي إنكــم‬\n‫اســتلمتم أنتــم البنــات والوالــدة بوجــود شــقيقي ‪ .....‬ليــس مائــة ألــف بــل‬\n                                                                      ‫مائتــا ألــف ؛؛‬\n‫ردا للبنــد الرابــع قطعــة األرض التــي كانــت معروفــه أنهــا بأســم ‪.....‬‬\n‫وأنــه قــام بتســليمها لوالدتــي وهــي أجنبيــه وقامــت والدتــي بتســليمها لــي‬\n‫وقمــت إنــا بعــد ذالــك ببيعهــا وأخــذت خمســة بنــات للمحكمــة الشــرعية‬\n‫وادعيــت أنهــم إخوتــي وحتايلــت علــى القضــاة والشــرع واحلكومــة وقمت‬\n‫ببيعهــا للمدعــو ‪ !!!.....‬ســيدي هــذا الــكالم لــو صحيــح بإمكانكــم‬\n‫االستفســار عــن طريــق اجلهــات احلكوميــة وأننــي مســتعد ألي أجــراء‬\n                                            ‫قانونــي وشــرعي إذا ثبــت ذالــك ‪،،‬‬\n‫ردا للبنــد اخلامــس قضيــة ‪ .....‬ســيدي قمــت بــردي الســابق بتوضيــح‬\n‫انــه يوجــد صــك شــرعي اصــدر حكــم علــي وبإمــكان فضيلتكــم‬\n‫االســتيضاح وقــراءة الصــك للقضيــة مــن أي عــام كانــت هــذه القضيــة‬\n‫وانــه صــدر حكــم علــي مــن جهــة احلقــوق املدنيــة بجــده املوظــف ‪......‬‬\n‫بســداد مبلــغ مائتــان وكســور توضيــح املبلــغ موجــود بالصــك الشــرعي‬\n‫وأن أقــوم بســداد املبلــغ أقســاط شــهرية كل قســط ألفــان ريــال وبحمــد‬\n‫اهلل ســددت املبلــغ وموجــود شــهود كانــوا يقومــون بتوصيــل املبالــغ‬\n‫واســتالم الســندات وألكــن قبــل ثالثــة ســنوات قــام ‪ .....‬وادعــى انــه لــم‬\n‫يســتلم املبلــغ فطلبــت منــه حلــف اليمــن فحلــف وصــدر صــك شــرعي‬\n                                   ‫وإننــي أقــوم بســداد املبلــغ للمــرة الثانيــة ‪،‬‬\n‫ردا للبنــد الســادس قضيــة ‪ .....‬أمتنــى مــن فضيلتكــم حســب طلبهــا‬\n\n\n                                                                                         ‫‪318‬‬\n\f      ‫وادعائهــا طلبــه للمثــول إمــام فضيلتكــم ومصــر إنــا علــى مواجهتــي‬\n                                ‫أمــام فضيلتكــم وتوضيــح وصــدق مــا قلتــه ‪،،‬‬\n      ‫ردا للبنــد الســابع بيــع الســيارة فأننــي أخطئــت بالتاريــخ فقــط ومت بيــع‬\n                          ‫الســيارة بتاريــخ ‪1986‬م وتقســيم قيمتهــا عليكــم ‪،،‬‬\n      ‫ردا للبنــد الثامــن ارض اخلمــرة ‪ ........‬إمــام فضيلتكــم شــقيقي ‪.....‬‬\n      ‫فاستفســروا منــه وكيــف بحيــات والــدي رحمــة اهلل عليــه مت شــراء‬\n      ‫لــكل فــرد منهــم شــقة مبدينــة بيــروت وطلــب منــي إن يســجل لــي شــقة‬\n      ‫فرفضــت بــان لبنــان ليســت بلــدي وليــس لــي عيشــة فيهــا ومــع ذالــك‬\n      ‫قامــوا إخوتــي البنــات بالتحايــل علــى والدتــي وحرمانــي مــن نصيبــي‬\n      ‫بــأرض وبيــت اجلبــل وكتبــوه باســمهم فقــط علــى حجــة إن والدتــي‬\n                                                   ‫قامــت بإعطائهــم األرض هبــه ؛؛‬\n      ‫ردا علــى البنــد التاســع كان هنــاك قضيــة رفعتهــا والدتــي يف احملكمــة‬\n      ‫الشــرعية يف بــاب شــريف ســابقا وكانــت دعواهــا بأننــي رافــض‬\n      ‫إعطائهــا اثنــن مــن شــقيقاتي كانــا قاصريــن للعيــش معهــا بلبنــان‬\n      ‫وكنــت رافــض إصــدار تأشــيرة خــروج وعــوده لهــا ألننــي كنــت خائــف‬\n      ‫عليهــا ‪ .....‬شــقيقتي مــن إحــداث لبنــان يف تلــك األيــام ورغبتــي بــان يتــم‬\n      ‫الوضــع كمــا حيــاة والــدي وكانــت الدعــوى عنــد فضيلــة الشــيخ ‪.....‬‬\n                                                             ‫هــذا الــذي افتكــره ؛؛‬\n      ‫ردا علــى البنــد العاشــر لقــد قلتــي يف البنــد الثالــث عشــر انــك قمــت‬\n      ‫بســداد عشــرة أالف ريــال رهــن عفــش بيــت الوالــد عــن أشــياء ليســت‬\n      ‫لهــا قيمــة الرهــان حســب قولــك وقبــل وفــاة والــدي قــال لــك إن ال ديــن‬\n      ‫عليــه كيــف يكــون ذالــك !! وعنــد وفــاة والــدي كان عمــري إحــدى‬\n      ‫وعشــرون عامــا وبشــهادة شــقيقي ‪ .....‬وبشــهادة عمــال كانــوا يعملــون‬\n\n\n‫‪319‬‬\n\f‫يف حيــاة والــدي مســتعدون للشــهادة إننــي كنــت اعمــل بالورشــة وكنــت‬\n‫الســاعد األميــن ولــم اقــل إنــي املــك ثمانــون ألــف ريــال بــل قلــت أن والــدي‬\n‫خصــص لــي راتــب شــهري ثالثــة أالف ريــال وعنــد حســاب املــدة ســوف‬\n‫يكــون لــي مائــة وثمانــون ألــف ريــال ؛؛ أمــا بخصــوص خالتــي فأنــي‬\n‫أعطيتهــا مائــة وخمســون ألــف ريــال فقــط وكان هنــاك ســند عليهــا‬\n‫وليــس علــى زوجهــا واملبلــغ كان مــن قيمــة بيــع أرض اخلمــره مائتــان‬\n‫وخمســون ألــف ريــال وكانــت والدتــي علــى علــم وأخــذت منــي الســند‬\n‫لــك ال أقــوم بشــكوة أختهــا وســجنها وإنهــا أي والدتــي ســوف تأخــذ‬\n                              ‫منهــا املبلــغ بطريقتهــا وتقســمه علــى إخوتــي ؛؛‬\n‫ردا علــى البنــد اإلحــدى عشــر بأننــي وجهــت تهمــة لزوجهــا بأنــه ضــرب‬\n   ‫والدتــي هــذا غيــر صحيــح وموجــود لــدى فضيلتكــم مــا قلــت عنــه ؛؛‬\n‫ردا علــى البنــد الثانــي عشــر إنــا لــم اتهمــك بأنــك بعــت األرض احملجــر‬\n‫إلــى نفســك وأنتــي أجنبيــة بــل قلــت أنهــا بيعــت ل‪.......‬وهــو أجنبــي أيضــا‬\n‫ألنهــا بأســم أمــه الســعودية وقســم املبلــغ لكــم انتــم البنــات وهــذا مثبــت‬\n‫لــدى فضيلتكــم ‪ ،،‬ردا علــى البنــد الرابــع عشــر إنــا أطالبهــا بإحضــار‬\n‫‪ .....‬ويثبــت إمــام فضيلتكــم بأننــي بعتــه أي بضاعــة مــن مســتودعات‬\n‫والــدي ألنهــا هــي التــي تعــرف مــكان وجــوده يف الســعودية وعلى تواصل‬\n‫معــه وهــي تقــول أنهــا مســتعدة بإحضــار الشــهود غيــر ‪ ....‬نصــار ألنــه‬\n‫ســمع ولــم يــرى ؛ وكانــت الوالــدة محتاجــة لكميــة كبيــرة مــن املــال‬\n‫لعمــارة بيــت اجلبــل وأمــا بالنســبة حلقــوق املدعيــة‪ .....‬هــي وأخواتهــا البنات‬\n‫فإنــي أريــد مــن فضيلتكــم أن تســألها أيــن ورثنــا أنــا وأخــي ‪ .....‬مــن‬\n‫بيــت اجلبــل( مليــون وثالثمائــة ألــف دوالر أمريكــي ) أيــن حقنــا يف املــال‬\n‫الــذي أخذمتــوه مــن حســاب والدتنــا يف بنــك ‪ .....‬ببيــروت باخلدعة(مائتــي‬\n\n\n                                                                                         ‫‪320‬‬\n\f      ‫ألــف دوالر أمريكــي ) وأيــن ســبايك الذهــب التــي انزلهــا ‪ .....‬لبيــروت‬\n      ‫(أكثــر مــن مليــون دوالر أمريكــي) لقــد ضاعــت مــن بيــت الوالــدة يف‬\n      ‫بيــروت بطريقــة مشــبوهة ونطلــب مــن فضيلــة الشــيخ أن يقضــي بيننــا‬\n      ‫وبينــك وبــن ابنتــك ‪ .....‬بحلفــان اليمــن البينــة علــى مــن ادعــى واليمــن‬\n                                                                        ‫علــى مــن أنكــر‬\n      ‫وبعــرض ذلــك علــى املدعيــة قالــت ‪ :‬ليــس لــدي إجابــة علــى مــا ذكــر‪.‬‬\n      ‫وبســؤال الطرفــن هــل لديكمــا مــا تضيفانــه قــاال ‪ :‬ال ‪ .‬ثــم رفعــت‬\n      ‫اجللســة للتأمــل ‪ .‬ويف يــوم االثنــن املوافق‪1433/07/28‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 01 : 30‬وفيهــا حضــر الطرفــان‪ ،‬وقــررت املدعيــة قائلة‪:‬‬\n      ‫إننــي أطلــب احلكــم مبــا جــاء يف الدعــوى أصالــة عــن نفســي وبصفتــي‬\n      ‫وكيلــة عــن موكالتــي شــقيقاتي ‪.....‬و‪.....‬و‪.....‬و‪ ......‬وبعــد التأمــل ‪،‬‬\n      ‫طلبــت مــن املدعيــة البينــة علــى أن املدعــى عليــه ‪ .....‬هــو مــن بــاع األرض‬\n      ‫التــي باســم ‪ .....‬واململوكــة يف احلقيقــة للمــورث ‪ .....‬فقالــت ‪ :‬ليــس لــدي‬\n      ‫بينــة وأطلــب ميــن املدعــى عليــه ‪ .....‬علــى إنــكار ذلــك ‪ .‬وبســؤالها عــن‬\n      ‫صــورة صــك األرض لالستفســار عنــه لــدى كتابــة العــدل قالــت ‪ :‬ليــس‬\n      ‫لــدي نســخة منــه ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه ‪ .....‬قــال ‪ :‬إن أرض‬\n      ‫احملجــر ليســت باســم ‪ ، .....‬وليــس عليهــا صــك ‪ ،‬وإمنــا باســم ورثــة ‪، .....‬‬\n      ‫وقــد اشــتراها املــورث مبوجــب وثيقــة ‪ ،‬وهــي عبــارة عــن بيتــن شــعبيني‬\n      ‫ومســتودع ‪ ،‬وال أعــرف مبصيرهــا ‪ ،‬ومســتعد باحللــف علــى إنــكار‬\n      ‫بيعــي لــأرض وعلــم مبصيرهــا ‪ .‬ثــم حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال‬\n      ‫إلــه إال هــو أن األرض التــي تدعــي املدعــي أنهــا كانــت باســم ‪ .....‬و‪.....‬‬\n      ‫قــد اشــتراها والــدي املــورث مــن ورثــة نصيــف وليــس عليهــا صــك‪ ،‬ولــم‬\n      ‫أبــع تلــك األرض ولــم اســتلم ثمنهــا وال أعلــم مبصيرهــا ‪ .‬هكــذا حلــف‪.‬‬\n\n\n‫‪321‬‬\n\f‫وبســؤال املدعيــة البينــة علــى بيــع بضاعــة الورشــة ‪ ،‬وبكــم بيعــت ‪،‬‬\n‫ومــن الــذي باعهــا قالــت ‪ :‬لقــد بيعــت البضاعــة لــكل مــن ‪ ..... .....‬مــن‬\n‫قبــل املدعــى عليهمــا ‪ ،‬وال أعــرف بكــم بيعــت ‪ ،‬ولــدي شــاهد هــو ‪.....‬‬\n‫ولكنــه كبيــر يف الســن وال يســتطيع احلضــور للمحكمــة ‪ ،‬وأطلــب‬\n‫نــدب منــدوب مــن احملكمــة لســماع شــهادته ‪ .‬وبســؤالها عــن البينــة علــى‬\n‫أن بذمــة ‪ .....‬ســتون ألــف ريــال للمــورث ‪ ،‬ومقابــل مــاذا ومــن الــذي اســتلم‬\n‫هــذا الديــن قالــت ‪ :‬ليــس لــدي بينــة علــى ذلــك ‪ ،‬وأطلــب ميــن املدعــى‬\n‫عليــه ‪ .....‬علــى إنــكار ذلــك ‪ ،‬علمــا بــأن املبلــغ مقابــل بضاعــة ‪ ،‬وقــد‬\n‫اســتلمه ‪ ......‬وبعــرض ذلــك علــى املدعــى عليــه ‪ .....‬قــال ‪ :‬لــم اســتلم مــن‬\n‫‪ .....‬ســوى ثالثــون ألــف ريــال فقــط ‪ ،‬ومســتعد باحللــف علــى ذلــك ‪ .‬ثــم‬\n‫حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أننــي لــم اســتلم مــن ‪.....‬‬\n‫ســوى مبلــغ قــدره ثالثــون ألــف ريــال ‪ ،‬وذلــك مقابــل بضاعــة الورشــة‬\n‫ومســودع اخلمــرة ‪ .‬هكــذا حلــف ‪ .‬وبســؤال املدعيــة عــن الســيارات‬\n‫والرافعــة الشــوكية التــي ادعــت أنهــا مــن تركــة املــورث قالــت ‪ :‬لــدي‬\n‫شــهود ســأحضرهم يف اجللســة القادمــة ‪ .‬وبســؤال املدعــى عليــه ‪ .....‬عــن‬\n‫البينــة علــى أن املنتجــع الصيفــي الواقــع بجمهوريــة لبنــان واملســجل باســم‬\n‫الوالــدة ‪ .....‬للمــورث قــال ‪ :‬ليــس لــدي بينــة ‪ ،‬وأطلــب ميــن املدعيــة علــى‬\n‫اإلنــكار ‪ .‬وبعرضــه علــى املدعيــة قالــت ‪ :‬هــو ملــك للمــورث ‪ ،‬ومســجل‬\n‫باســم الوالــدة ‪ .‬فأفهمــت الطرفــن أن الدعــاوى املتعلقــة بعقــار خــارج‬\n‫اململكــة ال تختــص محاكــم اململكــة بنظرهــا بنــاء علــى املــادة ‪28‬‬\n‫مــن نظــام املرافعــات الشــرعية ‪ .‬وبســؤال املدعــى عليــه ‪ .....‬عــن الصــك‬\n‫الصــادر مــن هــذه احملكمــة والــذي يدعــي بأنــه صــادر علــى تركــة‬\n‫املــورث قــال‪ :‬ليــس لــدي نســخة منــه ‪ ،‬ويتعــذر ‪ .....‬إحضــاره ‪ .‬وبســؤال‬\n\n\n                                                                                        ‫‪322‬‬\n\f      ‫املدعــى عليــه ‪ .....‬عــن البينــة علــى بيعــه لــأرض املكونــة مــن ثــاث قطــع‬\n      ‫بثالثمائــة ألــف ريــال ‪ ،‬وأنــه ســلم والدتــه نصــف الثمــن والنصــف اآلخــر‬\n      ‫ســداد ديــن يف ذمــة املــورث قــال ‪ :‬ليــس لــدي بينــة وقــد بعتهــا قبــل حوالــي‬\n      ‫ثمانيــة وعشــرون عامــا ‪ ،‬وليــس لــدي نســخة مــن صــك العقــار وبســؤال‬\n      ‫املدعيــة عــن موضــوع الرهينــة قالــت ‪ :‬إنــه بعــد عودتــي مــن ســفر ذهبــت‬\n      ‫لبيــت مســتأجر للمــورث وإذا بــه مغلــق وليــس بــه ســوى بــراد وتلفــاز‬\n      ‫وغســالة قدميــة ال تعمــل جيــدا ‪ ،‬وال يوجــد غيــر ذلــك مــن عفــش البيــت ‪،‬‬\n      ‫وكان علــى املــورث قســط مــن األجــرة قــدره عشــرة آالف ريــال ‪ ،‬وقــد‬\n      ‫دفعتهــا عنــه ‪ .‬وبســؤال املدعيــة عــن الورقــة التــي تنــازل فيهــا املدعــى‬\n      ‫عليهمــا قالــت ‪ :‬هــي وثيقــة البيــع فقــط ‪ ،‬وقــد تنــازال عــن نصيبيهمــا‬\n      ‫للوالــدة ‪ .‬وبعرضــه علــى املدعــى عليهمــا قــاال ‪ :‬لقــد تنازلنــا بنصيبينــا‬\n                                                                                  ‫للوالــدة ‪.‬‬\n      ‫وبســؤال املدعــى عليــه ‪ .....‬عــن قيمــة عــدة الورشــة قــال ‪ :‬تســاوي عشــرة‬\n      ‫آالف ريــال حــن أخذتهــا قبــل حوالــي ثمانيــة وعشــرين عامــا ‪ ،‬والزالــت‬\n      ‫موجــودة حتــى اآلن ‪ ،‬وفريــزر أملونيــوم أملانــي الصنــع مــن شــركة ‪........‬‬\n      ‫ويقــدر بحوالــي خمســة عشــر ألــف ريــال آنذاك ‪ ،‬وثالثة دريــات وطاولة‬\n      ‫وملزمــة تقــدر تلــك جميعــا بخمســمائة ريــال يف ذلــك الوقــت ‪ ،‬وتلــك‬\n      ‫املعــدات ال تعمــل منــذ أكثــر مــن خمســة عشــر ســنة ‪ .‬هكــذا حلــف‪.‬‬\n      ‫وبســؤال املدعــى عليــه ‪ .....‬مــن اســتلم ثمــن البضاعــة التــي كانــت يف‬\n      ‫الورشــة وقــدره ســتون ألــف ريــال قــال ‪ :‬أنــا مــن اســتلمها مــن املشــتري ‪.....‬‬\n      ‫وســلمت الوالــدة مــن ثمنهــا ثالثــون ألــف ريــال ‪ .‬وبعرضــه علــى املدعيــة‬\n      ‫قالــت ‪ :‬غيــر صحيــح ‪ .‬وبطلــب البينــة مــن املدعــى عليــه ‪ .....‬علــى تســليم‬\n      ‫الوالــدة ثالثــون ألــف ريــال مــن ثمــن البضاعــة قــال‪ :‬ال‪ .‬وبعــرض اليمــن‬\n\n\n‫‪323‬‬\n\f‫علــى املدعيــة علــى عــدم علمهــا مبــا دفــع بــه املدعــى عليــه ‪ .....‬اســتعدت‬\n‫لذلــك ‪ ،‬ثــم حلفــت قائلــة ‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أننــي ال‬\n‫أعلــم بــأن املدعــى عليــه ســلم الوالــدة مــن ثمــن البضاعــة التــي كانــت‬\n‫يف ورشــة مورثنــا والتــي ذكــر بأنــه باعهــا بســتني ألــف ريــال شــيئا ‪.‬‬\n‫هكــذا حلفــت ‪ .‬ثــم طلبــت مــن املدعيــة إحضــار بقيــة املدعــن فوعــدت‬\n‫بذلــك يف اجللســة القادمــة‪ .‬ثــم رفعــت اجللســة لذلــك ‪ .‬ويف يــوم االثنــن‬\n‫املوافــق ‪1434/02/25‬ه ـ افتتحــت اجللســة الســاعة ‪ 08 : 30‬وفيهــا‬\n‫حضــر الطرفــان‪ ،‬وحضــرت املدعيــة‪ .....‬لبنانيــة اجلنســية مبوجــب جــواز‬\n‫ســفر رقــم‪ ،.....‬وبعــرض اليمــن علــى املدعيــة ‪ .....‬علــى عــدم علمهــا مبــا‬\n‫دفــع بــه املدعــى عليــه‪ .....‬مــن تســليمه لثمــن البضاعــة التــي كانــت يف‬\n‫ورشــة املــورث والتــي ذكــر أنــه باعهــا بســتني ألــف ريــال ‪ ،‬اســتعدت‬\n‫لذلــك‪ ،‬ثــم حلفــت قائلــة‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أننــي ال أعلــم‬\n‫بــأن املدعــى عليــه ‪ .....‬ســلم الوالــدة مــن ثمــن البضاعــة التــي كانــت يف‬\n‫ورشــة مورثنــا والتــي ذكــر بأنــه باعهــا بســتني ألــف ريــال شــيئا ‪ .‬هكــذا‬\n‫حلفــت‪ .‬وبســؤال املدعيــة عــن بقيــة الورثــة املدعــن قالــت ‪ :‬إنهــن خــارج‬\n‫اململكــة‪ .‬وبعــرض ذلــك علــى املدعــى عليــه‪ .....‬قــال ‪ :‬أكتفــي بيمــن‬\n‫مــن حضــر وحلــف ‪ .‬وبســؤال الطرفــن هــل لديكمــا مــا تضيفانــه قــاال‪:‬‬\n‫ال‪ .‬ثــم رفعــت اجللســة للتأمــل‪ .‬ويف يــوم الثالثــاء املوافــق ‪1434/02/26‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 02 : 15‬وفيهــا حضــر الطرفــان‪ ،‬وبســؤالهما‬\n‫عــن صــك حصــر ورثــة املــورث أبــرزت املدعيــة صــورة منــه‪ ،‬والصــادر‬\n‫مــن احملاكــم الشــرعية الســنية باجلمهوريــة اللبنانيــة واملــدون عليــه رقــم‬\n‫‪ ،492‬ومــدون عليــه أيضــا رقــم ‪ 494‬و ‪ 985/4/3‬واملــؤرخ يف ‪ 3‬نيســان‬\n‫‪1985‬م واملتضمــن وفــاة ‪ .....‬يف بيــروت بتاريــخ ‪1985/3/9‬م وانحصــر‬\n\n\n                                                                                        ‫‪324‬‬\n\f      ‫ورثته يف والدته ‪ .....‬وزوجته ‪ .....‬ويف أوالده منها وهم ‪ .....‬و‪ .....‬و‪ .....‬و‪.....‬‬\n      ‫و‪ .....‬وو‪ .....‬ال وارث لــه ســواهم ‪ .‬أه ـ ومت تزويــد أوراق املعاملــة بــه ‪ .‬فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ‪ ،‬وبنــاء علــى إقــرار املدعــى عليــه‬\n      ‫‪ .....‬احملــرر علــى أوراق الورشــة الهندســية ألعمــال احلديــد واألملونيــوم‬\n      ‫واملتضمــن أن األراضــي رقــم ‪ 724‬و ‪ 726‬و ‪ 729‬مبخطــط اجلبيــري‬\n      ‫والورشــة املشــتراة ‪ .....‬هــي ملــك للمــورث ‪ ،‬وهــي مســجلة باســم املدعــى‬\n      ‫عليــه فقــط ‪ ،‬وصــادق املدعــى عليــه ‪ .....‬علــى ذلــك اإلقــرار احملــرر ‪،‬‬\n      ‫ودفــع بــأن املــورث أوصــى لــه بالقطــع الثــاث مــن مخطــط اجلبيــري بعــد‬\n      ‫مماتــه‪ ،‬وأنكــرت املدعيــة ذلــك ‪ ،‬وهــي وصيــة باطلــة ملخالفتهــا احلديث‬\n      ‫(ال وصيــة لــوارث) رواه اإلمــام أحمــد وغيــره وبنــاء علــى إقــرار املدعــى‬\n      ‫عليــه ‪ .....‬ببيعــه القطــع الثــاث بثالثمائــة ألــف ريــال ‪ ،‬ثــم دفــع بتســليم‬\n      ‫والدتــه نصــف الثمــن ‪ ،‬وأنكــرت املدعيــة ذلــك‪ ،‬كمــا دفــع بســداد‬\n      ‫ديــون علــى املــورث بالنصــف الــذي اســتلمته مــن ثمــن القطــع ‪ ،‬وأنكــرت‬\n      ‫املدعيــة ذلــك ‪ ،‬ولــم يقــم البينــة عليــه وحلفــت املدعيــة علــى إنــكاره ‪،‬‬\n      ‫وعــارض كالمــه هــذا مــا ســبق بــأن القطــع قــد أوصــى لــه مورثــه بهــا ‪،‬‬\n      ‫وهــذا تناقــض يــدل علــى عــدم صدقــه ‪ ،‬وبنــاء علــى إقــرار املدعــى عليــه‬\n      ‫‪ .....‬باســتالمه مبلــغ خمســة آالف ريــال مــن صبــوح النعمانــي وأنــه لــم‬\n      ‫يســلم الورثــة منــه شــيئا ‪ ،‬وبنــاء علــى شــهادة الشــاهد ‪ ..... .....‬بــأن املدعى‬\n      ‫عليهمــا ‪ .....‬و‪ .....‬قــد تنــازال عــن نصيبهمــا يف األرض التــي اشــتراها مــن‬\n      ‫الورثــة مبائــة وعشــرة آالف ريــال إلخوتهمــا ‪ ،‬وبنــاء علــى اإلقــرار احملــرر‬\n      ‫بذلــك ‪ ،‬وقــد صــادق املدعــى عليهمــا ‪ .....‬علــى ذلــك ‪ ،‬وبنــاء علــى إقــرار‬\n      ‫املدعــى عليــه ‪ .....‬باســتالمه مبلــغ مائتــا ألــف ريــال مــن الســيدة ‪، .... /‬‬\n      ‫ودفــع بتســليمه لوالدتهــم دون بينــة ‪ ،‬وأنكــرت املدعيــة ذلــك ‪ ،‬وبنــاء‬\n\n\n‫‪325‬‬\n\f‫علــى إقــرار املدعــى عليــه ‪ .....‬باســتالمه مبلــغ ثالثــون ألــف ريــال مــن‬\n‫الســيد ‪ .....‬وأنكــر مــا عــدا ذلــك ‪ ،‬ولــم تقــم املدعيــة البينــة علــى ذلــك‪،‬‬\n‫وحلــف املدعــى عليــه علــى إنــكار اســتالمه مــن ‪ .....‬أكثــر مــن ذلــك ثــم‬\n‫عــاد فأقــر يف جلســة أخــرى بأنــه اســتلم مبلغــا قــدره ســتون ألــف ريــال من‬\n‫‪ ، .....‬ودفــع بتســليم والدتــه ثالثــون ألــف ريــال منــه ‪ ،‬وأنكــرت املدعيــة‬\n‫ذلــك ‪ ،‬ولــم يقــم البينــة عليــه وحلفــت املدعيــة علــى إنــكار ذلــك ‪ ،‬وبنــاء‬\n‫علــى إنــكار املدعــى عليــه ‪ .....‬بيــع أرض ‪ .....‬وعــدم علمــه مبــا آلــت إليــه‬\n‫ولــم تقــم املدعيــة البينــة علــى مــا أنكــره ‪ ،‬وحلــف علــى إنــكاره ‪ ،‬وبنــاء‬\n‫علــى مــا دفــع بــه املدعــى عليــه ‪ .....‬مــن وجــود ديــون علــى التركــة ‪،‬‬\n‫وأنكــرت املدعيــة ذلــك ‪ ،‬ولــم يقــم البينــة عليــه ‪ ،‬وحلفــت املدعيــة علــى‬\n‫إنــكاره ‪ ،‬وبنــاء علــى إقــرار املدعــى عليــه ‪ .....‬ألخــذه عــدة الورشــة وأنهــا‬\n‫تســاوي عشــرة آالف ريــال حــن أخذهــا ‪ ،‬ثــم أقــر بــأن املعــدات هــي‬\n‫منشــارين أملونيــوم مــن شــركة (كلــن بــاخ) قيمــة الواحد منهما خمســة‬\n‫آالف ريــال ‪ ،‬وفريــزر أملونيــوم أملانــي مــن شــركة ســيدار ويقــدر بحوالــي‬\n‫خمســة عشــر ألــف ريــال ‪ ،‬وثــاث دريــات وطاولــة ملزمــة تقــدر جميعــا‬\n‫بخمســمائة ريــال ‪ ،‬وتعــذر تقديرهــا عــن طريــق أهــل اخلبرة بحســب إفادة‬\n‫املدعيــة ‪ ،‬وطلبــت ميــن املدعــى عليــه ‪ .....‬علــى ذلــك ‪ ،‬فحلــف عليــه ‪،‬‬\n‫وحلديــث (علــى اليــد مــا أخــذت حتــى تؤديــه) رواه األربعــة ‪ ،‬وحلديــث (أن‬\n‫النبــي صلــى اهلل عليــه وســلم قضــى أن اليمــن علــى املدعــى عليــه) رواه‬\n‫البخــاري ‪ ،‬وحلديــث (البينــة علــى املدعــي واليمــن علــى املدعــى عليــه)‬\n‫رواه الترمــذي ‪ ،‬قــال أبــو عيســى ‪ :‬العمــل عنــد أهــل العلــم مــن أصحــاب‬\n‫النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن‬\n‫علــى املدعــى عليــه ‪ ،‬لذلــك كلــه ‪ ،‬فقــد حكمــت علــى املدعــى عليــه‬\n\n\n                                                                                        ‫‪326‬‬\n\f      ‫‪ .....‬دفــع مبلــغ قــدره مائــة وثمانيــة عشــر ألفــا وخمســة وخمســون ريــاال‬\n      ‫وخمســة وخمســون هللــة للمدعيــات ‪ ، ..... ..... .....‬ونصيــب كل مدعيــة‬\n      ‫مــن ذلــك املبلــغ مبلغــا قــدره ثالثــة وعشــرون ألفــا وســتمائة وأحــد عشــر‬\n      ‫ريــاال وأحــد عشــر هللــة ‪ ،‬وحكمــت علــى املدعــى عليــه ‪ .....‬دفــع مبلــغ‬\n      ‫قــدره مائــة وأربعــة عشــر ألفــا وثالثمائــة وســبعة عشــر ريــاال وخمســة‬\n      ‫عشــر هللــة للمدعيــات ‪ ، ..... ..... ..... .....‬ونصيــب كل مدعيــة مــن ذلــك‬\n      ‫املبلــغ مبلغــا قــدره اثنــان وعشــرون ألفــا وثمامنائــة وثالثــة وســتون ريــاال‬\n      ‫وثالثــة وأربعــون هللــة ‪ ،‬ورددت مــا عــدا ذلــك مــن طلبــات لعــدم ثبــوت‬\n      ‫موجبــه ‪ ،‬وأفهمــت املدعــى عليهمــا بــأن لهمــا الرجــوع علــى والدتهمــا‬\n      ‫فيمــا ادعيــا تســليمه لهــا ‪ .‬وبــه حكمــت ‪ .‬وبــه قنعــت املدعيــة ‪ ،‬وقــرر‬\n      ‫املدعــى عليهمــا االعتــراض ‪ ،‬وجــرى تســليمهما نســخة مــن احلكــم‬\n      ‫وإفهامهمــا بــأن لهمــا احلــق يف االعتــراض عليــه خــال ثالثــن يومــا‬\n      ‫‪ ،‬وإال ســقط حقهمــا يف االعتــراض ‪ ،‬واكتســب احلكــم القطعيــة ‪.‬‬\n      ‫وأقفلــت اجللســة الســاعة ‪ . 02 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/26‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة ففــي يــوم االثنــن املوافــق ‪1434/06/05‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 08 : 45‬وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫بخطــاب رئيســها رقــم ‪ 33122398‬وتاريــخ ‪1434/5/27‬ه ـ ومرفــق بــه‬\n      ‫القــرار رقــم ‪ 34216327‬وتاريــخ ‪1434/5/19‬ه ـ واملتضمــن أنــه (تقــرر‬\n      ‫باألكثريــة إعادتهــا لفضيلتــه ملالحظــة مــا يلــي ‪ -1 :‬تعديــل الشــاهد‬\n      ‫مــا دام شــهادته موصلــة ‪ -2‬املــورث لــه ورثــة خــاف املدعيــات فأيــن‬\n      ‫نصيبهــم ونصيــب املدعــى عليهمــا ‪ -3‬تصحيــح األخطــاء اإلمالئيــة‬\n\n\n‫‪327‬‬\n\f‫واللغويــة واملطبعيــة وهــي كثيــرة جــدا) أه ـ وعليــه أجيــب أصحــاب‬\n‫الفضيلــة فيمــا يخــص املالحظــة األولــى فــإن تعديــل الشــاهد لــم يــدل‬\n‫عليهــا دليــل شــرعي صحيــح ‪ ،‬والرســول صلــى اهلل عليــه وســلم كان‬\n‫يقبــل شــهادة الشــاهد دون أن يطلــب تعديلــه ‪ ،‬والغــرض مــن التعديــل‬\n‫أن يكــون املعــدل للشــاهد معــروف احلــال لــدى القاضــي ‪ ،‬وإال فــإن‬\n‫تعديــل الشــاهد مــن قبــل مجهــول احلــال لــدى القاضــي يوجــب الــدور ‪،‬‬\n‫واألصــل يف املســلم العدالــة ‪ ،‬ولــم يطعــن املدعــى عليهمــا بالشــاهد ‪،‬‬\n‫ويف حــال اســتراب ناظــر القضيــة مــن الشــاهد فيتوجــه طلــب تعديلــه ‪،‬‬\n‫وفيمــا يخــص املالحظــة الثانيــة فــإن الدعــوى تنحصــر علــى املدعيــات‬\n‫‪ ،‬فــا يحكــم لغيرهــن ‪ ،‬ونظــر القاضــي قاصــر علــى طلــب املدعــي‬\n‫بالصفــة التــي تخولــه ‪ ،‬فقــد يقبــل غيرهــن بذلــك ‪ ،‬فمــا وجــه احلكــم‬\n‫لهــم مبــا لــم يطالبــوا بــه ‪ ،‬وأمــا نصيــب املدعــى عليهمــا فقــد مت احتســابه‬\n‫مــن مجمــل مــا دار عليــه اخلــاف فلــم يلــزم املدعــى عليهمــا بدفع شــيء إال‬\n‫نصيــب املدعيــات فقــط ‪ ،‬وفيمــا يخــص املالحظــة الثالثــة فمــا وقــع مــن‬\n‫أخطــاء إمنــا هــي ممــا قدمــه الطرفــان مبذكراتهــم ‪ ،‬والتــي يتــم تقدميهــا‬\n‫يف أوعيــة إلكترونيــة ويتــم رصدهــا كمــا هــي ‪ ،‬ويصعــب تدقيــق كل‬\n‫مذكــرة يتقــدم بهــا األطــراف ‪ ،‬الســيما مــع طولهــا ‪ ،‬وعليــه فلــم يظهــر‬\n‫لــي خــاف مــا حكمــت بــه ‪ ،‬وقــررت إحلــاق ذلــك علــى صــك احلكــم‬\n‫وســجله ‪ ،‬وإعــادة املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم بعــد‬\n‫اإلجــراء األخيــر ‪ .‬وأقفلــت اجللســة الســاعة ‪ . 09 : 00‬وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                             ‫‪1434/06/05‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n\n\n                                                                                       ‫‪328‬‬\n\f      ‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة الثانيــة مبحكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بجــدة املســاعد برقــم ‪33122398‬‬\n      ‫وتاريــخ ‪1434/6/7‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫‪ .....‬القاضــي باحملكمــة العامــة بجــدة واملســجل بعــدد ‪3448838‬وتاريــخ‬\n      ‫‪1434/2/26‬ه ـ و املتضمــن دعــوى‪ ..... /‬ضــد‪ ...../‬و ‪ .....‬واحملكــوم فيــه‬\n                                                                    ‫مبــا دون باطنــه ‪.‬‬\n      ‫وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n      ‫باألكثريــة املوافقــة علــى احلكــم واهلل املوفــق‪ .‬علــى نبينــا محمــد وعلــى‬\n                                                               ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪329‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":299,"source_page_end":329,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ac8a8cc7525af54376c523acaa6e55f8dcdefd85b4b73d4b6c7de60ecc3dd8ce","normalized_text_hash":"1778a1ec9682d1c6f8deead9c7c6439def25745f0730d5d67490a135e1450a5b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p299-3448838"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
